// بيانات السور
Object.assign(quranData, {
    11: { // سورة هود
        name: "هود",
        basmalaTafsir: ``,
        verses: [
            { text: "الٓر كِتَٰبٌ أُحْكِمَتْ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ", tafsir: `رموز بين الله والخلق ، أو أن من جنس « أ ، ل ، ر » ( كِتابٌ أُحْكِمَتْ آياتُهُ ) فكل آية من آياته محكمة متينة ليست رخوة لا تلائم الواقع والحياة ، وتكون غير صالحة لكل زمان أو مكان ، بل إنها كالأحجار الكريمة المستحكمة التي لا يدخلها نقص ورخاوة وتفكك ، ( ثُمَّ فُصِّلَتْ ) كل آية قد وضعت موضعها المناسب لها ، كما يفصل الكتاب إلى أبواب وفصول ، فليس نظمها مهلهلا غير منظم ، كالبناء المحكم ذي الأحجار والأدوات القديمة والذي ينظم ويفصّل تفصيلا منسجما صحيحا دقيقا ، فالآية محكمة بذاتها ، منظمة في مكانها. وهو ( مِنْ لَدُنْ ) أي من عند إله ( حَكِيمٍ ) في أفعاله يضع الأشياء في مواضعها ، فلا يفعل شيئا اعتباطا وعبثا وإنما بالحكمة والصلاح ( خَبِيرٍ ) عليم بالأشياء ، فإن الحكمة غير العلم ، إذ ربما حكيم غير عالم ، كما أنه ربما عالم غير حكيم.` },
            { text: "أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنَّنِى لَكُم مِّنْهُ نَذِيرٌ وَبَشِيرٌ", tafsir: `تقديره « لأن لا تعبدوا » ، فهو متعلق ب « أحكمت » أي أنزل الكتاب المحكم المفصل لعلّة أن لا تعبدوا ، فهو منصوب محلا ، كما تقول : « كتبت إليك أن تتعلم » ( إِلَّا اللهَ ) فهو وحده المستحق للعبادة والطاعة لا إله سواه ( إِنَّنِي لَكُمْ ) أيها الناس ( مِنْهُ ) من طرفه سبحانه ( نَذِيرٌ ) أنذر العاصين بالعقاب ( وَبَشِيرٌ ) أبشر المطيعين بالثواب. وكان ذكر الإنذار قبل التبشير ، للزوم تطهير النفس عن الكفر والمعاصي أولا ثم تحليتها بالفضائل ، قالوا : ولذا قدم النفي على الإثبات في « لا إله إلّا الله» . وَأَنِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ يُمَتِّعْكُمْ مَتاعاً حَسَناً إِلى أَجَلٍ مُسَمًّى وَيُؤْتِ كُلَّ ذِي فَضْلٍ فَضْلَهُ وَإِنْ تَوَلَّوْا فَإِنِّي أَخافُ عَلَيْكُمْ عَذابَ يَوْمٍ كَبِيرٍ (3)` },
            { text: "وَأَنِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُمَتِّعْكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٍ مُّسَمًّى وَيُؤْتِ كُلَّ ذِى فَضْلٍ فَضْلَهُۥ وَإِن تَوَلَّوْا۟ فَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ كَبِيرٍ", tafsir: `اطلبوا غفرانه فيما سلف من ذنوبكم ( ثُمَّ تُوبُوا ) ارجعوا ( إِلَيْهِ ) في أموركم ، فإن الاستغفار والتوبة أمران ، فإن الأول تطهير ، يمكن أن يرجع الإنسان ـ بعده ـ إلى الله ويمكن أن يرتكس في الذنوب ، وإن كان الغالب استعمال كل واحد منهما ويراد به الاثنان. والحاصل أن الإنسان يحتاج إلى تطهير ما سبق ، وطهارة المستقبل ، فالاستغفار وضع للأول ، والتوبة للثاني ، وإن استلزم كل واحد الآخر ( يُمَتِّعْكُمْ مَتاعاً حَسَناً ) فإنه إن استغفرتم وتبتم تفضّل عليكم بالمتاع الحسن من رزق وأثاث ورياش ، وحسنه بجماله الذاتي وأن لا يكدّره قلق ومرض وما أشبههما ( إِلى أَجَلٍ مُسَمًّى ) وقت مسمى عنده ، وهو منتهى عمركم ( وَيُؤْتِ كُلَّ ذِي فَضْلٍ فَضْلَهُ ) فمن أوتي بالفضل عن الاستغفار والتوبة آتاه الله سبحانه فضلا وزيادة على المتاع الحسن ، فالمطيع له المتاع الحسن والمطيع الذي يزيد في طاعته على أصل الواجب بالمندوبات ونحوها يعطى أزيد على قدر فضله ( وَإِنْ تَوَلَّوْا ) أي تعرضوا وأصله « تتولوا » بحذف إحدى التاءين ـ على القاعدة ـ و « التولي » بعدم الإيمان أو عدم الاستغفار والتوبة ( فَإِنِّي أَخافُ عَلَيْكُمْ عَذابَ يَوْمٍ كَبِيرٍ ) هو يوم القيامة ، الذي تعظم الأهوال فيه وتكبر ، فإن كان التولي بالمعصية كان الخوف بمعناه ، فإن العاصي يخاف عليه ، لا إنه يقطع بعذابه ، لاحتمال خلاصه بالعفو والشفاعة ، وإن كان التولي بالكفر كان لفظة « الخوف » من التواضع في الكلام لمن لا يعتقد. إِلَى اللهِ مَرْجِعُكُمْ وَهُوَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (4) أَلا إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا مِنْهُ أَلا حِينَ يَسْتَغْشُونَ ثِيابَهُمْ يَعْلَمُ ما يُسِرُّونَ وَما يُعْلِنُونَ إِنَّهُ عَلِيمٌ بِذاتِ الصُّدُورِ (5)` },
            { text: "إِلَى ٱللَّهِ مَرْجِعُكُمْ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `رجوعكم ، ومعناه إلى حسابه وجزائه رجوعكم بعد الموت ( وَهُوَ ) سبحانه ( عَلى كُلِّ شَيْءٍ قَدِيرٌ ) يقدر على إحياء الأموات ، ومحاسبتهم وجزائهم وقد اشتملت هذه الآيات على التوحيد والنبوة والمعاد ، وتعديل السلوك في الحياة. [6] ويواجه هذا الكتاب الحكيم وهذا الرسول البشير النذير جماعة من الناس بالإعراض بحني رؤوسهم وثني صدورهم كما يفعل كل من يريد أن يخفي نفسه منك ولا يعتني بك وبكلامك ( أَلا ) فلينتبه السامع ( إِنَّهُمْ ) أي الكفار ( يَثْنُونَ صُدُورَهُمْ ) يطوونها ويدخلون بعض أجزائها في بعض كالمطرق الشديد الإطراق ( لِيَسْتَخْفُوا ) يطلبون بذلك تخفيهم ( مِنْهُ ) من الله أو من الرسول صلى‌الله‌عليه‌وآله‌وسلم ( أَلا ) فلينتبه السامع ( حِينَ يَسْتَغْشُونَ ثِيابَهُمْ ) يتغطون بثيابهم ، فإن الإنسان المعرض يتلفّح بثوبه ، إما بأن يضعه على رأسه ، أو يخفي به بعض جسده ، ولعل بعضهم كان يفعل ذلك إظهارا لإعراضه حين يقرأ الرسول صلى‌الله‌عليه‌وآله‌وسلم القرآن. ( يَعْلَمُ ) الله ( ما يُسِرُّونَ ) يخفون ( وَ ) يعلم الله ( ما يُعْلِنُونَ ) عند ما يستغشون ثيابهم ( إِنَّهُ ) سبحانه ( عَلِيمٌ بِذاتِ الصُّدُورِ ) أي الصفات والأسرار الكامنة فيها ، فلا ينفعهم ثني الصدور واستغشاء الثياب في تخفيهم عليه سبحانه ، فإنه العالم بكل شيء. تقريب القران الى الأذهان من آية 7 من سورة هود إلى آية 53 من سورة يوسف بسم الله الرّحمن الرّحيم الحمد لله رب العالمين ، والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين. وَما مِنْ دَابَّةٍ فِي الْأَرْضِ إِلاَّ عَلَى اللهِ رِزْقُها وَيَعْلَمُ مُسْتَقَرَّها وَمُسْتَوْدَعَها كُلٌّ فِي كِتابٍ مُبِينٍ (6) وَهُوَ الَّذِي خَلَقَ السَّماواتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ وَكانَ عَرْشُهُ عَلَى الْماءِ [7] إنه سبحانه عالم بكل شيء ، ولو لم يعلم كل شيء لم يقدر على إيصال الرزق لكل دابة صغيرة أو كبيرة ( وَما مِنْ دَابَّةٍ فِي الْأَرْضِ ) « الدابة » كل حيوان يدبّ على وجه الأرض ، وهذا من باب المثال ، وإلا فمن الحيوانات ما لا يدب ، كما أن منها ما ليس في الأرض ( إِلَّا عَلَى اللهِ رِزْقُها ) ولعلّ تخصيص الرزق بالذكر ، للزومه عدة أمور من علم وحكمة وقدرة وغيرها ، ولتكرره كل يوم ـ غالبا ـ ( وَيَعْلَمُ مُسْتَقَرَّها ) مستقر تلك الدواب ( وَمُسْتَوْدَعَها ) ولعلّ الأول عبارة عن كل محل تقرّ فيه ، ولو لم يكن مكانها ، والثاني محلها الذي هو عيشها ومنزلها. وقيل في ذلك أقوال أخرى ( كُلٌّ فِي كِتابٍ مُبِينٍ ) أي إن جميع ذلك بالإضافة إلى أنها معلومة لله سبحانه مدرجة في كتاب واضح ، ولعله هو اللوح المحفوظ.` },
            { text: "أَلَآ إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا۟ مِنْهُ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ", tafsir: `` },
            { text: "وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ إِلَّا عَلَى ٱللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا كُلٌّ فِى كِتَٰبٍ مُّبِينٍ", tafsir: `` },
            { text: "وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُۥ عَلَى ٱلْمَآءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِنۢ بَعْدِ ٱلْمَوْتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ", tafsir: `سبحانه ( الَّذِي خَلَقَ السَّماواتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ) لا أكثر ولا أقل ، وقد جرت حكمة الله سبحانه على الخلق التدريجي كما نشاهده في النبات والحيوان والإنسان ، وكذلك كان خلق السماء والأرض ، وخصوصية ستة أيام كخصوصية الآماد المعينة في سائر الأشياء كتسعة أشهر مثلا للجنين. والظاهر أن المراد : مقدار ستة أيام ، إذ لم يكن في ذلك الوقت يوم بمعناه الحالي ( وَكانَ عَرْشُهُ عَلَى الْماءِ ) فقد كان سلطانه سبحانه وتصرفه ـ وهو المتبادر من العرش كما يقال : عرش الملك الفلاني من البلاد الكذائية إلى البلاد الكذائية ـ على لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلاً وَلَئِنْ قُلْتَ إِنَّكُمْ مَبْعُوثُونَ مِنْ بَعْدِ الْمَوْتِ لَيَقُولَنَّ الَّذِينَ كَفَرُوا إِنْ هذا إِلاَّ سِحْرٌ مُبِينٌ (7) وَلَئِنْ أَخَّرْنا عَنْهُمُ الْعَذابَ إِلى أُمَّةٍ مَعْدُودَةٍ الماء ، قبل خلق السماوات والأرض ، فإن الله قبل خلق السماوات والأرض خلق ماء ثم كوّن الكون ، وأما لم ذلك ؟ فعلمه لدى علّام الغيوب ( لِيَبْلُوَكُمْ ) يختبركم ويمتحنكم ( أَيُّكُمْ أَحْسَنُ عَمَلاً ) إن خلق السماوات والأرض كان استعدادا لإمكان خلق الإنسان ليمتحن ، كما قال صلى‌الله‌عليه‌وآله‌وسلم : « خلق الأشياء لأجلك » . أما خصوصية « الستة » وكون العرش على الماء ، فهو من توابع الخلق لأجل الامتحان ، لا من صميمه ـ كما يظهر لنا من السياق ـ كأن تقول : « هيأت لولدي الدار الفلانية في سنة ، لأسكنه فيها » . ثم إن ذلك كان لأجل امتحان البشر وليظهر أيهم أحسن عملا ، حتى يكون الجزاء وفق الامتحان ، ومن الغريب ـ إذن ـ أن ينكر أحد الجزاء ( وَلَئِنْ قُلْتَ ) يا رسول الله لهؤلاء الكفار : ( إِنَّكُمْ مَبْعُوثُونَ مِنْ بَعْدِ الْمَوْتِ ) للحساب والجزاء ( لَيَقُولَنَّ الَّذِينَ كَفَرُوا ) بالله ورسله ( إِنْ هذا ) أي : ما هذا القول حول البعث ( إِلَّا سِحْرٌ مُبِينٌ ) أي تمويه واضح ، لا حقيقة له. [9] إنهم يكذبون بكل شيء لم يروه ، وقد وعدناهم بالعذاب لكنه تأخر عنهم ، فيستعجلونه استهزاء ، وينكرونه كما ينكرون البعث ( وَلَئِنْ أَخَّرْنا عَنْهُمُ الْعَذابَ ) الذي يستحقونه بتكذيبهم للرسول وإنكارهم لله سبحانه ( إِلى أُمَّةٍ مَعْدُودَةٍ ) « الأمة » بمعنى « الحين » أي إلى أجل مسمّى لَيَقُولُنَّ ما يَحْبِسُهُ أَلا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفاً عَنْهُمْ وَحاقَ بِهِمْ ما كانُوا بِهِ يَسْتَهْزِؤُنَ (8) وَلَئِنْ أَذَقْنَا الْإِنْسانَ مِنَّا رَحْمَةً ثُمَّ نَزَعْناها مِنْهُ إِنَّهُ لَيَؤُسٌ كَفُورٌ (9) ووقت معين عدّت أيامه في علم الله سبحانه لمصالح خاصة ( لَيَقُولُنَ ) على وجه الاستهزاء : ( ما يَحْبِسُهُ ) ؟ أي : أيّ شيء يؤخر هذا العذاب الموعود عنّا إن كان الوعد حقا ، فتأخيره دليل على كذبه ( أَلا ) فلينتبه السامع ( يَوْمَ يَأْتِيهِمْ ) العذاب ( لَيْسَ مَصْرُوفاً عَنْهُمْ ) لا يقدر أحد على صرفه عنهم ، بل يأخذهم ويهلكهم ( وَ ) حينذاك ( حاقَ بِهِمْ ) أحاط بهؤلاء المكذبين ( ما ) أي العذاب الذي ( كانُوا بِهِ يَسْتَهْزِؤُنَ ) فلا منجي لهم ولا مهرب. أما تأخير العذاب فلأجل إيمان من يؤمن ، ممن يعلم الله إيمانه منهم ، ولينشأ بعض الذراري من أصلاب الكفار ، وإنما يأخذ الله سبحانه بعذاب الاستئصال من لم يجد منه خيرا إلى الأبد. [10] إن الإنسان عجول في حكمه وتقلبه فهو يستعجل العذاب ، كما أنه ييأس لمجرد نزول البلية ، والفخر بمجرد نزول النعمة ( وَلَئِنْ أَذَقْنَا الْإِنْسانَ مِنَّا رَحْمَةً ) أنزلنا إليه رحمة ذاقها ، من صحة أو مال أو ولد أو نحوها. والمراد ب « الذوق » هنا مطلق الإدراك ، فإنه يستعمل فيما يتذوق باللسان ، وفيما يدرك بالحواس الظاهرة ، وفيما يدرك و لو بالحواس الباطنة ، كما أن الرؤية كذلك ، تقول : رأيت وجه زيد ، ورأيت خشونة الحصير ، ورأيت الله أكبر كل شيء ( ثُمَّ نَزَعْناها ) أي سلبنا تلك النعمة ( مِنْهُ ) من الإنسان لمصلحة اقتضته ( إِنَّهُ ) أي الإنسان ( لَيَؤُسٌ ) ذو يأس وقنوط ( كَفُورٌ ) يكفر بالله وييأس من روحه ورحمته. وَلَئِنْ أَذَقْناهُ نَعْماءَ بَعْدَ ضَرَّاءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ السَّيِّئاتُ عَنِّي إِنَّهُ لَفَرِحٌ فَخُورٌ (10) إِلاَّ الَّذِينَ صَبَرُوا وَعَمِلُوا الصَّالِحاتِ أُولئِكَ لَهُمْ مَغْفِرَةٌ وَأَجْرٌ كَبِيرٌ (11)` },
            { text: "وَلَئِنْ أَخَّرْنَا عَنْهُمُ ٱلْعَذَابَ إِلَىٰٓ أُمَّةٍ مَّعْدُودَةٍ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ", tafsir: `` },
            { text: "وَلَئِنْ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةً ثُمَّ نَزَعْنَٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسٌ كَفُورٌ", tafsir: `` },
            { text: "وَلَئِنْ أَذَقْنَٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّىٓ إِنَّهُۥ لَفَرِحٌ فَخُورٌ", tafsir: `جعلناه يتذوق ويدرك ، ( نَعْماءَ بَعْدَ ضَرَّاءَ مَسَّتْهُ ) أي بعد بلاء أصابه ( لَيَقُولَنَ ) الإنسان عند نزول النعماء به : ( ذَهَبَ السَّيِّئاتُ ) أي الأمور التي تسوء صاحبها من فقر ومرض وعقم وما أشبه ( عَنِّي ) فكأنه أمر عادي طبيعي لا يشكر الله على ذهابها ، ولا يرى أنه هو الذي أذاقه النعمة ( إِنَّهُ لَفَرِحٌ فَخُورٌ ) يفرح ويفخر على الناس فلا يصبر عند البلية ولا يشكر عند النعمة ، إنه عجول في جميع أحواله في نعمة كان أم في نقمة.` },
            { text: "إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ", tafsir: `على الشدة فلم يكفروا ، وعلى النعمة فلم يبطروا ، فإن النعمة تحتاج إلى الصبر ، كما أن البلية تحتاج إليها ، ورب إنسان أنعم الله عليه فلم يصبر على النعمة حتى بدّلها كفرا ( وَعَمِلُوا الصَّالِحاتِ ) فلم يعملوا بالسيئات عند النعمة أو البلية ( أُولئِكَ ) الصابرون ( لَهُمْ مَغْفِرَةٌ ) غفران ذنوبهم ( وَأَجْرٌ كَبِيرٌ ) في الدنيا بالسعادة ، وفي الآخرة بالجنة والرحمة والرضوان. [13] ما هو موقف الرسول صلى‌الله‌عليه‌وآله‌وسلم أمام هؤلاء الكفار الذين يقولون عن البعث أنه سحر مبين ، ويكفرون عند الشدة ، ويبطرون عند النعمة ؟ إنه لا بد وأن يضيق صدره ، خصوصا وأنهم يطلبون منه ما لا يرتبط بالرسالة تعنّتا. و قد روي أن رؤساء مكة من قريش أتوا رسول الله صلى‌الله‌عليه‌وآله‌وسلم فقالوا : فَلَعَلَّكَ تارِكٌ بَعْضَ ما يُوحى إِلَيْكَ وَضائِقٌ بِهِ صَدْرُكَ أَنْ يَقُولُوا لَوْ لا أُنْزِلَ عَلَيْهِ كَنْزٌ أَوْ جاءَ مَعَهُ مَلَكٌ يا محمد ! إن كنت رسولا فحوّل لنا جبال مكة ذهبا ، أو ائتنا بملائكة يشهدون لك بالنبوة. فنزلت هذه الآية (1) . وفي التأويل ، ورد عن الإمام الصادق عليه‌السلام : « أن رسول الله صلى‌الله‌عليه‌وآله‌وسلم قال لعلي عليه‌السلام : إني سألت ربي أن يؤاخي بيني وبينك ففعل ، وسألت ربي أن يجعلك وصيّي ففعل ، فقال بعض القوم : والله لصاع من تمر في شنّ بال أحب إلينا مما سأل محمد ربّه ، فهلّا سأله ملكا يعضده على عدوه ، أو كنزا يستعين به على فاقته. فنزلت (2) : ( فَلَعَلَّكَ ) يا رسول الله ( تارِكٌ بَعْضَ ما يُوحى إِلَيْكَ ) من التنقيص لآلهة المشركين وتسخيف عقائدهم وأعمالهم ، كأن لا تقرأ بعض آي القرآن التي فيها هذه الأمور ، خوفا من أذى الكفار واستهزائهم ( وَضائِقٌ بِهِ ) بذلك الوحي ( صَدْرُكَ ) فإن الإنسان إذا همّه أمر ارتفعت درجة حرارته مما يتطلب هواء كثيرا ، وفي النفس العميق تنتفخ الرئة كثيرا مما يسبب ضيق الصدر عند انتفاخها ( أَنْ يَقُولُوا ) أي كراهة أن يقول الكفار : ( لَوْ لا أُنْزِلَ عَلَيْهِ ) أي لماذا لم ينزل على الرسول صلى‌الله‌عليه‌وآله‌وسلم ( كَنْزٌ ) من المال ليستعين به على فقره ( أَوْ جاءَ مَعَهُ مَلَكٌ ) ليشهد بصدقه ، فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم كان إذا ذكر آلهتهم ونقائصهم قابلوه بالاستهزاء بمثل هذه الأمور « لو لا أنزل عليه كنز أو جاء معه ملك » يريدون بذلك كفّه عن بعض الوحي. ( 1) بحار الأنوار : ج 9 ص 103. ( 2) الكافي : ج 8 ص 378. إِنَّما أَنْتَ نَذِيرٌ وَاللهُ عَلى كُلِّ شَيْءٍ وَكِيلٌ (12) أَمْ يَقُولُونَ افْتَراهُ قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِثْلِهِ مُفْتَرَياتٍ وهنا يرشده سبحانه أنه لا يحتاج إلى كنز أو ملك ( إِنَّما أَنْتَ نَذِيرٌ ) تنذر الناس ، والمنذر لا يحتاج إلى كنز ، وإنما طالب المال يحتاج إليه ، كما أنه لا يحتاج إلى الملك ، بل إنه بحاجة إلى التصديق ، وقد كانت معه صلى‌الله‌عليه‌وآله‌وسلم أدلة الصدق ، من المعجزات الباهرات ( وَاللهُ عَلى كُلِّ شَيْءٍ وَكِيلٌ ) فهو الموكل بهم ، والمتصرف في أمورهم ، و « الوكيل » هو العارف بالصلاح دونهم ، فما يفعله من عدم تلبية مثل هذه الخوارق إنما ذلك من صلاحهم وإن لم يعرفوا.` },
            { text: "فَلَعَلَّكَ تَارِكٌۢ بَعْضَ مَا يُوحَىٰٓ إِلَيْكَ وَضَآئِقٌۢ بِهِۦ صَدْرُكَ أَن يَقُولُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ كَنزٌ أَوْ جَآءَ مَعَهُۥ مَلَكٌ إِنَّمَآ أَنتَ نَذِيرٌ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ", tafsir: `` },
            { text: "أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ فَأْتُوا۟ بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `أي بل يقولون إن الرسول افترى القرآن على الله سبحانه ونسبه إليه كذبا مع أنه ليس من عنده ( قُلْ ) يا رسول الله لهم : إن كان القرآن من كلامي وليس من كلام الله سبحانه ( فَأْتُوا بِعَشْرِ سُوَرٍ مِثْلِهِ مُفْتَرَياتٍ ) أي مختلقات من عند أنفسكم ، فإنه لو كان من كلام البشر لتمكن البشر من الإتيان بمثله. وليس لأحد أن يقول كان الرسول صلى‌الله‌عليه‌وآله‌وسلم في الدرجة الأولى في البلاغة ، لذا لم يقدروا أن يأتوا بمثله. إذ كونه بالدرجة الأولى لا تمنع أقرانه أن يأتوا بجزء من بلاغته. ومن المعلوم بأن القرآن كبير فليأتوا بمثل بعضه ، كما أن كون أحد المهندسين أقوى من غيره في التصميم ورسم الخرائط ، ليس معناه أن سائر المهندسين لا يتمكنون حتى ولو بتخطيط تصميم واحد كتصميمات ذلك المهندس الكثيرة ، بل معناه أنه من حيث المجموع أقدر من غيره. ثم لو كان افتراء لزم ـ عقلا ـ تعجيز الله له ، وإلا لزم الإغراء بالجهل ، ولذا لم يدّع أحد النبوة كاذبا إلا وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللهِ إِنْ كُنْتُمْ صادِقِينَ (13) فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ فَاعْلَمُوا أَنَّما أُنْزِلَ بِعِلْمِ اللهِ وَأَنْ لا إِلهَ إِلاَّ هُوَ فضح كما نرى الشيء الكثير منه في التاريخ. ( وَادْعُوا ) أيها المكذّبون ( مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللهِ ) لمناصرتكم في الإتيان بعشر سور مثل القرآن ( إِنْ كُنْتُمْ صادِقِينَ ) في قولكم أن القرآن افتراء ، وليس من عند الله سبحانه.` },
            { text: "فَإِلَّمْ يَسْتَجِيبُوا۟ لَكُمْ فَٱعْلَمُوٓا۟ أَنَّمَآ أُنزِلَ بِعِلْمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَ فَهَلْ أَنتُم مُّسْلِمُونَ", tafsir: `أي إن لم يجبكم هؤلاء الكفار إلى الإتيان بمثل عشر سور ، ولعل الإتيان ب « لكم » خطابا للمسلمين ، لأجل أن المسلمين كانوا يحاجّون الكفار بمثل هذه الاحتجاجات ، والكفار لم يكونوا يتمكنون من الإجابة ( فَاعْلَمُوا ) أيها المسلمون ( أَنَّما أُنْزِلَ ) القرآن ( بِعِلْمِ اللهِ ) فإن علمه وحده كفيل بأن يأتي بشيء لا يقدر عليه البشر ، أما غيره فلا علم له بحيث يعلم ما لا يقدر عليه كل البشر حتى يتحدّاهم. ومعنى « اعلموا » أن ذلك العجز دليل على أنه من الله سبحانه ، إذ لو لم يكن من عنده سبحانه لشحذ الكفار أفكارهم ، وعقدوا ندوات وجاءوا أخيرا بمثل القرآن ، لتوفّر الدواعي لذلك ، فإن القرآن كان السلاح الوحيد الذي يتحداهم ، ويبنى عليه إبطال كل مزاعمهم ، فلو ملكوا أن يأتوا بمثل القرآن ولو بعد جهد وصعوبة ، لأتوا حتى يستريحوا ، وتكون لهم حجة على مزاعمهم بأن الرسول صلى‌الله‌عليه‌وآله‌وسلم ليس صادقا فيما يقول. ( وَ ) اعلموا ( أَنْ لا إِلهَ إِلَّا هُوَ ) فإنه لو كان له شريك ، لتمكن فَهَلْ أَنْتُمْ مُسْلِمُونَ (14) مَنْ كانَ يُرِيدُ الْحَياةَ الدُّنْيا من إسعاف هؤلاء المشركين به ليأتوا بمثل القرآن ، فإذا لم يأتوا به دل ذلك أن الله واحد لا شريك له ولا مثيل ( فَهَلْ أَنْتُمْ ) بعد قيام الحجة عليكم ( مُسْلِمُونَ ) ؟ لكنهم لم يسلموا ، بل ظلوا يحاربون الإسلام حتى خضعوا بالقوة. ثم إن القرآن تحدّى الكفار مرة بالإتيان بسورة ، ومرة بالإتيان بعشر سور ، ومرة بالإتيان بمثل القرآن كله ، فهل كان التحدي بهذا الترتيب ؟ قاله بعض المفسرين ، وقال آخرون : إن التحدي بعشر سور كان بعد التحدي بسورة واحدة ، فما السر ؟ الظاهر أن المراد : عدم إمكانهم أن يأتوا بشيء مثل القرآن ، سواء سورة واحدة منه أو أكثر ، فإن ذلك خارج عن موضوع التحدي ، وإنما اختلف حسب المقامات ، وذلك كما أن الطبيب إذا أراد تحدي من لا معرفة له بالطب وهو يدعي ذلك : يقول : « اشف مريضا ، اشف عشرة مرضى ، اشف من في البلد » ، فإنه لا يريد إلّا التحدي ، لا عدد المرضى الذين يريد المدعي علاجهم. [16] إن الكفار الذين لم يرضخوا للقرآن والحق ، إنما كانوا يخافون منه على منافعهم الدنيوية من رئاسة ومال وما إليهما ، فكيف يستعدّ من هو سيد قومه في قريش أن يذعن للرسول صلى‌الله‌عليه‌وآله‌وسلم الذي يزعم أنه دونه في المجتمع ، وكيف يرضخ الرئيس الديني اليهودي الذي تجبى إليه ثمرات عمل ألوف اليهود أن يترك كل ذلك ، ليكون له ما للمسلمين وعليه ما عليهم. ولذا يذكرهم سبحانه بهذه الحقيقة الكامنة في نفوسهم ( مَنْ كانَ يُرِيدُ الْحَياةَ الدُّنْيا ) أي الحياة القريبة وَزِينَتَها نُوَفِّ إِلَيْهِمْ أَعْمالَهُمْ فِيها وَهُمْ فِيها لا يُبْخَسُونَ (15) أُولئِكَ الَّذِينَ لَيْسَ لَهُمْ فِي الْآخِرَةِ إِلاَّ النَّارُ وَحَبِطَ ما صَنَعُوا فِيها وَباطِلٌ ما كانُوا يَعْمَلُونَ (16) ( وَزِينَتَها ) أي بهجتها وزخارفها ، وهو معرض عن الآخرة ( نُوَفِّ إِلَيْهِمْ أَعْمالَهُمْ فِيها ) أي : نوفّ لهم جزاء أعمالهم ، فإن كل عمل فيه جزاء ولا بد أن يرى الإنسان ـ صالحا أو طالحا ـ جزاء عمله ( وَهُمْ فِيها ) في الحياة الدنيا ( لا يُبْخَسُونَ ) لا ينقصون منها شيئا. فإن « البخس » بمعنى النقصان.` },
            { text: "مَن كَانَ يُرِيدُ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ", tafsir: `` },
            { text: "أُو۟لَٰٓئِكَ ٱلَّذِينَ لَيْسَ لَهُمْ فِى ٱلْـَٔاخِرَةِ إِلَّا ٱلنَّارُ وَحَبِطَ مَا صَنَعُوا۟ فِيهَا وَبَٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ", tafsir: `المريدون للدنيا فقط ، هم ( الَّذِينَ لَيْسَ لَهُمْ فِي الْآخِرَةِ إِلَّا النَّارُ ) إذ لم يعملوا في الدنيا عملا يستحقون به الجنة ، بل عملوا ما استحقوا به النار والعذاب ( وَحَبِطَ ) بطل ( ما صَنَعُوا فِيها ) ما عملوا في الدنيا من أعمال الخير ، إذ لم تكن أعمالهم لله سبحانه حتى يستحقوا عليها الثواب ، وحيث أن الثواب لازم طبيعي للعمل الصالح ، عبر ب « الحبط » بالنسبة إلى ما لا ثواب له ـ نظرا إلى نوعه ـ وإن كان الأمر ليس من الحبط حقيقة ( وَباطِلٌ ما كانُوا يَعْمَلُونَ ) فإن مبرّاتهم باطلة لا ثمرة لها ، إذ لم تكن جامعة لشرائط الصحة. [18] صنف من الناس يريد الحياة الدنيا وزينتها ، وصنف من الناس على بيّنة من ربه ، فهو يعرف طريقه ويؤمن بالآخرة كما يؤمن بالأولى ـ فطرة ـ وعنده شاهد يشهد له بصدق فطرته ، وهو الرسول صلى‌الله‌عليه‌وآله‌وسلم وقد سبقه مصدّق بطريقته كتاب موسى عليه‌السلام . إن هؤلاء الصنف يؤمنون بالرسول صلى‌الله‌عليه‌وآله‌وسلم لأنهم ينظرون إلى فطرتهم ، وإلى الشاهد ، وإلى الوثيقة السابقة. أما غيرهم فالنار موعدهم. هذا هو ظاهر الآية ، ويؤيده ما دلّ أَفَمَنْ كانَ عَلى بَيِّنَةٍ مِنْ رَبِّهِ وَيَتْلُوهُ شاهِدٌ مِنْهُ وَمِنْ قَبْلِهِ كِتابُ مُوسى إِماماً وَرَحْمَةً على حجية العقل وصحة حكم الفطرة ، فهو كبيّنة من الرب. ؟ وقد روي عن الإمام زين العابدين عليه‌السلام تفسير « الشاهد » في هذه الآية بالرسول صلى‌الله‌عليه‌وآله‌وسلم (1) . وفي المقام روايات أخرى واحتمالات ، أما الروايات فالظاهر أنها من باب ذكر المصاديق ، كما روي أن الشاهد هو الإمام المرتضى عليه‌السلام (2) . وأما الاحتمالات فلا حجية فيها ما لم توافق الظاهر. ( أَ فَمَنْ كانَ عَلى بَيِّنَةٍ مِنْ رَبِّهِ ) استفهام تقريري ، أي هل من كان على برهان وحجة من قبل الله سبحانه ، فله نور فطري يرى الحق ويؤمن به ؟ ولفظة « على » للتشبيه بالذي يركب المركب الفاره ، في مقابل الراجل ( وَيَتْلُوهُ ) أي يعضده ويؤيده ( شاهِدٌ مِنْهُ ) أي شاهد من قبل الله سبحانه ، وهو الرسول ، يشهد له بما دلّت عليه فطرته وهداه إليه عقله ، من أن للكون خالقا ، وأنه لا بد وأن يجازى كلّا بعمله. إلى غير ذلك مما تدل عليه الفطرة. ( وَمِنْ قَبْلِهِ ) أي قبل هذا الشاهد ( كِتابُ مُوسى ) عليه‌السلام يدل على صحة طريقته ، فله مؤيد فعلا ومؤيد سابقا ( إِماماً وَرَحْمَةً ) حالان لكتاب موسى عليه‌السلام أي أن كتاب موسى إمام يؤتمّ به في أمور الدين ، ( 1) راجع الكافي : ج 1 ص 190. ( 2) راجع مجمع البيان : ج 5 ص 255. أُولئِكَ يُؤْمِنُونَ بِهِ وَمَنْ يَكْفُرْ بِهِ مِنَ الْأَحْزابِ فَالنَّارُ مَوْعِدُهُ فَلا تَكُ فِي مِرْيَةٍ مِنْهُ إِنَّهُ الْحَقُّ مِنْ رَبِّكَ وَلكِنَّ أَكْثَرَ النَّاسِ لا يُؤْمِنُونَ (17) وَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً ورحمة من الله على عباده ، إذ يهديهم إلى الطريق. وذكر كتاب موسى ، لأنه مقبول لدى اليهود والنصارى ، ولأن عيسى عليه‌السلام كان كمتمّم لكتاب موسى ، فالتوراة هي الأصل. والحاصل المستفاد : أن التقدير : « أ فمن كان على بينة من الله ، وله شاهد على حقيقته ، ويعتقد به شاهد آخر ، كمن أراد الحياة الدنيا وزينتها ؟ » . وقد حذف جواب الاستفهام لدلالة الكلام عليه. ( أُولئِكَ ) الذين وصفوا بأنهم على بيّنة من ربهم ( يُؤْمِنُونَ بِهِ ) بالله وسائر الأمور التي يلزم الإيمان بها ( وَمَنْ يَكْفُرْ بِهِ مِنَ الْأَحْزابِ ) والفئات ، من أهل الكتاب كانوا أم من غيرهم ( فَالنَّارُ مَوْعِدُهُ ) ومصيره ومستقره ( فَلا تَكُ ) يا رسول الله ( فِي مِرْيَةٍ ) وشك ( مِنْهُ ) من الموعد ، أو من القرآن وما يلزم الإيمان به. والخطاب وإن كان للرسول صلى‌الله‌عليه‌وآله‌وسلم إلا أن المراد به سائر الناس ( إِنَّهُ ) أي ما تقدم من الموعد ، أو ما يلزم الإيمان به ـ المعلوم من السياق ـ ( الْحَقُّ مِنْ ) قبل ( رَبِّكَ ) أو أن الخبر الذي أخبرت به هو الحق من عند الله سبحانه ، فلا كذب فيه ولا تحوير ( وَلكِنَّ أَكْثَرَ النَّاسِ لا يُؤْمِنُونَ ) به ، بل يزعمون أنه كذب وافتراء.` },
            { text: "أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ وَيَتْلُوهُ شَاهِدٌ مِّنْهُ وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ وَمَن يَكْفُرْ بِهِۦ مِنَ ٱلْأَحْزَابِ فَٱلنَّارُ مَوْعِدُهُۥ فَلَا تَكُ فِى مِرْيَةٍ مِّنْهُ إِنَّهُ ٱلْحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ", tafsir: `` },
            { text: "وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أُو۟لَٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ٱلْأَشْهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُوا۟ عَلَىٰ رَبِّهِمْ أَلَا لَعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ", tafsir: `أي لا أحد أكثر ظلما ، وإن كان بصورة الاستفهام ( مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً ) أي نسب إلى الله الكذب افتراء ، وقد أُولئِكَ يُعْرَضُونَ عَلى رَبِّهِمْ وَيَقُولُ الْأَشْهادُ هؤُلاءِ الَّذِينَ كَذَبُوا عَلى رَبِّهِمْ أَلا لَعْنَةُ اللهِ عَلَى الظَّالِمِينَ (18) الَّذِينَ يَصُدُّونَ عَنْ سَبِيلِ اللهِ وَيَبْغُونَها عِوَجاً ذكر ذلك بمناسبة ما كان المشركون ينسبونه إلى النبي من افترائه القرآن ونسبته إلى الله سبحانه ، ولا يخفى أن عبارة « من أظلم » المستعملة في القرآن كثيرا ، يراد بها الظلم النسبي غالبا ، لا الحقيقي ( أُولئِكَ ) المفترون على الله ( يُعْرَضُونَ عَلى رَبِّهِمْ ) يوم القيامة ، أي يستحضرون في المحكمة التي يعقدها الله سبحانه ، إذ لا مكان له تعالى ولا يمكن رؤيته ( وَيَقُولُ الْأَشْهادُ ) جمع شاهد ، والمراد بهم إما الأنبياء أو الملائكة أو المؤمنون ( هؤُلاءِ الَّذِينَ كَذَبُوا عَلى رَبِّهِمْ ) ونسبوا إليه ما لم يكن منه ، فلا مجال للإنكار ولا محل للفرار ، ولا يمكن لهم أن يحلفوا كما يحلف المشركون ، قائلين : ( وَاللهِ رَبِّنا ما كُنَّا مُشْرِكِينَ ) (1) ، ( أَلا ) فلينتبه السامع ( لَعْنَةُ اللهِ ) طرده وعذابه ( عَلَى الظَّالِمِينَ ) الذين يظلمون أنفسهم وغيرهم بالافتراء على الله سبحانه ، وهذا إما تتمة كلام الأشهاد ، أو ابتداء كلام. [20] ثم وصف سبحانه الظالمين ، بقوله : ( الَّذِينَ يَصُدُّونَ عَنْ سَبِيلِ اللهِ ) أي يمنعون الناس عن الاهتداء وسلوك سبيل الله ، فيغرونهم بإلقاء الشّبه عليهم ، وإثارة شكهم وكفرهم وعصيانهم بترك أوامره ونواهيه ( وَيَبْغُونَها ) أي يريدون أن تكون السبيل ( عِوَجاً ) زيغا عن الاستقامة وعدولا عن الصواب ، هذا لو رجع الضمير إلى « السبيل » ـ وهي مؤنث ( 1) الأنعام : 24. وَهُمْ بِالْآخِرَةِ هُمْ كافِرُونَ (19) أُولئِكَ لَمْ يَكُونُوا مُعْجِزِينَ فِي الْأَرْضِ وَما كانَ لَهُمْ مِنْ دُونِ اللهِ مِنْ أَوْلِياءَ يُضاعَفُ لَهُمُ الْعَذابُ سماعي ـ أما لو رجع إلى سبيل الله ، كان المعنى : أنهم يزيدون وينقصون في سبيل الله وأحكامه ليظهروا للناس أنها منحرفة زائفة ، فيصرفوهم عنها ( وَهُمْ بِالْآخِرَةِ ) أي بالدار الآخرة ، من البعث والحساب والجزاء ( هُمْ كافِرُونَ ) غير مقرّين. ولا يخفى أن هذه الأوصاف ، تنطبق على الذين يفترون على الله الكذب ، فإنهم الصادون عن السبيل ، الجاحدون بالآخرة ، وإن أقرّ بعضهم بها لسانا ، فلو لا جحودهم قلبا لم يصدوا عن طريقه سبحانه.` },
            { text: "ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ", tafsir: `` },
            { text: "أُو۟لَٰٓئِكَ لَمْ يَكُونُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ يُضَٰعَفُ لَهُمُ ٱلْعَذَابُ مَا كَانُوا۟ يَسْتَطِيعُونَ ٱلسَّمْعَ وَمَا كَانُوا۟ يُبْصِرُونَ", tafsir: `الذين صدّوا عن السبيل وكفروا بالآخرة ( لَمْ يَكُونُوا مُعْجِزِينَ فِي الْأَرْضِ ) أي لم يكونوا يتمكنون من أن يعجزوا الله سبحانه في شيء من إرادته ، فيهدي الناس على رغمهم ، ولو أراد أن يأخذهم ويهلكهم لم يكن أمرهم عسيرا عليه ، فهم في قبضته وتحت قدرته ، وكأن ذكر « في الأرض » للإشارة إلى أنهم لا يتمكنون من تعجيزه في محل سيطرتهم وإمكانياتهم ، فكيف بالآخرة التي يحشرون فيها فرادى بلا مال ولا جاه ولا قوة ( وَما كانَ لَهُمْ مِنْ دُونِ اللهِ ) أي غير الله سبحانه ( مِنْ أَوْلِياءَ ) وأنصار ينصرونهم ويتولون أمرهم ، فإن الله سبحانه هو الذي بيده الأمور ، ويتولى كل شيء ، فإذا نزلت بهؤلاء كارثة لم يكن هناك منقذ لهم ( يُضاعَفُ لَهُمُ الْعَذابُ ) عذاب كفرهم بأنفسهم ، وعذاب صدّهم ، وكونهم سببا في كفر غيرهم ، كما قال سبحانه في آية أخرى : ( زِدْناهُمْ عَذاباً فَوْقَ الْعَذابِ بِما كانُوا ما كانُوا يَسْتَطِيعُونَ السَّمْعَ وَما كانُوا يُبْصِرُونَ (20) أُولئِكَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ وَضَلَّ عَنْهُمْ ما كانُوا يَفْتَرُونَ (21) لا جَرَمَ أَنَّهُمْ فِي الْآخِرَةِ هُمُ الْأَخْسَرُونَ (22) يُفْسِدُونَ ) (1) ، فقد عاشوا صمّا عميا و ( ما كانُوا يَسْتَطِيعُونَ السَّمْعَ ) فقد كانوا يقولون : إنا لا نستطيع أن نسمع كلام الله ، يريدون إظهار الضجر والاستهزاء ، لا أن المراد عدم استطاعتهم حقيقة ( وَما كانُوا يُبْصِرُونَ ) الأدلة والبراهين ، قد سدّوا أسماعهم عن كلامه سبحانه ، وأغمضوا عيونهم عن رؤية آياته ، لقد عاشوا مغلقي البصائر ، كأن ليس لهم سمع ولا بصر.` },
            { text: "أُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ", tafsir: `البعداء الصادّون الضالّون ( الَّذِينَ خَسِرُوا أَنْفُسَهُمْ ) فإن النفس ، كرأس مال يجب أن يتحفظ الإنسان بها عن العطب ويجلب بها الربح ، وهؤلاء قد خسروها ، حيث عطبت نفوسهم ، ولم يحصلوا على ربح ( وَضَلَّ عَنْهُمْ ما كانُوا يَفْتَرُونَ ) فقد تبدّد كذبهم وافتراؤهم ، وضاع عنهم فلم ينجهم ، فإن عملهم هلك وضاع ، حيث نجا سائر المؤمنين بأعمالهم الطيبة.` },
            { text: "لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ", tafsir: `« لا » كلمة نفي و « جرم » معناه الكسب ، أي لا كسب لهم في النفع بل كسبهم خسران الدنيا والآخرة ، أو بمعنى « لا محالة » و « لا بد » ( أَنَّهُمْ فِي الْآخِرَةِ هُمُ الْأَخْسَرُونَ ) أي الأكثر خسارة من غيرهم ، لشدة عذابهم ، ولا شك أن الكفار الذين لهم تلك الأوصاف المتقدمة من أكثر الناس عقابا. ( 1) النحل : 89. إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ وَأَخْبَتُوا إِلى رَبِّهِمْ أُولئِكَ أَصْحابُ الْجَنَّةِ هُمْ فِيها خالِدُونَ (23) مَثَلُ الْفَرِيقَيْنِ كَالْأَعْمى وَالْأَصَمِّ وَالْبَصِيرِ وَالسَّمِيعِ هَلْ يَسْتَوِيانِ مَثَلاً [24] هكذا كان حال الكافر المتصف بتلك الصفات السيئة ، أما المؤمنون فحالهم أحسن حال ( إِنَّ الَّذِينَ آمَنُوا ) بالله وبما يلزم الإيمان به ( وَعَمِلُوا الصَّالِحاتِ ) أي الأعمال الصالحة. والمراد هنا أعم من فعل الواجبات وترك المحرمات ، فإن من لم يترك الحرام لا يقال له أنه يعمل الصالحات وإن أتى بكل واجب. كما أنها تشمل عامل المستحبات وتارك المكروهات ( وَأَخْبَتُوا ) أي أنابوا وتضرّعوا إليه ، فإن الإخبات بمعنى الطمأنينة ، أي اطمأنوا ( إِلى رَبِّهِمْ ) وخشوا وخضعوا له ، فإن المؤمن خاضع لله ، مطمئن إلى أحكامه وتقديراته ، هادئ النفس لما يترقّبه من نصرته وعونه ( أُولئِكَ أَصْحابُ الْجَنَّةِ ) المالكون الملازمون لها ( هُمْ فِيها خالِدُونَ ) باقون أبدا دائما. [25] ثم مثّل سبحانه الكافر والمؤمن بمثل محسوس فقال : ( مَثَلُ الْفَرِيقَيْنِ ) فريق الكافرين وفريق المؤمنين ، أما الكافرون فهم ( كَالْأَعْمى ) بصرا ( وَالْأَصَمِ ) أذنا ، وأي عمى أعظم من عدم إبصار آيات الله وبراهينه وحججه ، وأي صمم أعظم من عدم استماع أوامره ونواهيه وإرشاداته ( وَ ) أما المؤمنون فهم ك ( الْبَصِيرِ وَالسَّمِيعِ ) فكما أنه يرى ويسمع ، كذلك المؤمن قد تفتّحت بصيرته فيرى الآيات الكونية ، وانفتح سمع قلبه فيسترشد بالموعظة ويسمع الحق سماع تفهّم وعمل ( هَلْ يَسْتَوِيانِ ) هؤلاء وهؤلاء ( مَثَلاً ) أي من حيث المثل ، استفهام إنكاري ، أي لا يستوي السميع البصير ، والأعمى أَ فَلا تَذَكَّرُونَ (24) وَلَقَدْ أَرْسَلْنا نُوحاً إِلى قَوْمِهِ إِنِّي لَكُمْ نَذِيرٌ مُبِينٌ (25) أَنْ لا تَعْبُدُوا إِلاَّ اللهَ إِنِّي أَخافُ عَلَيْكُمْ عَذابَ يَوْمٍ أَلِيمٍ (26) فَقالَ الْمَلَأُ الأصم ، عند أحد ، فكذلك المؤمن والكافر ( أَ فَلا تَذَكَّرُونَ ) أي تتذكرون ـ حذفت إحدى تاءيه للقاعدة في باب التفعل ـ وهو استفهام إنكاري يراد به ردع الكافرين ، كيف لا يفكرون في هذا الأمر الواضح ، ويعتبرون به. [26] وبعد ما بيّن سبحانه في هذه السورة حقائق كبري حول المبدأ والمعاد والرسول والأمة ، وأن من كذّب فله الهلاك والدمار والعذاب والنار ، ومن آمن فله خير وسعادة وجنات النعيم ، ذكر جملة من القصص السالفة التي تثبت احتجاج الأنبياء مع أممهم حول هذه العقائد ، وما انجرّت إليه أمورهم ، من تكذيب واضطهاد ، وما أعقب تكذيب الأمم من الهلاك والعقاب ( وَلَقَدْ أَرْسَلْنا نُوحاً إِلى قَوْمِهِ ) فقال لهم : ( إِنِّي لَكُمْ نَذِيرٌ مُبِينٌ ) أي منذر واضح ، أنذركم أن إذا كفرتم وعملتم بالمعاصي تجازون بعذاب الدنيا والآخرة.` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَخْبَتُوٓا۟ إِلَىٰ رَبِّهِمْ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `` },
            { text: "مَثَلُ ٱلْفَرِيقَيْنِ كَٱلْأَعْمَىٰ وَٱلْأَصَمِّ وَٱلْبَصِيرِ وَٱلسَّمِيعِ هَلْ يَسْتَوِيَانِ مَثَلًا أَفَلَا تَذَكَّرُونَ", tafsir: `` },
            { text: "وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ", tafsir: `` },
            { text: "أَن لَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍ", tafsir: `متعلق ب « نذير » أي إنذاري هو أن تتركوا عبادة ما دون الله من الأصنام ( إِنِّي أَخافُ عَلَيْكُمْ عَذابَ يَوْمٍ أَلِيمٍ ) مؤلم موجع ، وإنما قال « أخاف » لأنه لم يكن معلوما أنهم يموتون كفارا لعلهم يتوبون ، أو ترقيقا في الكلام مع المنكر المعاند.` },
            { text: "فَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرًا مِّثْلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ ٱلرَّأْىِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍۭ بَلْ نَظُنُّكُمْ كَٰذِبِينَ", tafsir: `أي جماعة الأشراف ـ لأنهم يملئون العيون جلالا والقلوب هيبة ـ وحيث أن المعارضين للأنبياء والمصلحين دائما هم الَّذِينَ كَفَرُوا مِنْ قَوْمِهِ ما نَراكَ إِلاَّ بَشَراً مِثْلَنا وَما نَراكَ اتَّبَعَكَ إِلاَّ الَّذِينَ هُمْ أَراذِلُنا بادِيَ الرَّأْيِ الطبقة المستعلية ، يأتي بيان حوارهم ، وإلّا فغيرهم أيضا كان يجادل ويحاور ( الَّذِينَ كَفَرُوا مِنْ قَوْمِهِ ) صفة « الملأ » ، وليس المراد ب « كفروا » تجدّد الكفر منهم ، بل كونهم كفارا ، فإن فعل الماضي ينسلخ عن الزمان غالبا ـ في مثل هذه الموارد ـ ولا مفهوم للوصف ، بأنه كان هناك عدّة لم يكفروا ، لأنه وصف توضيحي لا احترازي : ( ما نَراكَ ) يا نوح ( إِلَّا بَشَراً مِثْلَنا ) فكيف تدّعي النبوة والرسالة من الله سبحانه. فقد كانت كل أمة تظن أن النبي صلى‌الله‌عليه‌وآله‌وسلم يلزم أن يكون من الملائكة ، لا لبرهان عندهم ، بل لرفعة مقام الرسالة في نفوسهم ، لأنه لا يمكن أن يكون بشرا مثلهم في حين يدعي أنه متصل بالسماء وواسطة بينهم وبين الله العظيم ( وَما نَراكَ اتَّبَعَكَ إِلَّا الَّذِينَ هُمْ أَراذِلُنا ) لم يتبعك الأشراف والرؤساء والمثرون ، وإنما اتبعك وآمن بك الأراذل ، وهو جمع « رذل » وهو الخسيس الحقير في كل شيء ، فكيف يؤمن الأشراف في صف الأراذل. وقد كان الغالب أن الفقراء الذين ليس لهم ثروة ومنصب هم أسرع الناس قبولا إلى اتباع كل حق وباطل ، لأن المال والمنصب والكبرياء تمنع عن الاستجابة ، وتسبب القسوة والغلظة ، بخلاف الجماهير والفقراء من مختلف الطبقات والأعمال وما أشبه ، فإنهم أقرب إلى البساطة ، والفطرة السليمة. في حال كونهم ( بادِيَ الرَّأْيِ ) أي ظاهر الرأي لا عمق لرأيهم ، حتى يتدبروا ويتفكروا في الصدق والكذب ، والعواقب والمصير ، وَما نَرى لَكُمْ عَلَيْنا مِنْ فَضْلٍ بَلْ نَظُنُّكُمْ كاذِبِينَ (27) قالَ يا قَوْمِ أَ رَأَيْتُمْ إِنْ كُنْتُ عَلى بَيِّنَةٍ مِنْ رَبِّي وَآتانِي رَحْمَةً مِنْ عِنْدِهِ فَعُمِّيَتْ عَلَيْكُمْ أَ نُلْزِمُكُمُوها وَأَنْتُمْ لَها كارِهُونَ (28) مشتق من « بدا » بمعنى ظهر ( وَما نَرى لَكُمْ ) يا نوح وللمؤمنين بك ( عَلَيْنا مِنْ فَضْلٍ ) في ثروة أو مكانة اجتماعية ، فكيف نتبعك ؟ وقد ظنوا أن الرسالة من جنس هذه الأعراض الدنيوية ، فاللازم أن تكون الفئة المؤمنة من أصحاب الأموال والمناصب ، وقد غفلوا عن أن الرسالة من المناصب الروحية لا يتحملها إلا من اختاره الله وجعل نفسه أكمل الأنفس ، وليست من المناصب الدنيوية التي تحتاج إلى ثروة وكبرياء. وهكذا هم أهل الدنيا يستصغرون دائما أهل الدين ، إذا خلت أيديهم من المال والجاه. ( بَلْ نَظُنُّكُمْ ) يا نوح أنت والمؤمنين بك ( كاذِبِينَ ) في دعوى النبوة وما أتيت به ، وتبعك هؤلاء عليه من الدين.` },
            { text: "قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةً مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَٰرِهُونَ", tafsir: `نوح في جوابه لكفار قومه : ( يا قَوْمِ أَ رَأَيْتُمْ ) أخبروني ( إِنْ كُنْتُ عَلى بَيِّنَةٍ مِنْ رَبِّي ) على برهان وحجة يشهدان لي بصحة الدعوى وصدق النبوة ، وبأني أتيت بالمعجزات ، أ فلا تصدقونني ؟ وتنسبوني إلى الكذب أيضا ( وَآتانِي رَحْمَةً مِنْ عِنْدِهِ ) أي جعلني نبيا وخصّني بهذه المنزلة الرفيعة من بين البشر ( فَعُمِّيَتْ عَلَيْكُمْ ) خفيت عليكم لعدم تهيؤكم لقبول تلك البينة ، ( أَ نُلْزِمُكُمُوها ) نجبركم على المعرفة والبينة ( وَأَنْتُمْ لَها كارِهُونَ ) أي تكرهون البينة والمعرفة ولا تتدبرونها ، والحاصل أن لي بينة ، لكن أنتم تكرهون رؤيتها والتدبّر فيها ، وإنما لا ألزمكم وأجبركم على التدبر لأنه « لا إكراه في الدين » . وَيا قَوْمِ لا أَسْئَلُكُمْ عَلَيْهِ مالاً إِنْ أَجرِيَ إِلاَّ عَلَى اللهِ وَما أَنَا بِطارِدِ الَّذِينَ آمَنُوا إِنَّهُمْ مُلاقُوا رَبِّهِمْ وَلكِنِّي أَراكُمْ قَوْماً تَجْهَلُونَ (29) وَيا قَوْمِ مَنْ يَنْصُرُنِي مِنَ اللهِ إِنْ طَرَدْتُهُمْ أَ فَلا تَذَكَّرُونَ (30)` },
            { text: "وَيَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ", tafsir: `لماذا تمتنعون عن إجابتي وليس في ذلك تكليف لكم بدفع الأجور حتى تخافون من ذلك وتهربون من دفعه ، فإني ( لا أَسْئَلُكُمْ عَلَيْهِ ) على دعوتي لكم إلى الله سبحانه ( مالاً ) فتستثقلون دعوتي ( إِنْ أَجرِيَ ) أي : ما أجري في التبليغ ( إِلَّا عَلَى اللهِ ) فهو الذي أمرني بذلك ، وهو الذي يعطيني الأجر والثواب على عملي ( وَ ) قد كان بعض الكفار سألوا نوحا بطرد المؤمنين ـ الأراذل في نظرهم ـ حتى يفكروا في أمره ويلتفوا حوله ـ كما قال بعض المفسرين ـ لكن نوحا أجابهم بقوله : ( ما أَنَا بِطارِدِ الَّذِينَ آمَنُوا ) لست أطردهم من عندي ولا أقصيهم من حوالي ، ولماذا ؟ أ ليسوا هم مؤمنين بي و ( إِنَّهُمْ مُلاقُوا رَبِّهِمْ ) فيجازي من طردهم بالعذاب والنار ، كما تقول : « لا أقطع علاقتي بفلان فإنه يلاقي الملك » ، تريد : فيشكوك عنده ( وَلكِنِّي أَراكُمْ ) أيها الكفار ( قَوْماً تَجْهَلُونَ ) الحق ، فتعلّلون عدم إيمانكم بعلل واهية وأعذار سخيفة.` },
            { text: "وَيَٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ أَفَلَا تَذَكَّرُونَ", tafsir: `بأس ( اللهِ ) ونقمته ( إِنْ طَرَدْتُهُمْ ) أي طردت هؤلاء المؤمنين بلا ذنب ولا عصيان ، حين يشكوني خصمائي عند الله ( أَ فَلا تَذَكَّرُونَ ) تتفكرون ، فتعلمون أن الأمر على ما قلته. وهكذا يكون دائما المتكبرون ، إنهم يقولون لأصحاب الرسالات وَلا أَقُولُ لَكُمْ عِنْدِي خَزائِنُ اللهِ وَلا أَعْلَمُ الْغَيْبَ وَلا أَقُولُ إِنِّي مَلَكٌ وَلا أَقُولُ لِلَّذِينَ تَزْدَرِي أَعْيُنُكُمْ لَنْ يُؤْتِيَهُمُ اللهُ خَيْراً اللهُ أَعْلَمُ بِما فِي أَنْفُسِهِمْ إِنِّي إِذاً لَمِنَ الظَّالِمِينَ (31) والمصلحين : أطرد فلانا وفلانا ، ممن يرون أنهم فوقهم شأنا. وقد دلت التجارب أن أولئك المؤمنين هم المخلصون الذين يحملون مشعل الإصلاح دون أولئك المتكبرين الذين يريدون طرد جماعة ، فإن المتكبر لا يصلح لحمل شعلة الهداية والإصلاح.` },
            { text: "وَلَآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ إِنِّى مَلَكٌ وَلَآ أَقُولُ لِلَّذِينَ تَزْدَرِىٓ أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ ٱللَّهُ خَيْرًا ٱللَّهُ أَعْلَمُ بِمَا فِىٓ أَنفُسِهِمْ إِنِّىٓ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ", tafsir: `يا قوم ( لا أَقُولُ لَكُمْ عِنْدِي خَزائِنُ اللهِ ) فأتمكن فوق قدرة البشر بأن أبذل ما أشاء ، وأفعل ما أشاء ( وَلا أَعْلَمُ ) بنفسي من دون إرشاد ربي ( الْغَيْبَ ) الأمور الغائبة عن الحواس والمدارك ، حتى أريد أن أتفضل عليكم بذلك ( وَلا أَقُولُ إِنِّي مَلَكٌ ) من الملائكة ، فأنا بشر كما قلتم ذو إمكانية بشرية ، لا خزائن ، ولا غيب لي ، وإنما أنا رسول من قبل الله سبحانه ( وَلا أَقُولُ ) للمؤمنين الملتفين حولي الذين ( تَزْدَرِي أَعْيُنُكُمْ ) « الازدراء » الاحتقار ، أي الذين تحتقرونهم. ونسبة الازدراء إلى العين لأنهم إنما ازدروهم لما عليهم من ألبسة رثة وأطمار خلقه ، ولو نظروا إلى واقعهم لرأوهم كبارا في نفوسهم ، عظماء عند الله سبحانه. وقد حذف المتعلق في الكلام ، أي تزدريهم أعينكم : ( لَنْ يُؤْتِيَهُمُ اللهُ خَيْراً ) حيث لم يعطهم مالا وجاها ـ كما تقولون أنتم ـ فإن الخير في الإيمان والصفات الكاملة لا في المال والمنصب ( اللهُ أَعْلَمُ بِما فِي أَنْفُسِهِمْ ) فلقد أتاهم الخير كله ، حيث هيأ نفوسا نظيفة وقلوبا طاهرة ( إِنِّي إِذاً ) إذا طردتهم ، أو قلت : لن يؤتهم الله خيرا ( لَمِنَ الظَّالِمِينَ ) حيث ظلمتهم بذلك العمل ، أو هذا القول. قالُوا يا نُوحُ قَدْ جادَلْتَنا فَأَكْثَرْتَ جِدالَنا فَأْتِنا بِما تَعِدُنا إِنْ كُنْتَ مِنَ الصَّادِقِينَ (32) قالَ إِنَّما يَأْتِيكُمْ بِهِ اللهُ إِنْ شاءَ وَما أَنْتُمْ بِمُعْجِزِينَ (33) وَلا يَنْفَعُكُمْ نُصْحِي إِنْ أَرَدْتُ أَنْ أَنْصَحَ لَكُمْ إِنْ كانَ اللهُ يُرِيدُ أَنْ يُغْوِيَكُمْ [33] ولما حاجّهم نوح عليه‌السلام بتلك الاحتجاجات الصريحة المعقولة ، لم يجد القوم إلا الفرار عن المحاجة ، ف ( قالُوا يا نُوحُ قَدْ جادَلْتَنا ) حاججتنا وخاصمتنا ( فَأَكْثَرْتَ جِدالَنا ) وبحثك معنا حول المبدأ والمعاد وما إليهما ( فَأْتِنا بِما تَعِدُنا ) من العذاب. فقد هددهم نوح بعذاب الله إن بقوا في كفرهم وغيّهم ( إِنْ كُنْتَ مِنَ الصَّادِقِينَ ) في دعواك النبوة ، وأنّا إن لم نؤمن عذبنا الله بذنوبنا.` },
            { text: "قَالُوا۟ يَٰنُوحُ قَدْ جَٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ", tafsir: `` },
            { text: "قَالَ إِنَّمَا يَأْتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ", tafsir: `نوح في جواب استعجالهم العذاب : ( إِنَّما يَأْتِيكُمْ بِهِ ) بالعذاب ( اللهُ إِنْ شاءَ ) تعذيبكم ، وليس من عندي حتى أعجّله أو أؤجله ( وَما أَنْتُمْ بِمُعْجِزِينَ ) أي إن أراد عذابكم فلا تتمكنون من تعجيزه حتى لا يتمكن من العذاب ، ولا تتمكنون من صدّ العذاب أو الهرب عن مشيئته سبحانه. [35] ثم قال نوح عليه‌السلام : ( وَلا يَنْفَعُكُمْ ) يا قوم ( نُصْحِي ) وإرشادي ( إِنْ أَرَدْتُ أَنْ أَنْصَحَ لَكُمْ ) وإنما قيّد النصح بالإرادة ، وقد صدر منه فعلا ، تواضعا في الكلام ، وكأنه لم ينصح من قبل ، لا أنه نصح ولم يفد ، أو لأنهم لم يعتبروا كلامه نصحا ، فهو يقول : إن صدر مني نصح في المستقبل لا ينفعكم ( إِنْ كانَ اللهُ يُرِيدُ أَنْ يُغْوِيَكُمْ ) وإرادة الله إغوائهم ، يعني تركهم وشأنهم ، حيث أنهم لمّا أعرضوا عن الحق هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ (34) أَمْ يَقُولُونَ افْتَراهُ قُلْ إِنِ افْتَرَيْتُهُ فَعَلَيَّ إِجْرامِي وَأَنَا بَرِيءٌ مِمَّا تُجْرِمُونَ (35) تركهم سبحانه وشأنهم ، فلم يلطف بهم الألطاف الخاصة ليستعدوا للاهتداء ، كما تقول : « إن كان الملك يريد إفساد الشعب لا ينفع وعظ الخطباء » تريد تركهم على حالهم حتى يفسدوا بطبعهم ، ويعملوا الجرائم لعدم رادع لهم. و ( هُوَ ) تعالى ( رَبُّكُمْ ) فهو يعلم دخائل نفوسكم ، وأنكم غير صالحين للطفه الخفي ( وَإِلَيْهِ تُرْجَعُونَ ) يوم القيامة فيجازيكم بسيئاتكم.` },
            { text: "وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ", tafsir: `` },
            { text: "أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَعَلَىَّ إِجْرَامِى وَأَنَا۠ بَرِىٓءٌ مِّمَّا تُجْرِمُونَ", tafsir: `أي : بل يقولون ، والظاهر من السياق أنه من تتمة المطلب المربوط بحوار نوح مع قومه ( افْتَراهُ ) على الله في دعواه الرسالة ( قُلْ ) يا نوح لهم : ( إِنِ افْتَرَيْتُهُ ) أي كذبت على الله فيما نقلته عنه ( فَعَلَيَّ إِجْرامِي ) وعقوبته لي ، لا لكم ، فأنتم بريئون من جرمي وافترائي ( وَأَنَا بَرِيءٌ مِمَّا تُجْرِمُونَ ) لا أو آخذ بجريمتكم وكفركم. وهناك احتمال آخر وهو أن يكون ذلك من الالتفات من قصة نوح إلى قصة النبي مع المشركين ، فإنهم كانوا يتّهمون الرسول بما اتّهم قوم نوح نوحا عليه‌السلام من الافتراء ـ وحيث كان ذلك من أغراض القصة ، جيء به هنا تنبيها ، يرجع إلى تتمة قصة نوح وقومه ـ فالمعنى : إن هؤلاء المشركين يقولون لك يا رسول الله أنك افتريت على الله سبحانه بنسبة القرآن إليه. والبقية بهذا السياق جاعلا الرسول صلى‌الله‌عليه‌وآله‌وسلم مكان نوح عليه‌السلام . وَأُوحِيَ إِلى نُوحٍ أَنَّهُ لَنْ يُؤْمِنَ مِنْ قَوْمِكَ إِلاَّ مَنْ قَدْ آمَنَ فَلا تَبْتَئِسْ بِما كانُوا يَفْعَلُونَ (36) وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنا وَوَحْيِنا وَلا تُخاطِبْنِي فِي الَّذِينَ ظَلَمُوا إِنَّهُمْ مُغْرَقُونَ (37)` },
            { text: "وَأُوحِىَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ ءَامَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَفْعَلُونَ", tafsir: `بعد تلك البلاغات الكبيرة والمحاولات الطويلة ، والأمد البعيد ( أَنَّهُ لَنْ يُؤْمِنَ مِنْ قَوْمِكَ إِلَّا مَنْ قَدْ آمَنَ ) بك من قبل فلا رجاء في الباقين ( فَلا تَبْتَئِسْ ) أي لا تحزن ولا تغتم ، من « الابتئاس » وهو افتعال من « البؤس » بمعنى الغمّ ( بِما كانُوا يَفْعَلُونَ ) من الكفر وأنواع المعاصي ، فإن الإنسان إنما يحزن إما لنفسه كيف يكون مصيره مع قومه ، وإما للقوم ، أما إذا أدّى ما عليه بالدعوة مرارا كثيرة فلا حزن لنفسه ، كما أنه لو علم أن لا خير فيهم فلا حزن عليهم.` },
            { text: "وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ إِنَّهُم مُّغْرَقُونَ", tafsir: `اعمل ( الْفُلْكَ ) هي السفينة لتركبها أنت والمؤمنون عند الطوفان ( بِأَعْيُنِنا ) بمرأى منّا فإن « أعين » جمع « عين » أي برعايتنا وحفظنا ، حيث ننظر إليك وإلى عملك. ومن يراقبه الله سبحانه لا يضل ولا يزيغ ( وَوَحْيِنا ) أي تعليمنا لك كيفية الصنع ( وَلا تُخاطِبْنِي فِي الَّذِينَ ظَلَمُوا ) لا تسألني العفو عن هؤلاء الكافرين ، ولا تشفع لهم ( إِنَّهُمْ مُغْرَقُونَ ) قد حكم عليهم بالغرق والهلاك ، وإنما خاطبه سبحانه بذلك ، ليعلم أنه لا يستجاب مثل هذا الدعاء ، فلا يتعب نفسه في الطلب والسؤال. وإن قيل : كيف يجمع هذا الأمر ـ وهو أن نوحا عليه‌السلام كان يريد الدعاء لهم بالخير ـ مع قوله سبحانه حكاية عن نوح : ( رَبِّ لا تَذَرْ عَلَى الْأَرْضِ مِنَ الْكافِرِينَ دَيَّاراً ) (1) ؟ ( 1) نوح : 27. وَيَصْنَعُ الْفُلْكَ وَكُلَّما مَرَّ عَلَيْهِ مَلَأٌ مِنْ قَوْمِهِ سَخِرُوا مِنْهُ قالَ إِنْ تَسْخَرُوا مِنَّا فَإِنَّا نَسْخَرُ مِنْكُمْ كَما تَسْخَرُونَ (38) فالجواب : إن دعاء الخير لمن يحتمل إيمانه في المستقبل ، لا ينافي دعاء الشر لمن علم بعدم إيمانه أصلا ، فإن قوله عليه‌السلام « من الكافرين » يعني الذين لا يرجعون عن غيّهم وكفرهم ، وفوق ذلك ( يُضِلُّوا عِبادَكَ وَلا يَلِدُوا إِلَّا فاجِراً كَفَّاراً ) (1) ، فلا خير في نسلهم كما لا خير فيهم .. أما الذين ظلموا فلعله كان يحتمل رجوع بعضهم. وبهذا الخطاب منه سبحانه تبين أنه لا يفيد فيهم الدعاء ، ولا يرجعون عن غيّهم أبدا ، وأنه لن يؤمن منهم إلا من قد آمن من قبل.` },
            { text: "وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ", tafsir: `جعل نوح عليه‌السلام ( يَصْنَعُ الْفُلْكَ ) بيده ، ينحتها ويسويها ، كما يصنع النجار من الأخشاب الأبواب وغيرها ( وَكُلَّما مَرَّ عَلَيْهِ مَلَأٌ ) جماعة ( مِنْ قَوْمِهِ ) الذين دعاهم فلم تنفعهم الدعوة ( سَخِرُوا مِنْهُ ) استهزءوا منه قائلين : يا نوح صرت نجارا بعد طول الدعوة وادّعاء النبوة ، والجدال والبحث حول الإله والمعاد ، استهزاء به وسخرية منه ، فكانوا يتضاحكون يقول بعضهم لبعض : انظروا إلى هذا المدّعي للنبوة كيف ينجر سفينة بهذا الكبر في اليابسة حيث لا ماء. ( قالَ ) نوح عليه‌السلام في جوابهم : ( إِنْ تَسْخَرُوا مِنَّا ) على هذا العمل ( فَإِنَّا نَسْخَرُ مِنْكُمْ كَما تَسْخَرُونَ ) أي نجازيكم على سخريتكم بسخرية منّا عند نجاتنا وغرقكم. إما سخرية حقيقية ، وإما من باب تسمية الجزاء باسم المجزي به ، نحو : ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا ( 1) نوح : 28. فَسَوْفَ تَعْلَمُونَ مَنْ يَأْتِيهِ عَذابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذابٌ مُقِيمٌ (39) حَتَّى إِذا جاءَ أَمْرُنا وَفارَ التَّنُّورُ قُلْنَا احْمِلْ فِيها مِنْ كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ ) (1) ، و ( ( اللهُ يَسْتَهْزِئُ بِهِمْ ) (2) .` },
            { text: "فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ", tafsir: `في المستقبل ( تَعْلَمُونَ مَنْ يَأْتِيهِ عَذابٌ يُخْزِيهِ ) يفضحه ويهينه ويذله ، وذلك بالغرق ( وَيَحِلُّ عَلَيْهِ عَذابٌ مُقِيمٌ ) لا يزول عنه ولا يتحول ، وهو عذاب الآخرة الممتد من بعد الموت في القبر ، ثم في جهنم إلى الأبد.` },
            { text: "حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌ", tafsir: `« حتى » غاية لحال نوح وحال قومه ، أي بقي نوح يصنع السفينة وبقي القوم على كفرهم يستهزئون منه ، حتى حين مجيء أمرنا بإهلاكهم ونجاة المؤمنين ( وَفارَ التَّنُّورُ ) بالماء ، فقد كان فوران التنور بالماء علامة لوقت العذاب كي يحمل نوح عليه‌السلام في السفينة المؤمنين ( قُلْنَا ) أي أوحينا إلى نوح عليه‌السلام : ( احْمِلْ فِيها ) في السفينة ( مِنْ كُلٍّ زَوْجَيْنِ اثْنَيْنِ ) من كل أجناس الحيوانات زوجين ذكر وأنثى ، يطلق « الزوج » على الذكر كما يطلق على الأنثى ، وقد يطلق على الاثنين معا ، فيقال لهما « زوج » ، ولما كان يحتمل في الآية إرادة المعنى الأخير حتى يكون اللازم حمل أربعة من كل جنس ، بيّن « الزوجين » بأن المراد بهما فرد وفرد ، فيصير الحاصل اثنين لا أكثر. ( وَ ) احمل في السفينة ( أَهْلَكَ ) عائلتك ، زوجتك وأولادك ( 1) البقرة : 195. ( 2) البقرة : 16. إِلاَّ مَنْ سَبَقَ عَلَيْهِ الْقَوْلُ وَمَنْ آمَنَ وَما آمَنَ مَعَهُ إِلاَّ قَلِيلٌ (40) ( إِلَّا مَنْ سَبَقَ عَلَيْهِ الْقَوْلُ ) من تقدم حوله قولنا بأنه من الهالكين من عائلتك وهي زوجة نوح عليه‌السلام واسمها واغلة ، وكانت أما لكنعان الولد الذي هلك بالغرق ، فقد كان لنوح عليه‌السلام زوجتان وأولاد كلهم صالحون إلا هذه المرأة وابنها ( وَ ) احمل في السفينة ( مَنْ آمَنَ ) وهم بين ثمانية وثمانين ، كما في الأحاديث ، ولذا قال سبحانه : ( وَما آمَنَ مَعَهُ إِلَّا قَلِيلٌ ) و قد ورد أن نوحا عليه‌السلام نادى الحيوانات فأجابته واجتمعت حوله فأركبها في السفينة ، وذلك ليس على الله بعزيز. ومن غريب الأمر أن بعض المسلمين الذين فقدوا ثقتهم بنفوسهم أمام الغرب يأوّلون جميع المعاجز مهما تمكنوا ويجعلونها أمورا عادية وقصصا خارجية لا مسحة عليها من الغيب والإعجاز ، وإذا لم يلائم شيء مع هذه الطريقة سمّوه ب « الإسرائيليات » ولم ذلك ؟ لأنه معجز خارج عن نطاق مفاهيم الماديين الغربيين. ففي قصتنا مثلا ، يقول : سفينة نوح سفينة عادية صنعت ، و « الوحي حولها » هو الإلهام في القلب كما يلهم قلب كل متعلم بالعلم ، و « حمل نوح عدة حيوانات » مما يملكه نوح من الحيوانات ، وكان الموسم فيضانا والمطر وابل فغرق بعض الناس الذين كانوا في تلك المناطق ، وسلم نوح وقومه المؤمنون. وهكذا يحرّفون كل خارقة إلى رماد وتراب بعد ما كانت خارقة تأخذ بالأنفس وتدل على رسالة الأنبياء ، فإذا لم يكن في القرآن فهو خرافة وإسرائيليات ، مهما بلغ سنده من الصحة والثبات ، أما إذا كان في القرآن فباب التأويل واسع ، ف ( ( اقْتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ ) (1) يراد به انشقاق بعض الأقمار التي دل العلم على وجودها سابقا ثم صارت منشقة بصورة هائلة أي : ابتعاد الأنجم بعضها عن بعض. و ( ( وَأَرْسَلَ عَلَيْهِمْ طَيْراً أَبابِيلَ* تَرْمِيهِمْ بِحِجارَةٍ مِنْ سِجِّيلٍ ) (2) كانت أسراب طير معها « ميكروب » الوباء فلما اختلطت بالناس ، عدى المرض إليهم فماتوا بالوباء ، وما أشبه هذه التأويلات .. وهكذا هلمّ جرا. حتى أن بعضهم ـ وهو مؤمن بالله واليوم الآخر ، طبعا ـ ذكر أن المراد ب « الإله » القوة المسيّرة للكون أو الطاقة المحركة للحياة ، و « المعاد » هو حساب التاريخ للإنسان ، و « الجنة » ذكره الطيب المنبعث عن أعماله الحسنة ، و « النار » ذكره السيئ المنبعث عن أعماله القبيحة .. فلنتساءل : أي فرق بينكم أيها المؤمنون ! وبين الماديين ؟ وهل أحد ينكر الطاقة ومحاسبة التاريخ والذكر الحسن والسيئ ؟ وإذا سألت هؤلاء المنهزمين ، ماذا تصنعون بالنصوص والتصريحات ؟ أجابوا بأنها على سبيل الكناية والمجاز ، حسب فهم العرب المخاطبين .. نقول : إن المؤمن هو من يؤمن بكل نص ، أما أن يكون الإنسان ماديا قلبا ، مسلما صورة فليس ذاك إلا النفاق ، والانهزام أمام بريق الغرب المادي .. ومثل هذه الانهزامية في العقائد ، والانهزامية في الأحكام ، كمن يقول إن الإسلام جمهوري لقوله تعالى في قصة بلقيس : ( فَما ذا تَأْمُرُونَ ) (3) ؟ ، أو برلماني ، لقوله تعالى : ( وَأَمْرُهُمْ ( 1) القمر : 2. ( 2) الفيل : 4 و 5. ( 3) الأعراف : 111. وَقالَ ارْكَبُوا فِيها بِسْمِ اللهِ مَجْراها وَمُرْساها إِنَّ رَبِّي لَغَفُورٌ رَحِيمٌ (41) وَهِيَ تَجْرِي بِهِمْ فِي مَوْجٍ كَالْجِبالِ وَنادى نُوحٌ ابْنَهُ شُورى ) (1) ، أو اشتراكي ، لقوله : ( وَالَّذِينَ فِي أَمْوالِهِمْ حَقٌّ مَعْلُومٌ ) (2) ، أو ربوي لقوله : ( لا تَأْكُلُوا الرِّبَوا أَضْعافاً مُضاعَفَةً ) (3) ، مما يفهم منه جواز أكله بدون أن يصبح أضعافا ، وهكذا .. مما هم بالهوس أقرب منهم إلى الإسلام. وقد رأينا أن معيار هؤلاء هو الغرب فما ذكره فهم تبع له ، فإن وافق الإسلام فهو ، وإلا فاللازم أن يطبق الإسلام عليه ، يا للهراء والسخف !!` },
            { text: "وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ", tafsir: `نوح عليه‌السلام : ( ارْكَبُوا فِيها ) في السفينة ( بِسْمِ اللهِ مَجْراها وَمُرْساها ) أي قائلين بسم الله ، وقت جريانها على الماء ، ووقت إرسائها أي وقوفها وحبسها عن المسير ، أو المعنى : بالله إجراؤها وإرساؤها ( إِنَّ رَبِّي لَغَفُورٌ ) للذنوب ( رَحِيمٌ ) وبهاتين الصفتين استحق المؤمنون النجاة.` },
            { text: "وَهِىَ تَجْرِى بِهِمْ فِى مَوْجٍ كَٱلْجِبَالِ وَنَادَىٰ نُوحٌ ٱبْنَهُۥ وَكَانَ فِى مَعْزِلٍ يَٰبُنَىَّ ٱرْكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلْكَٰفِرِينَ", tafsir: `كانت السفينة ( هِيَ تَجْرِي بِهِمْ فِي مَوْجٍ ) جمع « موجة » وهي ما علا من الماء بسبب دخول الهواء فيه ، فيكون الماء متخلخلا عاليا يسير بسير الهواء واتجاه الرياح ، ومعنى « بهم » أي في حال كونها معهم ، وحال كونهم فيها ( كَالْجِبالِ ) بارتفاعها وضخامتها ( وَنادى نُوحٌ ) عليه‌السلام في تلك الحالة ( ابْنَهُ ) كنعان الذي كان من تلك المرأة ( 1) الشورى : 39. ( 2) المعارج : 25. ( 3) آل عمران : 131. وَكانَ فِي مَعْزِلٍ يا بُنَيَّ ارْكَبْ مَعَنا وَلا تَكُنْ مَعَ الْكافِرِينَ (42) قالَ سَآوِي إِلى جَبَلٍ يَعْصِمُنِي مِنَ الْماءِ قالَ لا عاصِمَ الْيَوْمَ مِنْ أَمْرِ اللهِ إِلاَّ مَنْ رَحِمَ وَحالَ بَيْنَهُمَا الْمَوْجُ فَكانَ مِنَ الْمُغْرَقِينَ (43) وَقِيلَ يا أَرْضُ ابْلَعِي ماءَكِ الخائنة ( وَكانَ ) الابن ( فِي مَعْزِلٍ ) أي محل عزلة ، لأنه لم يركب معهم في السفينة : ( يا بُنَيَّ ارْكَبْ مَعَنا ) في السفينة لتنجو ( وَلا تَكُنْ مَعَ الْكافِرِينَ ) حتى تهلك وتغرق. [44] فأجابه الابن ( قالَ سَآوِي ) من « أوى يأوي » إذا اتخذ مأوى ومحلّا ، أي سأرجع إلى مأوى ( إِلى جَبَلٍ ) شاهق لا يعلوه الماء ( يَعْصِمُنِي ) يحفظني ( مِنَ الْماءِ ) فلا أغرق ولا أركب معك في السفينة ( قالَ ) نوح عليه‌السلام : ( لا عاصِمَ الْيَوْمَ مِنْ أَمْرِ اللهِ ) أي لا شيء يحفظ الإنسان من عذاب الله وغرقه الذي قدّره على الكافرين ( إِلَّا مَنْ رَحِمَ ) من المؤمنين الذين ركبوا السفينة ، فآمن بالله واركب السفينة كي تنجو ويرحمك الله ( وَحالَ بَيْنَهُمَا ) بين نوح وابنه ( الْمَوْجُ ) جاءت الأمواج حتى لم يشاهد نوح ابنه ( فَكانَ ) أي صار الابن ( مِنَ الْمُغْرَقِينَ ) أغرق وأهلك في جملة الكافرين. [45] لقد طافت السفينة على الماء أياما ، ونوح والمؤمنون والحيوانات فيها ، وأخذ الماء ينهمر من السماء ويخرج من الأرض حتى غرق الكفار بأجمعهم ( وَ ) حينذاك ( قِيلَ ) المراد أن الله سبحانه قال ذلك ، إما بنفسه أو بأمر بعض الملائكة أن يقول ذلك ، أو المراد إرادته سبحانه ، فعبّر عنه بالقول : ( يا أَرْضُ ابْلَعِي ماءَكِ ) ردّي واشربي الماء الذي وَيا سَماءُ أَقْلِعِي وَغِيضَ الْماءُ أخرجتيه بسبب تفجّر العيون ، وقد أريد بذلك : نشف الماء دفعة كأنه بلع له ( وَيا سَماءُ أَقْلِعِي ) أي قال تعالى للسماء : أمسكي المطر ولا ترسلي الماء إلى الأرض. فبلعت الأرض ماءها ، وأمسكت السماء عن المطر. وهل أن المراد من « ابلعي ماءك » جميع الماء الموجود فيها ولو كان الماء النازل من السماء ، أم خصوص مائها ، وبقي ماء السماء وتسرب في المسارب والمنحدرات ؟ احتمالان. و قد روي عن الأئمة الطاهرين عليهم‌السلام : أن الماء بقي ، وصار بحارا وأنهارا (1) . أقول : إن العلم الحديث دلّ على كون الجبال كلها كانت غامرة في الماء ، حتى أرفع الجبال كانت كذلك ، وقد وجد فيها آثار للماء والحيوانات المائية ، ولعل ذلك ـ إن صح ـ كان من وقت الطوفان حيث دلّ الدليل على غمر الماء لكل الجبال. وهل أن الخطاب حقيقي لشعور السماء والأرض بالأمر والنهي ، بمقتضى ( ( وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ ) (2) ، أو المراد نتيجة ذلك ، من باب خطاب العارف نحو : « أيا جبلي نعمان بالله خليا » . احتمالان ؟ ولا يبعد الأول ، كما قال سبحانه : ( فَقالَ لَها وَلِلْأَرْضِ ائْتِيا طَوْعاً أَوْ كَرْهاً قالَتا أَتَيْنا طائِعِينَ ) (3) ، وهكذا أمثالها ، مما ظاهره شعور السماء والأرض. ( وَغِيضَ الْماءُ ) أي ذهب الماء من وجه الأرض إلى باطنها من ( 1) بحار الأنوار : ج 11 ص 304. ( 2) الإسراء : 45. ( 3) فصلت : 12. وَقُضِيَ الْأَمْرُ وَاسْتَوَتْ عَلَى الْجُودِيِّ وَقِيلَ بُعْداً لِلْقَوْمِ الظَّالِمِينَ (44) « غاض يغيض » إذا تسرّب في الباطن ( وَقُضِيَ الْأَمْرُ ) تمّ الأمر المراد ، وهو هلاك الكفار ونجاة المؤمنين ( وَاسْتَوَتْ ) استقرت السفينة ( عَلَى ) جبل يسمى ( الْجُودِيِ ) وقد ورد في التفاسير أنه جبل بالموصل في شمال العراق (1) ( وَقِيلَ ) أي قال الله سبحانه ، أو الملائكة ، أو نوح والمؤمنون ، والمراد : نتيجة ذلك ( بُعْداً لِلْقَوْمِ الظَّالِمِينَ ) الذين كفروا وظلموا أنفسهم ، فليبتعدوا عن رحمة الله ، وعن سعادة الدنيا بالهلاك ، وعن خير الآخرة بدخول النار. وقد ذكر المفسرون وأهل البلاغة أن هذه الآية الكريمة في كمال البلاغة مما يدهش العقول والألباب فقد ذكروا أن كفار قريش أرادوا أن يتعاطوا معارضة القرآن فعكفوا على لباب البرّ ولحوم الضأن وسلاف الخمر أربعين يوما لتصفو أذهانهم ، فلما أخذوا فيما أرادوا سمعوا هذه الآية ، فقال بعضهم لبعض : هذا كلام لا يشبه شيء من الكلام ، ولا يشبه كلام المخلوقين ، وتركوا ما أخذوا فيه وافترقوا. وكان أهل الجاهلية إذا ألّفوا أفصح القصائد علقوها بالكعبة ، وهكذا حتى جمعت من أفصح القصائد وأبلغها على الكعبة سبع ، لامرئ القيس وزملائه ، فلما نزلت هذه الآية ، أمر النبي صلى‌الله‌عليه‌وآله‌وسلم بكتابتها ، وأن تعلق قرب المعلقات السبع ، فف عل ذلك بعض المسلمين ، ولما أصبحت قريش وأتت إلى الكعبة ، ورأت الآية إلى جنب المعلقات ، ( 1) بحار الأنوار : ج 11 ص 333. وَنادى نُوحٌ رَبَّهُ فَقالَ رَبِّ إِنَّ ابْنِي اضطرت إلى أن تقلع المعلقات ولم تدعها قرب الآية. ويقال : أن ثلاثة من الملحدين أرادوا معارضة القرآن ليبطلوا أساس الإسلام ، فاجتمعوا في مكة ، وضمن كل واحد منهم أن يقول مثل ثلث القرآن إلى العام القابل ، واجتمعوا في القابل في مكة فقال أحدهم : إني أعرضت عن معارضة القرآن لما رأيت أن فيه قوله : ( وَقِيلَ يا أَرْضُ ابْلَعِي ماءَكِ .. ) ، فقد علمت أني لا أتمكن أن آتي بما يشابهها. وقال الثاني : إني أعرضت عن معارضة القرآن حيث رأيت في قوله : ( فَلَمَّا اسْتَيْأَسُوا مِنْهُ خَلَصُوا نَجِيًّا ) (1) ، فقد علمت أنه لا يتسنّى لي مقابلة هذه الآية. وقال الثالث : إني أعرضت عن معارضة القرآن حيث رأيت فيه قوله : ( وَأَوْحَيْنا إِلى أُمِّ مُوسى أَنْ أَرْضِعِيهِ فَإِذا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِي الْيَمِّ وَلا تَخافِي وَلا تَحْزَنِي إِنَّا رَادُّوهُ إِلَيْكِ وَجاعِلُوهُ مِنَ الْمُرْسَلِينَ ) (2) ، فقد علمت أنه لا يمكنني معارضة هذه الآية. و يقال أن الإمام الصادق عليه‌السلام مرّ بهم في ذاك الحال وهم يتذاكرون عجزهم وينسبون تلك الأسباب فيما بينهم ، فقال لهم : ( قُلْ لَئِنِ اجْتَمَعَتِ الْإِنْسُ وَالْجِنُّ عَلى أَنْ يَأْتُوا بِمِثْلِ هذَا الْقُرْآنِ لا يَأْتُونَ بِمِثْلِهِ وَلَوْ كانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيراً ) (3) (4) . [46] وإذ قد انتهى الأمر وتذكر نوح عليه‌السلام ابنه الغريق كنعان وأخذته الشفقة عليه ( وَنادى نُوحٌ رَبَّهُ ) نداء دعاء وضراعة ( فَقالَ ) : يا ( رَبِّ إِنَّ ابْنِي ( 1) يوسف : 81. ( 2) القصص : 8. ( 3) الإسراء : 89. ( 4) بحار الأنوار : ج 17 ص 213. مِنْ أَهْلِي وَإِنَّ وَعْدَكَ الْحَقُّ وَأَنْتَ أَحْكَمُ الْحاكِمِينَ (45) قالَ يا نُوحُ إِنَّهُ لَيْسَ مِنْ أَهْلِكَ إِنَّهُ عَمَلٌ غَيْرُ صالِحٍ فَلا تَسْئَلْنِ ما لَيْسَ لَكَ بِهِ عِلْمٌ مِنْ أَهْلِي وَإِنَّ وَعْدَكَ الْحَقُ ) فقد وعدتني بنجاة أهلي فنجّه من الغرق ، أو من العذاب في الغرق ، فإن كان المراد الأول ، فلعلّ نوحا لم يكن يعرف مصير ولده هل أنه غرق أم لا ( وَأَنْتَ أَحْكَمُ الْحاكِمِينَ ) أي إن حكمك أصح الأحكام ، فلا تحكم في ولدي أو غيره إلا بالصحيح.` },
            { text: "قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍ يَعْصِمُنِى مِنَ ٱلْمَآءِ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ", tafsir: `` },
            { text: "وَقِيلَ يَٰٓأَرْضُ ٱبْلَعِى مَآءَكِ وَيَٰسَمَآءُ أَقْلِعِى وَغِيضَ ٱلْمَآءُ وَقُضِىَ ٱلْأَمْرُ وَٱسْتَوَتْ عَلَى ٱلْجُودِىِّ وَقِيلَ بُعْدًا لِّلْقَوْمِ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "وَنَادَىٰ نُوحٌ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبْنِى مِنْ أَهْلِى وَإِنَّ وَعْدَكَ ٱلْحَقُّ وَأَنتَ أَحْكَمُ ٱلْحَٰكِمِينَ", tafsir: `` },
            { text: "قَالَ يَٰنُوحُ إِنَّهُۥ لَيْسَ مِنْ أَهْلِكَ إِنَّهُۥ عَمَلٌ غَيْرُ صَٰلِحٍ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ إِنِّىٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلْجَٰهِلِينَ", tafsir: `الله سبحانه في جواب طلب نوح عليه‌السلام : ( يا نُوحُ إِنَّهُ ) أي ولدك ( لَيْسَ مِنْ أَهْلِكَ ) فإن الأهل الذين وعدت بنجاتهم ليس أهل لحم ودم ، وإنما أهل عقيدة وإيمان ( إِنَّهُ عَمَلٌ غَيْرُ صالِحٍ ) قد يبالغ في نسبة الفعل إلى شخص حتى يجعل ذلك الشخص نفس الفعل ، كما يقال : « زيد عدل » مع العلم أن زيد ليس قطعة من العدل وإنما هو ذو عدل ، ولكن البلاغة تقتضي ذلك. وهنا كذلك ، فإن ابن نوح لما كان يعمل الأعمال الفاسدة ، صار كأنه قطعة منها ، فقيل : « إنه عمل غير صالح » ، كما يقال : « زيد قطعة من فساد » ، يراد أنه منهمك فيه ، أو بتقدير « ذو » أي أنه « ذو عمل غير صالح » كما قال الشاعر : « فإنما هي إقبال وإدبار » أي : « ذات إقبال وإدبار » . وقال بعض أن الضمير في « إنه » يعود إلى سؤال نوح ، أي : إن طلبك بنجاة ابنك عمل غير صالح ، لكن هذا الاحتمال بعيد عن الظاهر. ( فَلا تَسْئَلْنِ ) يا نوح ( ما لَيْسَ لَكَ بِهِ عِلْمٌ ) السؤال إنشاء ، والإنشاء لا يتصف بالصدق والكذب ، ومطابقة الواقع وعدم مطابقته ، إِنِّي أَعِظُكَ أَنْ تَكُونَ مِنَ الْجاهِلِينَ (46) قالَ رَبِّ إِنِّي أَعُوذُ وكونه متعلق العلم وعدم كونه متعلقه. إلّا أن الإنشاء حيث يحمل دائما ـ في طيه ـ إخبار عن شيء صح الاتصاف بهذه الأمور ، فمثلا يسألك أحدهم مالا ، فتقول : إنه يكذب ، ولست تريد أنه يكذب في السؤال ، بل تريد أن الخبر الذي يدل عليه هذا الإنشاء ـ وهو أنه فقير معدم ـ غير صحيح ، إذ ظاهر السائل أنه لفقره يسأل ، فأنت تريد تكذيب ذلك الخبر المنطوي في هذا الإنشاء .. وهنا كذلك ، فإن سؤال نوح لم يكن بما ليس له به علم ، بل الخبر الضمني كان بدون علم فإنه عليه‌السلام أخبر بأن الله وعده نجاة ابنه ـ بتشكيل القياس ـ « ابنه من أهله » ، و « أهله موعود نجاتهم » ، ف « ابنه موعود نجاته » . وقد كان نوح عليه‌السلام يرى أن الوعد بنجاة الأهل شامل للولد أيضا ، وعلى هذا طلب الوفاء بالوعد ، لكنه سبحانه بيّن أنه لم يكن داخلا في الوعد ، ولم يدل دليل على لزوم علم الأنبياء بجميع الأمور ، حتى يقال أن نوحا عليه‌السلام كيف لم يعلم ذلك ، وهذا لا ينافي مقام العصمة ، فإن معنى العصمة أن لا يذنب ، لا أن يعلم كل شيء. ( إِنِّي أَعِظُكَ ) يا نوح ( أَنْ تَكُونَ مِنَ الْجاهِلِينَ ) أي لئلّا تكون جاهلا ، ولا شك أن وعظه سبحانه يبدّد الجهل. وقد يظن بعض الناس أن هذه عبارة خشنة ، لكن الظاهر أنه جار مجرى التكلم المعتاد ، في مقابل التكلم بلين ، ومقامه سبحانه لا يقتضي اللين في الكلام ، ويحتمل أن يكون إفراغ الغالب في هذا القالب لإفادة مبغوضية الكفار لدى الله سبحانه ـ وقد سبق ما يشبهه في قصة أخذ موسى عليه‌السلام برأس أخيه ـ.` },
            { text: "قَالَ رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَٰسِرِينَ", tafsir: `نوح عليه‌السلام بعد ذلك الكلام منه سبحانه : يا ( رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْئَلَكَ ما لَيْسَ لِي بِهِ عِلْمٌ وَإِلاَّ تَغْفِرْ لِي وَتَرْحَمْنِي أَكُنْ مِنَ الْخاسِرِينَ (47) بِكَ ) أي أعتصم بك ، من « عاذ » إذا استجار ( أَنْ أَسْئَلَكَ ما لَيْسَ لِي بِهِ عِلْمٌ ) أي أسألك شيئا ليس فيه صلاح ، ويكون سؤالي صادرا عن عدم علم لي بالواقع. ولا يخفى أن ذلك لا ينافي أيضا مقام العصمة ، فإن « ولدك لو سألك أن تذهب إلى النجف ، ولم يكن ذلك من الصلاح ، لأن الأجور تحمّلك خسارة كبيرة ، فهل أن سؤاله يعد عصيانا لك ؟ » . لكن نوحا عليه‌السلام أراد أن يجنّبه الله سبحانه حتى من هذا النحو من السؤال. ( وَإِلَّا ) أي : وإن لم ( تَغْفِرْ لِي وَتَرْحَمْنِي أَكُنْ مِنَ الْخاسِرِينَ ) « الغفران » الستر ، و « الترحم » التفضّل ، وهما كما يكونان بالنسبة إلى العاصي ، يكونان بالنسبة إلى المطيع ، فإن الإنسان مهما بلغ من النزاهة فإنه يحتاج إلى ستر الله لما لا يليق بشأنه ، كما يحتاج إلى تفضّله ، وهذا هو سر استغفار المعصومين. فمثلا إن التوجه إلى إنسان في كلام مما يسبب عدم التوجه إلى الله سبحانه في ذاك الوقت لا يليق بشأن من يعرف الله حقّ معرفته ، وإن كان راجحا في نفسه ، ولذا يستحق الاستغفار. قال سبحانه للرسول صلى‌الله‌عليه‌وآله‌وسلم : ( إِذا جاءَ نَصْرُ اللهِ وَالْفَتْحُ* وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللهِ أَفْواجاً* فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كانَ تَوَّاباً ) (1) . ومن هذا القبيل ما قيل : « حسنات الأبرار سيئات المقربين » (2) . ( 1) النصر : 2 ـ 4. ( 2) بحار الأنوار : ج 25 ص 205. قِيلَ يا نُوحُ اهْبِطْ بِسَلامٍ مِنَّا وَبَرَكاتٍ عَلَيْكَ وَعَلى أُمَمٍ مِمَّنْ مَعَكَ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُمْ مِنَّا عَذابٌ أَلِيمٌ (48) ثم إن من المعلوم أن للخسران مراتب فمن من شأنه تحصيل الربح الكثير إذا لم يحصل عليه كان خاسرا ، وهكذا قول نوح عليه‌السلام : « أكن من الخاسرين » فلو لا غفران الله ورحمته كان عليه‌السلام خاسرا إذا لم يحصّل تلك المراتب الرفيعة التي تليق بمثله. [49] ولما استقرت السفينة على جبل الجودي ( قِيلَ ) والقائل هو الله سبحانه ، إما بنفسه ، أو بأمر ملائكة بذلك : ( يا نُوحُ اهْبِطْ ) من السفينة والجبل إلى الأرض ( بِسَلامٍ مِنَّا ) بتحية لك من عندنا ، أو بنجاة وسلامة من قبلنا ، فأنت آمن ناج ( وَبَرَكاتٍ ) أي زيادة من فضل ، وخيرات نامية ( عَلَيْكَ وَعَلى أُمَمٍ مِمَّنْ مَعَكَ ) أي الجماعات التي معك من الإنس والطير والوحش ، فإنها تنمو وتزداد حتى تملأ الأرض من ذراريها ونسلها ، فإن الأمة تطلق على الحيوانات ، كما قال سبحانه : ( وَما مِنْ دَابَّةٍ فِي الْأَرْضِ وَلا طائِرٍ يَطِيرُ بِجَناحَيْهِ إِلَّا أُمَمٌ أَمْثالُكُمْ ) (1) . وهنا طريفة لفظية ، وهي : أن ثمان « ميمات » اجتمعن في هذه الآية « أمم مّمّن مّعك » أصلها خمس ميمات ونونان وتنوين. ( وَ ) من نسل هؤلاء ( أُمَمٌ سَنُمَتِّعُهُمْ ) نعطيهم متعة الحياة الدنيا في المستقبل ( ثُمَ ) يكفرون ويعصون ف ( يَمَسُّهُمْ ) يشملهم ( مِنَّا ) أي من طرفنا ( عَذابٌ أَلِيمٌ ) موجع مؤلم في الدنيا بصنوف القلق والمرض والفقر والحروب وما أشبه ، وفي الآخرة بالنار والعقاب. ( 1) الأنعام : 39. تِلْكَ مِنْ أَنْباءِ الْغَيْبِ نُوحِيها إِلَيْكَ ما كُنْتَ تَعْلَمُها أَنْتَ وَلا قَوْمُكَ مِنْ قَبْلِ هذا فَاصْبِرْ إِنَّ الْعاقِبَةَ لِلْمُتَّقِينَ (49) وَإِلى عادٍ وكان قوله « وأمم » لأجل أن لا يستفاد من قوله « وعلى أمم » أن من حملهم نوح وذريتهم كلهم تصحبهم السلامة والبركة ، بل هناك من نسلهم من يكفر ويعصي فلا بركة له ولا سلام.` },
            { text: "قِيلَ يَٰنُوحُ ٱهْبِطْ بِسَلَٰمٍ مِّنَّا وَبَرَكَٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍ مِّمَّن مَّعَكَ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "تِلْكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهَآ إِلَيْكَ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَٰذَا فَٱصْبِرْ إِنَّ ٱلْعَٰقِبَةَ لِلْمُتَّقِينَ", tafsir: `الأخبار التي قصصناها عليك من تفصيل أحوال نوح عليه‌السلام وقومه ( مِنْ أَنْباءِ الْغَيْبِ ) أي أخبار ما غاب عنك يا رسول الله معرفته ( نُوحِيها إِلَيْكَ ) وليس في التوراة والإنجيل لهذه الكيفية والتفصيل والنزاهة ( ما كُنْتَ تَعْلَمُها أَنْتَ ) يا رسول الله ( وَلا قَوْمُكَ ) قريش ، أو العرب ، أو الناس المعاصرون لك ، فإن لفظ « قوم » يستعمل بمعنى كل ذلك. ولا غضاضة في أن لا يعلمها الرسول صلى‌الله‌عليه‌وآله‌وسلم وهل علم الرسول إلا من علم الله سبحانه ووحيه فهو قبل ذلك لا يعلم شيئا ( مِنْ قَبْلِ هذا ) أي من قبل الوحي ، أو من قبل القرآن ( فَاصْبِرْ ) يا رسول الله على أذى قومك كما صبر نوح عليه‌السلام ( إِنَّ الْعاقِبَةَ ) المحمودة ( لِلْمُتَّقِينَ ) الذين يخافون الله ويعملون بأوامره ، كما كانت العاقبة لنوح والمؤمنين به. [51] وحيث ينتهي السياق من قصة نوح شيخ المرسلين ، يأتي الكلام حول قصة هود عليه‌السلام ويورد القرآن الكريم جملة من هذا القبيل من القصص كلها تركز على شيء واحد هو بعثة الأنبياء عليهم‌السلام لإصلاح الناس ، ثم عدم سماع الناس ـ إلا نادرا ـ منهم ، ثم إهلاك المكذبين وجعل كلمة الله هي العليا بنجاة المؤمنين ونصرتهم ( وَ ) أرسلنا ( إِلى عادٍ ) وهم أَخاهُمْ هُوداً قالَ يا قَوْمِ اعْبُدُوا اللهَ ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ إِنْ أَنْتُمْ إِلاَّ مُفْتَرُونَ (50) يا قَوْمِ لا أَسْئَلُكُمْ عَلَيْهِ أَجْراً إِنْ أَجْرِيَ إِلاَّ عَلَى الَّذِي فَطَرَنِي أَ فَلا تَعْقِلُونَ (51) وَيا قَوْمِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ قبيلة ( أَخاهُمْ ) في النسب ( هُوداً ) النبي عليه‌السلام ، وكان هؤلاء ساكنين في الأحقاف « والحقف » كثيب الرمل المائل ، في جنوب الجزيرة العربية ، وكانوا يعبدون الأصنام ، فأرسل الله إليهم أخاهم من تلك القبيلة هودا عليه‌السلام ، ف ( قالَ ) لهم : ( يا قَوْمِ اعْبُدُوا اللهَ ) وحده ( ما لَكُمْ ) ليس لكم ( مِنْ إِلهٍ غَيْرُهُ ) دخول « من » في المنفي يفيد العموم ( إِنْ أَنْتُمْ ) ما أنتم في اتخاذكم الأصنام شركاء لله تعالى ( إِلَّا مُفْتَرُونَ ) كاذبون في قولكم ، وحيث أنكم تنسبون ذلك إلى الله سبحانه ، فهو افتراء وبهتان.` },
            { text: "وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ", tafsir: `` },
            { text: "يَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ أَفَلَا تَعْقِلُونَ", tafsir: `أي على التبليغ والإرشاد والهداية ( أَجْراً ) مالا ، فإنما أبلغكم مجانا وبلا عوض. وقد كانت الأنبياء تؤكد على ذلك لأن الناس دائما يخافون من الداعي لخوفهم على أموالهم ، فإذا أمنوا ذلك ، لم يكن لهم عذر مادي في عدم قبولهم الدعوة ( إِنْ أَجْرِيَ ) أي ليس جزائي على الدعوة ( إِلَّا عَلَى ) الله ( الَّذِي فَطَرَنِي ) خلقني وسواني وأوجدني من العدم ( أَ فَلا تَعْقِلُونَ ) استفهام توبيخي ، أي لما ذا لا تعملون عقولكم لتعلموا صدق واستقامة طريقتي ؟!` },
            { text: "وَيَٰقَوْمِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا۟ مُجْرِمِينَ", tafsir: `اطلبوا عفوه وغفرانه لما سلف منكم من الكفر والمعاصي ( ثُمَّ تُوبُوا ) ارجعوا ( إِلَيْهِ ) في العمل بأوامره يُرْسِلِ السَّماءَ عَلَيْكُمْ مِدْراراً وَيَزِدْكُمْ قُوَّةً إِلى قُوَّتِكُمْ وَلا تَتَوَلَّوْا مُجْرِمِينَ (52) ونواهيه ، فإن الإنسان العاصي يحتاج إلى أمر سلبي هو محو ما سلف ، وإلى أمر إيجابي هو الاستقامة على منهاج جديد لما يأتي. وقد تقدم أن « الاستغفار والتوبة » لو افترقا شملا الأمرين ، أما لو اجتمعا فالاستغفار للسلبي ، والتوبة للإيجابي. فإذا فعلتم ذلك ( يُرْسِلِ السَّماءَ عَلَيْكُمْ مِدْراراً ) أي يرسل المطر عليكم متتابعا متواترا ، بمعنى « جرى ونزل » ، واستعمال « السماء » مريدا به المطر ، لعلاقة الحال والمحل. قال الشاعر : إذا نزل السماء بأرض قوم رعيناه وإن كانوا غضابا وفي بعض التفاسير أنهم كانوا قد أجابوا فوعدهم هود عليه‌السلام بالغيث إن تابوا وأنابوا ، كما قال تعالى في آية أخرى : ( وَلَوْ أَنَّ أَهْلَ الْقُرى آمَنُوا وَاتَّقَوْا لَفَتَحْنا عَلَيْهِمْ بَرَكاتٍ مِنَ السَّماءِ وَالْأَرْضِ وَلكِنْ كَذَّبُوا فَأَخَذْناهُمْ بِما كانُوا يَكْسِبُونَ ) (1) (2) . ( وَيَزِدْكُمْ قُوَّةً إِلى قُوَّتِكُمْ ) والمراد ب « القوة » كل ما يتقوّى به الإنسان من مال وأهل وقوى مادية ومعنوية ، وهذا بقدر ما هو مما وراء الغيب ، هو حسب القوانين العادية ، فإن المؤمنين أكثر نشاطا وتآلفا ، وأصح منهاجا مما تؤدي إليه كثرة القوة ( وَلا تَتَوَلَّوْا ) أي لا تعرضوا عن الله وأوامره في حال كونكم ( مُجْرِمِينَ ) تعملون الكفر والآثام. ( 1) الأعراف : 97. ( 2) راجع مجمع البيان : ج 5 ص 290. قالُوا يا هُودُ ما جِئْتَنا بِبَيِّنَةٍ وَما نَحْنُ بِتارِكِي آلِهَتِنا عَنْ قَوْلِكَ وَما نَحْنُ لَكَ بِمُؤْمِنِينَ (53) إِنْ نَقُولُ إِلاَّ اعْتَراكَ بَعْضُ آلِهَتِنا بِسُوءٍ قالَ إِنِّي أُشْهِدُ اللهَ وَاشْهَدُوا أَنِّي بَرِيءٌ مِمَّا تُشْرِكُونَ (54) مِنْ دُونِهِ فَكِيدُونِي جَمِيعاً` },
            { text: "قَالُوا۟ يَٰهُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِكِىٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ", tafsir: `في جواب دعوته لهم : ( يا هُودُ ما جِئْتَنا بِبَيِّنَةٍ ) بحجة واضحة تدل على صدقك. فإنهم لم يكونوا يعتبرون الأدلة الواضحة حجّة ، كما هو شأن كل معاند ( وَما نَحْنُ بِتارِكِي آلِهَتِنا عَنْ قَوْلِكَ ) لسنا نترك عبادة الأصنام لأجل قولك بأن الله واحد. وإنما جيء ب « عن » لأنه يدل على التجاوز ، نحو : « رميت السهم عن القوس » ، أي فليس تركنا ناشئا عن قولك ( وَما نَحْنُ لَكَ بِمُؤْمِنِينَ ) بمصدّقين مقالك.` },
            { text: "إِن نَّقُولُ إِلَّا ٱعْتَرَىٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءٍ قَالَ إِنِّىٓ أُشْهِدُ ٱللَّهَ وَٱشْهَدُوٓا۟ أَنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ", tafsir: `ما نقول فيك وفي هذه المقالات التي تقولها ( إِلَّا اعْتَراكَ ) أي أصابك ( بَعْضُ آلِهَتِنا بِسُوءٍ ) فإنك حيث كنت تسب آلهتنا ، أصابوك بالجنون فجننت وخبل عقلك ـ كذا قال المفسرون ـ فلما رأى هود عليه‌السلام أنه لا ينفع فيهم الكلام ولا يتفكرون ( قالَ ) لهم : ( إِنِّي أُشْهِدُ اللهَ وَاشْهَدُوا ) عليّ فإني أجعلكم شهودا على ( أَنِّي بَرِيءٌ مِمَّا تُشْرِكُونَ ) مع الله من الآلهة الباطلة ، ولا أعترف لهم بالألوهية. [56] فإن آلهتكم المزعومة التي تعبدونها ( مِنْ دُونِهِ ) من دون الله ، ليست في نظري بآلهة حتى أعبدها ، وإنما هو إله واحد لا شريك له. ثم كيف تزعمون أن آلهتكم مستني بسوء لسبي إياها ، فإني أتحدّاكم أن تجتمعوا أنتم والآلهة التي تعبدونها ( فَكِيدُونِي جَمِيعاً ) فاحتالوا واجتهدوا ثُمَّ لا تُنْظِرُونِ (55) إِنِّي تَوَكَّلْتُ عَلَى اللهِ رَبِّي وَرَبِّكُمْ ما مِنْ دَابَّةٍ إِلاَّ هُوَ آخِذٌ بِناصِيَتِها إِنَّ رَبِّي عَلى صِراطٍ مُسْتَقِيمٍ (56) لضرّي وإيذائي ( ثُمَّ لا تُنْظِرُونِ ) أي لا تمهلونني ، بل فاجئوني بالهجوم لقصد إيذائي ، فإني لا أبالي بكم ولا أكترث بكيدكم ، بعد ما كنت مستظهرا بالله سبحانه ، واثقا من نصره ، إنكم جميعا لا تقدرون على إيذائي ، فكيف يقدر بعض آلهتكم أن يمسني بسوء ؟ قال بعض المفسرين : إن هذا من أعظم آيات الأنبياء عليهم‌السلام أن يكون الرسول وحده ، وأمته متعاونة عليه ، فيقول لهم : كيدوني ، فلا يستطيع واحد منهم صدّه ، وكذلك قال نوح عليه‌السلام : ( فَأَجْمِعُوا أَمْرَكُمْ وَشُرَكاءَكُمْ .. . ) (1) ـ كما تقدم ـ و قال نبينا صلى‌الله‌عليه‌وآله‌وسلم : ( فَإِنْ كانَ لَكُمْ كَيْدٌ فَكِيدُونِ ) (2) . ومثل هذا القول لا يصدر إلا عمن هو واثق بنصر الله وبأنه يحفظه عنهم ويعصمه منهم.` },
            { text: "مِن دُونِهِۦ فَكِيدُونِى جَمِيعًا ثُمَّ لَا تُنظِرُونِ", tafsir: `` },
            { text: "إِنِّى تَوَكَّلْتُ عَلَى ٱللَّهِ رَبِّى وَرَبِّكُم مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذٌۢ بِنَاصِيَتِهَآ إِنَّ رَبِّى عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `إني وثقت به وفوضت أمري إليه فهو المدافع المحامي عني ( ما مِنْ دَابَّةٍ إِلَّا هُوَ ) سبحانه ( آخِذٌ بِناصِيَتِها ) أي ما من حيوان يدب على الأرض إلا هو مالك له يصرفه كيف يشاء ، و « الناصية » هو مقدم الرأس ، فكما أن الآخذ بشعر مقدم الرأس لأحد ، يتصرف في ذلك الإنسان بالقهر والغلبة ، كذلك المالك للدواب ، وهذا كناية عن قهره سبحانه لكل دابة وقدرته عليها كلها ( إِنَّ رَبِّي عَلى صِراطٍ مُسْتَقِيمٍ ) فإنه مع قدرته فهو عادل فيما يعامل به البشر ، وسنته وأحكامه عادلة مستقيمة. وهذا تشبيه للمعقول ( 1) يونس : 72. ( 2) المرسلات : 40. فَإِنْ تَوَلَّوْا فَقَدْ أَبْلَغْتُكُمْ ما أُرْسِلْتُ بِهِ إِلَيْكُمْ وَيَسْتَخْلِفُ رَبِّي قَوْماً غَيْرَكُمْ وَلا تَضُرُّونَهُ شَيْئاً إِنَّ رَبِّي عَلى كُلِّ شَيْءٍ حَفِيظٌ (57) وَلَمَّا جاءَ أَمْرُنا نَجَّيْنا هُوداً وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا وَنَجَّيْناهُمْ مِنْ عَذابٍ غَلِيظٍ (58) بالمحسوس فكما أن السائر المستقيم ، يمشي على صراط مستقيم ، فكذلك صراطه سبحانه في أحكامه وسننه. [58] ثم قال هود عليه‌السلام لقومه : ( فَإِنْ تَوَلَّوْا ) أصله « تتولوا » ، أي فإن أعرضتم عن دعوتي فإني غير ملوم وغير مأخوذ بإعراضكم إذ قد ( أَبْلَغْتُكُمْ ما أُرْسِلْتُ بِهِ إِلَيْكُمْ ) وبلغت لكم رسالة ربي ، فتوليكم من سوء اختياركم. ثم إن ذلك لا يضر الله سبحانه كما لا يضرّني فإنه يهلككم بمعاصيكم ( وَيَسْتَخْلِفُ رَبِّي قَوْماً غَيْرَكُمْ ) يؤتي مكانكم بأناس آخرين يعبدونه ويوحّدونه ، بعدكم وخلفا لكم ( وَلا تَضُرُّونَهُ شَيْئاً ) بتولّيكم ، كما لم تضرّوني بذلك ( إِنَّ رَبِّي عَلى كُلِّ شَيْءٍ حَفِيظٌ ) يحفظ دينه من الضياع فيأتي بغيركم ليعبدوه ، كما يحفظني عن أذاكم وضرركم.` },
            { text: "فَإِن تَوَلَّوْا۟ فَقَدْ أَبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـًٔا إِنَّ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ", tafsir: `` },
            { text: "وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَنَجَّيْنَٰهُم مِّنْ عَذَابٍ غَلِيظٍ", tafsir: `بهلاك عاد بعد أن لم تنفعهم الدعوة وتولّوا معرضين ( نَجَّيْنا هُوداً وَالَّذِينَ آمَنُوا مَعَهُ ) من الهلاك ـ وفي المجمع : قيل أنهم كانوا أربعة آلاف ـ ( بِرَحْمَةٍ مِنَّا ) حيث رحمناهم بعدم عذابهم. وذكر هذه الجملة ، إما لإفادة أن نجاتهم لم تكن صدفة وإنما عن قصد ، وإما لإفادة أن نجاة أولئك المؤمنين لم تكن باستحقاقهم ، إذ أن كل أحد لا بد وأنه ممن يستحق العقاب ، فنجاته تكون برحمة وفضل من الله ( وَنَجَّيْناهُمْ مِنْ عَذابٍ غَلِيظٍ ) شديد. والإتيان بهذا وَتِلْكَ عادٌ جَحَدُوا بِآياتِ رَبِّهِمْ وَعَصَوْا رُسُلَهُ وَاتَّبَعُوا أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ (59) وَأُتْبِعُوا فِي هذِهِ الدُّنْيا لَعْنَةً وَيَوْمَ الْقِيامَةِ أَلا إِنَّ عاداً كَفَرُوا رَبَّهُمْ اللفظ لدلالته على ما كان للعذاب من شدة وهول ، وتكرّر « نجينا » إما لبيان الخصوصية فإن اللفظ أولا كان مطلقا ، ثم جيء به مع المتعلق ، وإما لبيان أنهم نجوا من عذاب الآخرة كما نجوا من عذاب الدنيا ، وهذا فيما إذا أريد من « العذاب الغليظ » عذاب الآخرة. [60] ثم تأتي القصة في جمل قصار للتكرير والتركيز في الذهن ( وَتِلْكَ ) القبيلة التي أهلكت وهي ( عادٌ ) أي قبيلة عاد ( جَحَدُوا بِآياتِ رَبِّهِمْ ) أنكروا براهينه وأدلته التي أقامها على توحيده ورسالة رسوله وسائر الأصول والفروع ( وَعَصَوْا رُسُلَهُ ) بالمخالفة والمشاقة. وإنما قال « رسله » بلفظ الجمع ، لأن من كذّب رسولا فقد كذّب الرسل ، كما أن من المحتمل أن يكون سبحانه أرسل إليهم أنبياء ، وإنما تعرض لقصة أحدهم فقط وهو «هود » ( وَاتَّبَعُوا أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ ) « الجبار » هو من يجبر الناس على ما يريد ، و « العنيد » الكثير العناد الذي لا يقبل الحق ، والمراد جبابرتهم ، فقد كان قوم هود يمتثلون أمر الرؤساء الجبارين عوض امتثال أمر الأنبياء المصلحين.` },
            { text: "وَتِلْكَ عَادٌ جَحَدُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَعَصَوْا۟ رُسُلَهُۥ وَٱتَّبَعُوٓا۟ أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ", tafsir: `` },
            { text: "وَأُتْبِعُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ عَادًا كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّعَادٍ قَوْمِ هُودٍ", tafsir: `فإن الله سبحانه سخّر للمؤمنين لعنة الكفار ، فقوم هود « عاد » يلعنون في الدنيا ، فتعقبهم اللعنات مدى الزمان ( وَيَوْمَ الْقِيامَةِ ) يكونون ملعونين مطرودين عن الخير معذّبين في النار ، يلعنهم الأنبياء والملائكة والمؤمنون ( أَلا ) فلينتبه السامع ( إِنَّ عاداً كَفَرُوا رَبَّهُمْ ) أي : كفروا بربهم ، أو المراد أنهم ستروه بأن أَلا بُعْداً لِعادٍ قَوْمِ هُودٍ (60) وَإِلى ثَمُودَ أَخاهُمْ صالِحاً قالَ يا قَوْمِ اعْبُدُوا اللهَ ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ لم يعترفوا به ، فإن « الكفر » أصله « الستر » ( أَلا ) فلينتبه السامع ( بُعْداً لِعادٍ ) أي أبعد الله عادا ( قَوْمِ هُودٍ ) النبي هود عليه‌السلام عن رحمته. وهذا دعاء عليهم يتضمن التوهين والإذلال. وفي تكرّر « ألا » و « عاد » إظهار فظاعة أمرهم ، وحث الناس على الاعتبار بما نالهم ، والحذر من مثل أفعالهم ، وإنما قال « قوم هود » ليتميزوا عن « عاد إرم » . ورد أن عاد كانت بلادهم في البادية ، وكان لهم زرع ونخل كثير ، ولهم أعمار طويلة وأجسام ضخمة ، فعبدوا الأصنام وبعث الله إليهم هودا يدعوهم إلى الإسلام وخلع الأنداد ، فأبوا ولم يؤمنوا وآذوه ، فكفت السماء عنهم سبع سنين حتى قحطوا ، فجاءوا إليه فقالوا : يا نبي الله قد أجدبت بلادنا ولم تمطر ، فسل الله المطر وأن يخصب بلادنا ، فتهيأ للصلاة فصلى ودعا ، فقال لهم : ارجعوا فقد أمطرتم وأخصبت بلادكم. وبقي في قومه يدعوهم إلى الله وينهاهم عن عبادة الأصنام حتى أخصبت بلادهم وأنزل الله عليهم المطر. فلما لم يؤمنوا وبقوا على كفرهم وإصرارهم بعبادة الأصنام أرسل الله عليهم الريح الصرصر يعني « الباردة » سبع ليالي وثمانية أيام حتى أهلكهم عن آخرهم.` },
            { text: "وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا فَٱسْتَغْفِرُوهُ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى قَرِيبٌ مُّجِيبٌ", tafsir: `أرسلنا ( إِلى ثَمُودَ ) وهم قبيلة كانوا يسكنون مدائن الحجر بين تبوك ومدينة الرسول صلى‌الله‌عليه‌وآله‌وسلم ( أَخاهُمْ ) في النسب ( صالِحاً قالَ ) صالح عليه‌السلام لهم : ( يا قَوْمِ اعْبُدُوا اللهَ ) وحده لا شريك له ( ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ ) من هذه الأصنام التي تعبدونها وسائر الآلهة الباطلة هُوَ أَنْشَأَكُمْ مِنَ الْأَرْضِ وَاسْتَعْمَرَكُمْ فِيها فَاسْتَغْفِرُوهُ ثُمَّ تُوبُوا إِلَيْهِ إِنَّ رَبِّي قَرِيبٌ مُجِيبٌ (61) قالُوا يا صالِحُ قَدْ كُنْتَ فِينا مَرْجُوًّا قَبْلَ هذا ( هُوَ أَنْشَأَكُمْ ) أي ابتدأ خلقكم ( مِنَ الْأَرْضِ ) إما باعتبار آدم عليه‌السلام ، أو باعتبار كل فرد من أفراد البشر ، فإنه كان ترابا ثم صار نباتا ثم مأكولا ، أو حيوانا ثم منيا ثم إنسانا ( وَاسْتَعْمَرَكُمْ فِيها ) الاستعمار هو أن يجعل القادر منهم أن يعمّر الأرض ، فإذا قيل : «استعمر زيد عمروا » كان معناه : أنه جعل عمروا قادرا على عمارة الأرض بما هيأ له من الأسباب. فالمعنى أمركم بعمارة الأرض وأقدركم عليها. و قد روى « النعماني » عن أمير المؤمنين عليه‌السلام ، في تفسير « واستعمركم فيها » : فأعلمنا سبحانه أنه قد أمرهم بالعمارة ليكون ذلك مما جعله الله تعالى سببا لمعايشهم بما يخرج من الحب والثمرات وما شاكل ذلك مما جعله الله تعالى معايش (1) . أقول : ويؤيد هذا المعنى قوله : « أنشأكم » . ( فَاسْتَغْفِرُوهُ ) أي اطلبوا غفرانه بالتوبة من الشرك والمعاصي وفعل الطاعات ( ثُمَّ تُوبُوا إِلَيْهِ ) بعد أن طهّرتم أنفسكم من الذنوب ، وارجعوا إليه في أخذ الأحكام والطاعة والعبادة ( إِنَّ رَبِّي قَرِيبٌ ) قرب العلم والاطلاع والغفران ، فليس بعيدا غير عالم ، ولا متكبرا لا يلبي الطلب ( مُجِيبٌ ) لمن دعاه وطلبه.` },
            { text: "قَالُوا۟ يَٰصَٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَٰذَآ أَتَنْهَىٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِى شَكٍّ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبٍ", tafsir: `قالت ثمود : ( يا صالِحُ قَدْ كُنْتَ فِينا مَرْجُوًّا قَبْلَ هذا ) نرجو ( 1) وسائل الشيعة : ج 19 ص 35. أَ تَنْهانا أَنْ نَعْبُدَ ما يَعْبُدُ آباؤُنا وَإِنَّنا لَفِي شَكٍّ مِمَّا تَدْعُونا إِلَيْهِ مُرِيبٍ (62) قالَ يا قَوْمِ أَرَأَيْتُمْ إِنْ كُنْتُ عَلى بَيِّنَةٍ مِنْ رَبِّي وَآتانِي مِنْهُ رَحْمَةً فَمَنْ يَنْصُرُنِي مِنَ اللهِ إِنْ عَصَيْتُهُ فَما تَزِيدُونَنِي غَيْرَ تَخْسِيرٍ (63) منك الخير لما كنا نرى من صفاتك الحسنة وأخلاقك الطيبة ، أما الآن فقد يئسنا منك حيث رأينا أقوالك ودعوتك إلى الله ونبذ عبادة الأصنام ( أَ تَنْهانا ) استفهام إنكاري ( أَنْ نَعْبُدَ ما يَعْبُدُ آباؤُنا ) أي : كيف تنهانا عن عبادة الأصنام التي كان آباؤنا يعبدونها ؟ ( وَإِنَّنا لَفِي شَكٍّ مِمَّا تَدْعُونا إِلَيْهِ ) من عبادة الله وحده ونبذ الأصنام ( مُرِيبٍ ) موجب للريبة والتهمة ، كيف أنت تصدّق وآباؤنا كانوا على ضلالة وجهالة.` },
            { text: "قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى مِنْهُ رَحْمَةً فَمَن يَنصُرُنِى مِنَ ٱللَّهِ إِنْ عَصَيْتُهُۥ فَمَا تَزِيدُونَنِى غَيْرَ تَخْسِيرٍ", tafsir: `صالح لهم : ( يا قَوْمِ أَ رَأَيْتُمْ ) أي أخبروني ( إِنْ كُنْتُ عَلى بَيِّنَةٍ ) حجة واضحة تشهد على صدقي ( مِنْ ) قبل ( رَبِّي ) سبحانه ( وَآتانِي مِنْهُ رَحْمَةً ) أعطاني النبوة برحمته وفضله ( فَمَنْ يَنْصُرُنِي مِنَ اللهِ ) أي من بأس الله وغضبه وعذابه ( إِنْ عَصَيْتُهُ ) بعد إبلاغكم الدعوة ، أو اتخاذ طريقتكم لرجائكم فيّ الخير ، فإن رجاءكم فيّ الخير من دون عبادة الله وحده لا يدفع عني العذاب ، خصوصا وأنه سبحانه أعطاني وفضلني ( فَما تَزِيدُونَنِي ) إذا لبّيت دعوتكم ( غَيْرَ تَخْسِيرٍ ) أي خسارة على خسارة ، من سلب النبوة عني وعذاب الله الشامل للعاصين ، أو المعنى : غير أن أنسبكم إلى الخسران ، بأن أريكم أنكم الخاسرون ، إذ كلما أصرّ المبطل زاد المحق علما بأنه في خسارة وانحطاط ونقص. وَيا قَوْمِ هذِهِ ناقَةُ اللهِ لَكُمْ آيَةً فَذَرُوها تَأْكُلْ فِي أَرْضِ اللهِ وَلا تَمَسُّوها بِسُوءٍ فَيَأْخُذَكُمْ عَذابٌ قَرِيبٌ (64) فَعَقَرُوها فَقالَ تَمَتَّعُوا فِي دارِكُمْ ثَلاثَةَ أَيَّامٍ ذلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ (65) فَلَمَّا جاءَ أَمْرُنا نَجَّيْنا صالِحاً [65] ثم ذكر صالح عليه‌السلام الدليل على كونه نبيا من قبل الله سبحانه ، قال : ( وَيا قَوْمِ هذِهِ ناقَةُ اللهِ ) الإضافة إليه سبحانه تشريفية ، فإنه هو الذي كونها من غير ولادة عادية ، وإنما أخرجها من الجبل الأصم ( لَكُمْ آيَةً ) أي علامة ودليل على صدقي وحجة كلامي ـ وقد سبقت قصتها فراجع ـ ( فَذَرُوها ) أي دعوها واتركوها وشأنها ( تَأْكُلْ فِي أَرْضِ اللهِ ) من العشب والنبات ، ولا تريد الأكل منكم حتى تستثقلوها وتتضجرون منها ( وَلا تَمَسُّوها ) أي لا تصيبوها ( بِسُوءٍ ) أي بأذى قتل أو جرح أو عقر أو غيره فإن فعلتم ذلك ( فَيَأْخُذَكُمْ عَذابٌ قَرِيبٌ ) يقرب وقته من وقت إيذائكم لها. [66] لكن القوم أصرّوا على كفرهم وعنادهم ، واجتمع جماعة منهم وجعلوا لأحدهم جعلا إن عقر الناقة وخلّصهم منها ( فَعَقَرُوها ) وإنما نسب الأمر إلى جميعهم لفعل بعضهم ، ومشاركة جماعة بالتسبب ، ورضى الآخرين ( فَقالَ ) صالح عليه‌السلام لهم : ( تَمَتَّعُوا فِي دارِكُمْ ثَلاثَةَ أَيَّامٍ ) فإنه لم يبق من حياتكم وتمتعكم في الدنيا أكثر من ثلاثة أيام ( ذلِكَ ) العذاب بعد الثلاثة أيام ( وَعْدٌ غَيْرُ مَكْذُوبٍ ) أي صادق لا كذب فيه.` },
            { text: "وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ", tafsir: `` },
            { text: "فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِى دَارِكُمْ ثَلَٰثَةَ أَيَّامٍ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ", tafsir: `` },
            { text: "فَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا صَٰلِحًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَمِنْ خِزْىِ يَوْمِئِذٍ إِنَّ رَبَّكَ هُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ", tafsir: `أي عذابنا لقوم صالح ( نَجَّيْنا صالِحاً ) من العذاب وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا وَمِنْ خِزْيِ يَوْمِئِذٍ إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ (66) وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيارِهِمْ جاثِمِينَ (67) كَأَنْ لَمْ يَغْنَوْا فِيها أَلا إِنَّ ثَمُودَ كَفَرُوا رَبَّهُمْ ( وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا ) أي رحمنا أولئك المؤمنين فلم نعذبهم. ولعل سر الإيثار في هذه الجملة إفادة أن المؤمن الناجي ، أيضا ينجو بالرحمة لأن لكل إنسان من الذنوب ما يستحق بها العذاب ، أو أن الإنسان لا يستحق الثواب والجزاء الجميل وإنما يتفضل الله سبحانه بذلك ، فالنجاة من الهلكة ليست بالاستحقاق وإنما بالفضل والرحمة ( وَمِنْ خِزْيِ يَوْمِئِذٍ ) أي نجيناهم من الموت والخزي ، فإن الموت بالعذاب خزي وإهانة ، ومعنى « يومئذ » أي خزي يوم العذاب ( إِنَّ رَبَّكَ ) يا رسول الله ( هُوَ الْقَوِيُ ) الذي يقوى على إهلاك الكفار وإفنائهم ( الْعَزِيزُ ) الغالب في سلطانه لا يمتنع عليه أي شيء مما أراد.` },
            { text: "وَأَخَذَ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ", tafsir: `بأن صاح بهم جبرائيل عليه‌السلام أو خلق الله سبحانه صيحة فماتوا جميعا ( فَأَصْبَحُوا فِي دِيارِهِمْ ) وبيوتهم ( جاثِمِينَ ) من « جثم » بمعنى لزم المكان ، فلم يبرحه. أي : ميتين لا حراك لهم.` },
            { text: "كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّثَمُودَ", tafsir: `« غنى في المكان » أقام فيه ، والمعنى : كأن لم تكن ثمود في منازلهم قط لانقطاع آثارهم بالهلاك ، إلا بقايا بيوتهم وجثثهم الهامدة. ثم يجمل السياق القول في ما فعلوا وكان سببا في عاقبتهم هذه ( أَلا ) فلينتبه السامع ( إِنَّ ثَمُودَ كَفَرُوا رَبَّهُمْ ) فلم يعتقدوا أَلا بُعْداً لِثَمُودَ (68) وَلَقَدْ جاءَتْ رُسُلُنا إِبْراهِيمَ بِالْبُشْرى قالُوا سَلاماً قالَ سَلامٌ فَما لَبِثَ أَنْ جاءَ بِعِجْلٍ حَنِيذٍ (69) به وأشركوا معه غيره ، وأصل « الكفر » الستر ، كأنهم بعدم الاعتراف ستروا وجه الحقيقة ( أَلا ) فلينتبه السامع ( بُعْداً لِثَمُودَ ) عن حسن الذكر في الدنيا والسعادة في الآخرة ، إنهم قد طردوا عن رحمة الله وفضله. [70] ثم يستعرض القرآن الحكيم القصة الرابعة في هذه السورة بعد قصة نوح وهود وصالح عليهم‌السلام بقوله تعالى : ( وَلَقَدْ جاءَتْ رُسُلُنا ) أي الملائكة وهم جبرائيل وإسرافيل وميكائيل وكروبيل ( إِبْراهِيمَ بِالْبُشْرى ) أي بشارة إعطائه الولد ـ إسماعيل عليه‌السلام ـ بعد أن شاخ ويئس عن الولد. ولعل ذكر هذا الطرف من قصة إبراهيم عليه‌السلام لبيان أن الله سبحانه أنجز وعده الذي وعده لنوح بقوله : ( قِيلَ يا نُوحُ اهْبِطْ بِسَلامٍ مِنَّا وَبَرَكاتٍ عَلَيْكَ وَعَلى أُمَمٍ مِمَّنْ مَعَكَ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُمْ مِنَّا عَذابٌ أَلِيمٌ ) (1) ، فقد كانت البركات في أولاد إبراهيم إسماعيل وإسحاق ، والعذاب في أمة لوط. ( قالُوا ) أي لما دخلت الملائكة قالت لإبراهيم : ( سَلاماً ) بهذا اللفظ ، وهذا كناية عن تسليمهم عليه سلاما كاملا ، بأن قالوا ـ مثلا ـ سلام عليكم ، ف ( قالَ ) إبراهيم عليه‌السلام في جوابهم : ( سَلامٌ ) بهذا اللفظ ، ( فَما لَبِثَ أَنْ جاءَ بِعِجْلٍ حَنِيذٍ ) كأنه قال : « ما أبطأ عن المجيء بالعجل » ، فحذف حرف الجر ووصل الفعل بالمجرور ـ على القاعدة ـ « العجل » ولد البقر ، و « الحنيذ » فعيل بمعنى مفعول من ( 1) هود : 49. فَلَمَّا رَأى أَيْدِيَهُمْ لا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً قالُوا لا تَخَفْ إِنَّا أُرْسِلْنا إِلى قَوْمِ لُوطٍ (70) وَامْرَأَتُهُ قائِمَةٌ فَضَحِكَتْ « حنذ » بمعنى شواه بالحجارة ، أي جاء بعجل مشوي بالحجارة ، أو المشوي مطلقا. وقد كان إبراهيم عليه‌السلام محبا للضيف فلما رأى الملائكة ظنهم بشرا ـ لأنهم كانوا في صورة بشر ـ فأتى إليهم بالطعام ، وهو عجل مشوي. [71] لكن الملائكة لا تأكل طعام الدنيا ، ولذا لم يتقدموا للأكل كما هو عادة الضيوف ( فَلَمَّا رَأى ) إبراهيم عليه‌السلام ( أَيْدِيَهُمْ ) أي أيدي الملائكة ( لا تَصِلُ إِلَيْهِ ) إلى العجل ولا يأكلون منه ( نَكِرَهُمْ ) أنكرهم فإن « نكر وأنكر » بمعنى واحد ( فَأَوْجَسَ مِنْهُمْ خِيفَةً ) أي أضمر في نفسه منهم خوفا ، يقال : « أوجس خوفا » أي أضمر ، فإن الإيجاس يعني الإحساس. قالوا : فقد جرت عادتهم أن الضيف لو أكل من الطعام كانوا في أمن منه ، وإن لم يأكل خافوا من شره لأن عدم أكله دليل أنه ينوي السوء بالمضيف. وقيل : إن خوفه كان بسبب ما علم أنهم ملائكة وخاف من أن يكونوا أمروا بعذاب القوم. ( قالُوا ) أي قالت الملائكة ، لما رأوا خوف إبراهيم عليه‌السلام : ( لا تَخَفْ ) منا يا إبراهيم ( إِنَّا أُرْسِلْنا إِلى قَوْمِ لُوطٍ ) بالعذاب والإهلاك ، ولا نضمر بك شرا ، أو لا نضمر بقومك شرا.` },
            { text: "وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوا۟ سَلَٰمًا قَالَ سَلَٰمٌ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذٍ", tafsir: `` },
            { text: "فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍ", tafsir: `` },
            { text: "وَٱمْرَأَتُهُۥ قَآئِمَةٌ فَضَحِكَتْ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ وَمِن وَرَآءِ إِسْحَٰقَ يَعْقُوبَ", tafsir: `قد كانت ( امْرَأَتُهُ ) أي زوجة إبراهيم سارة ( قائِمَةٌ ) في أثناء هذا الكلام بين إبراهيم وبين الملائكة ( فَضَحِكَتْ ) ولعلّ ضحكها كان بسبب البشارة بهلاك القوم المجرمين ، فإن المرأة أكثر الناس غضبا فَبَشَّرْناها بِإِسْحاقَ وَمِنْ وَراءِ إِسْحاقَ يَعْقُوبَ (71) قالَتْ يا وَيْلَتى أَ أَلِدُ وَأَنَا عَجُوزٌ وَهذا بَعْلِي شَيْخاً لعمل الفاحشة من الرجال ، أو أنها ضحكت مستبشرة بقدوم الملائكة إلى دارها ، أو المراد من « ضحكت » حاضت ، فإن « ضحك » بمعنى سال ، يقال : ضحكت الشجرة ، إذا سال صمغها ، والمراد : أنها حاضت بعد عقم وانقطاع حيض ، وإن الحيض لمن المبشرات بالولد ، إذ لولاه لم يكن تكوّن الولد ( فَبَشَّرْناها بِإِسْحاقَ ) وحيث أن بشارة الملائكة لا تكون إلا من الله سبحانه صح إسناد البشارة إلى نفسه تعالى ( وَمِنْ وَراءِ إِسْحاقَ يَعْقُوبَ ) فإن البشارة بالولد والذرية من خير البشائر للمرأة العقيمة.` },
            { text: "قَالَتْ يَٰوَيْلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٌ وَهَٰذَا بَعْلِى شَيْخًا إِنَّ هَٰذَا لَشَىْءٌ عَجِيبٌ", tafsir: `سارة لما سمعت ببشارة الأولاد : ( يا وَيْلَتى ) حرف النداء دخل على منادى محذوف أصله : يا قوم ويلتي ، أو المعنى : يا ويلتي احضري فهذا وقتك ، كما قالوا في « يا للعجب » معناه : يا عجب احضر فهذا وقتك ، وليس حينئذ حقيقة وإنما القصد إنشاء التعجب بهذه العبارة ، و « ويلتي » أصله الدعاء بالهلاك ، لأن الويل بمعنى الشر والهلاك لكنه استعمل لمطلق التعجب عرضا ولو كان في الفرح ، من باب علاقة استعمال الضد في الضد ، نحو : « لا أبا لك » الذي كان أصله للسب ثم استعمل للمدح أيضا ( أَ أَلِدُ ) أي : هل ألد الولد ( وَ ) الحال ( أَنَا عَجُوزٌ ) طاعنة في السن ، و « العجوز » لفظ يستعمل لكل ذكر وأنثى ( وَهذا بَعْلِي شَيْخاً ) ؟! « البعل » الزوج ، أي إن هذا بعلي في حال كونه شيخا كبير السن. روي أن سارة كان لها من العمر يوم ذاك تسعون سنة إِنَّ هذا لَشَيْءٌ عَجِيبٌ (72) قالُوا أَ تَعْجَبِينَ مِنْ أَمْرِ اللهِ رَحْمَتُ اللهِ وَبَرَكاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ إِنَّهُ حَمِيدٌ مَجِيدٌ (73) فَلَمَّا ذَهَبَ عَنْ إِبْراهِيمَ الرَّوْعُ وَجاءَتْهُ الْبُشْرى يُجادِلُنا و لإبراهيم عليه‌السلام مائة وعشرون سنة (1) . ( إِنَّ هذا ) التبشير بالولد ، أو الولد منا ونحن هرمين ( لَشَيْءٌ عَجِيبٌ ) ولم يكن تعجبا إنكارا لقدرة الله سبحانه ، بل الإنسان إذا رأى شيئا خلاف القوانين المودعة في الطبيعة تحرك فيه حس التعجب والاستغراب.` },
            { text: "قَالُوٓا۟ أَتَعْجَبِينَ مِنْ أَمْرِ ٱللَّهِ رَحْمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيْكُمْ أَهْلَ ٱلْبَيْتِ إِنَّهُۥ حَمِيدٌ مَّجِيدٌ", tafsir: `أي قالت الملائكة التي بشروها بالولد : ( أَ تَعْجَبِينَ مِنْ أَمْرِ اللهِ ) استفهام تنبيه ، أي : كيف تعجبين من أمر إرادة الله سبحانه ؟ والحال ( رَحْمَتُ اللهِ وَبَرَكاتُهُ ) تفضله وخيراته النامية ( عَلَيْكُمْ ) يا ( أَهْلَ الْبَيْتِ ) أي أهل بيت النبوة ، فإنه سبحانه لم يزل يرعاكم ويتفضل عليكم فلا عجب لأنه القادر على ما يشاء ، ولا عجب من جهتكم لأنكم مورد ألطافه وكراماته ( إِنَّهُ ) سبحانه ( حَمِيدٌ ) محمود على أفعاله ( مَجِيدٌ ) ذو مجد ورفعة ، فبكونه محمود الفعال يتفضّل ، وبكونه رفيعا يقدر.` },
            { text: "فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ ٱلرَّوْعُ وَجَآءَتْهُ ٱلْبُشْرَىٰ يُجَٰدِلُنَا فِى قَوْمِ لُوطٍ", tafsir: `أي الخوف والرعب الذي دخله من الرسل ( وَجاءَتْهُ الْبُشْرى ) بالولد ، واطمأن بفضل الله ولطف الملائكة به ، شرع ( يُجادِلُنا ) أي يجادل رسلنا ويناقشهم. وحيث أن رسول ( 1) بحار الأنوار : ج 12 ص 110. فِي قَوْمِ لُوطٍ (74) إِنَّ إِبْراهِيمَ لَحَلِيمٌ أَوَّاهٌ مُنِيبٌ (75) يا إِبْراهِيمُ أَعْرِضْ عَنْ هذا إِنَّهُ قَدْ جاءَ أَمْرُ رَبِّكَ وَإِنَّهُمْ آتِيهِمْ عَذابٌ غَيْرُ مَرْدُودٍ (76) الشخص كالشخص ، صح إسناد فعل الرسل إليه ، كما صح إسناد فعل الأشخاص إلى الرسل ، بفعلهم معه ( فِي قَوْمِ لُوطٍ ) الذين أرسلت الملائكة لتعذيبهم. ورد أن إبراهيم عليه‌السلام قال للرسل : إن كان في القوم مائة من المؤمنين أ تهلكونهم ؟ قالوا : لا ، قال : إن كان فيهم خمسون ؟ قالوا : لا ، قال : فأربعون ؟ قالوا : لا. وما يزال ينقص ويقولون : لا ، حتى قال : فواحد ؟ قالوا : لا ، فقال : إن فيهم لوطا ؟ ـ وقد كان عليه‌السلام ابن خالة إبراهيم عليه‌السلام ـ قالوا : نحن أعلم بمن فيهم ، لننجيّنه وأهله إلا امرأته (1) .` },
            { text: "إِنَّ إِبْرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٌ مُّنِيبٌ", tafsir: `يحلم عن العصاة ، وبحلمه كان يطلب عدم تعذيب قوم لوط ( أَوَّاهٌ ) أي كثير الدعاء ( مُنِيبٌ ) راجع إلى الله سبحانه في جميع أموره ، من «أناب » ، وكأن الإتيان بهذا الوصف له عليه‌السلام ، وقد قضي الأمر. [77] ثم قالت الملائكة لإبراهيم عليه‌السلام ، بعد التساؤل والنقاش : ( يا إِبْراهِيمُ أَعْرِضْ عَنْ هذا ) الطلب وانصرف عنه فإنه لا يفيد ( إِنَّهُ قَدْ جاءَ أَمْرُ رَبِّكَ ) بهلاك هؤلاء وعذابهم فهو نازل بهم لا محالة ( وَإِنَّهُمْ ) أي قوم لوط ( آتِيهِمْ عَذابٌ غَيْرُ مَرْدُودٍ ) لا يرد عنهم ، فقد جرت سنة الله أن ( 1) الكافي : ج 5 ص 546. وَلَمَّا جاءَتْ رُسُلُنا لُوطاً سِيءَ بِهِمْ وَضاقَ بِهِمْ ذَرْعاً وَقالَ هذا يَوْمٌ عَصِيبٌ (77) المعرضين ما داموا لم يحتجّ عليهم ، أو يحتمل ـ ولو احتمالا خارجيا ـ أو كان في أصلابهم ذرية مؤمنة ، لا يعذّبون ، أما وقد انسدت الأبواب ، فقد حقت عليهم كلمة العذاب وما فائدة بقائهم أكثر من ذلك. [78] وانتهى الأمر وسار الرسل نحو قرية لوط عليه‌السلام في زي شبان حسان الصور ـ وهذه هي القصة الخامسة في السورة ـ ( وَلَمَّا جاءَتْ رُسُلُنا لُوطاً ) أي أتت الملائكة إلى لوط عليه‌السلام ( سِيءَ ) لوط ( بِهِمْ ) أي ساءه مجيئهم ( وَضاقَ ) لوط ( بِهِمْ ) أي بسبب ورودهم ( ذَرْعاً ) أي قلبا وطاقة. قالوا : إن الأصل في ذلك أن البعير يذرع بيديه في سيره ذرعا على قدر سعة خطوته ، فإذا حمل عليه أكثر من طاقته ضاق ذرعه عن ذرعه فيضعف ويمد عنقه ، ومنه قولهم : « ما لي به ذرع » أي ليس لي به طاقة. ( وَقالَ ) لوط عليه‌السلام : ( هذا يَوْمٌ عَصِيبٌ ) أي يوم شديد عليّ ، كيف أصنع بالقوم إذا أرادوا الفاحشة مع هؤلاء الضيوف ، أصل « عصب » من الشد ، يقال : « عصبت الشيء » أي شددته ، ويستعمل غالبا في الشر. و قد روي عن الإمام الباقر عليه‌السلام ـ بتغيير يسير ـ : كان قوم لوط من أفضل قوم خلقهم الله ، فطلبهم إبليس الطلب الشديد ، وكان من فضلهم وخيرتهم أنهم إذا خرجوا إلى العمل خرجوا بأجمعهم وتبقى النساء خلفهم ، ولم يزل إبليس يعتادهم وكانوا إذا رجعوا خرّب إبليس ما كانوا يعملون ، فقال بعضهم لبعض : تعالوا نرصد لهذا الذي يخرب متاعنا ، فرصدوه ، فإذا هو غلام أحسن ما يكون من الغلمان ، فقالوا له : أنت الذي تخرب متاعنا مرة بعد مرة ، فاجتمع رأيهم على أن يقتلوه فبيّتوه عند رجل ، فلما كان الليل صاح فقال له : ما لك ؟ فقال : كان أبي ينومني على بطنه. فقال الرجل : تعال فنم على بطني. قال : فلم يزل الشيطان يدلك الرجل حتى علّمه أن يفعل بنفسه ، ثم انسل ففر منهم ، وأصبحوا فجعل الرجل يخبر بما فعل بالغلام ويحبّبهم منه وهم لا يعرفونه ، فوضعوا أيديهم فيه حتى اكتفى الرجال بالرجال ، ثم جعلوا يرصدون مارة الطريق فيفعلون بهم ، حتى تنكّب مدينتهم الناس ، ثم تركوا نساءهم وأقبلوا على الغلمان ، فلما رأى الشيطان أنه قد أحكم أمره في الرجال ، جاء إلى النساء فصيّر نفسه امرأة ثم قال : إن رجالكن يفعل بعضهم ببعض. قلن : نعم قد رأينا ذلك. وكل ذلك ينصحهم لوط ويوصيهم ، وإبليس يغويهم ، حتى استغنت النساء بالنساء. فلما كملت عليهم الحجة بعث الله جبرائيل وميكائيل وإسرافيل في زي غلمان ، عليهم أقبية فمروا بلوط عليه‌السلام وهو يحرث قال : أين تريدون ؟ ما رأيت أجمل منكم قط ؟ قالوا : إنا أرسلنا سيدنا إلى رب هذه المدينة. قال : أو لم يبلغ سيدكم ما يفعل أهل هذه المدينة ، يا بني إنهم والله يأخذون الرجال فيفعلون بهم حتى يخرج الدم. فقالوا : أمرنا سيدنا أن نمر وسطها. قال : فلي إليكم حاجة ؟ قالوا : وما هي ؟ قال : تصبرون هنا إلى اختلاط الظلام. قال : فجلسوا ، فبعث لوط ابنته فقال : جيئي لهم بخبز وجيئي لهم بماء في القرعة وجيئي لهم بعباءة يتغطون بها من البرد. فلما أن ذهبت الابنة أقبل المطر ، وجرى الوادي ، فقال لوط : الساعة يذهب بالصبيان الوادي ، قال : قوموا حتى نمضي ، وجعل لوط يمشي في أصل الحائط وجعلت الملائكة يمشون وسط الطريق فقال : يا بني امشوا هاهنا ، فقالوا : أمرنا سيدنا أن نمر وسطها. وكان لوط يستغنم الظلام. و مر إبليس وأخذ من حجر امرأة صبيا فطرحه في البئر فتصايح أهل المدينة كلهم على باب لوط ، فلما نظروا إلى الغلمان في منزل لوط قالوا : يا لوط قد دخلت في عملنا ؟ فقال : هؤلاء ضيفي فلا تفضحوني في ضيفي. قالوا : هم ثلاثة خذ واحدا وأعطنا اثنين. ثم أدخلهم الحجرة ، وقال : لو أن لي أهل بيت يمنعوني منكم ؟ قال : و تدافعوا على الباب وكسروا باب لوط وطرحوا لوطا. فقال له جبرائيل : إنا رسل ربك لن يصلوا إليك ، فأخذ جبرائيل كفا من بطحاء فضرب بها وجوههم وقالوا : شاهت الوجوه. فعمي أهل المدينة كلهم وقال لهم لوط : يا رسل ربي فما أمركم ربي فيهم ؟ قالوا : أمرنا أن نأخذهم وقت السحر. قال : فلي إليكم حاجة ؟ قالوا : وما حاجتك ؟ قال : تأخذونهم الساعة ، فإني أخاف أن ي رحمهم‌الله سبحانه ويصرف العذاب عنهم. فقالوا : يا لوط إن موعدهم الصبح أليس بقريب لمن يريد أن يأخذ ؟ فخذ أنت بناتك وامض ودع امرأتك. و في رواية أخرى : ففعل لوط ما أمر وخرج ببناته ليلا ودعوا زوجته لأنها كانت منافقة ، ولما خرج لوط من المدينة وجاء الصباح قلع جبرائيل المدينة ورفعها إلى السماء ثم قلبها وأمطر الله عليها وعلى أطرافها حجارة من سجيل. وفي بعض التفاسير : أن زوجة لوط هي التي أخبرت القوم بالضيوف (1) . ( 1) الكافي : ج 5 ص 544. وَجاءَهُ قَوْمُهُ يُهْرَعُونَ إِلَيْهِ وَمِنْ قَبْلُ كانُوا يَعْمَلُونَ السَّيِّئاتِ قالَ يا قَوْمِ هؤُلاءِ بَناتِي هُنَّ أَطْهَرُ لَكُمْ فَاتَّقُوا اللهَ وَلا تُخْزُونِ فِي ضَيْفِي أَ لَيْسَ مِنْكُمْ رَجُلٌ رَشِيدٌ (78)` },
            { text: "يَٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَٰذَآ إِنَّهُۥ قَدْ جَآءَ أَمْرُ رَبِّكَ وَإِنَّهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ", tafsir: `` },
            { text: "وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌ", tafsir: `` },
            { text: "وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ قَالَ يَٰقَوْمِ هَٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ", tafsir: `أي توجه إلى طرف دار لوط ( قَوْمُهُ ) الكافرون ( يُهْرَعُونَ إِلَيْهِ ) يسرعون في المشي نحوه لطلب الفاحشة بالضيوف ، ولعل الإتيان بالمجهول لبيان كيفية الإسراع وأنه لم يكن هرع عقلاء وإنما هرع شهوة حيث قد انطوت أنفسهم على حب هذا العمل الشنيع ، فكانت نفوسهم تسوقهم من حيث لا يشعرون ( وَمِنْ قَبْلُ ) إتيان الملائكة أو من قبل وقوع هذه القصة ( كانُوا ) أي كان قوم لوط ( يَعْمَلُونَ السَّيِّئاتِ ) جمع « سيئة » والمراد بها اللواط ، وهذا لبيان وجه أنه عليه‌السلام ضاق بهم ذرعا ورأى اليوم عصيبا. ( قالَ ) لوط عليه‌السلام لما رأى إصرار القوم على السيئة : ( يا قَوْمِ هؤُلاءِ بَناتِي هُنَّ أَطْهَرُ لَكُمْ ) فتزوجوا بهن واعملوا حيث أمركم الله ، ففي المرأة الطهارة النفسية والطهارة الجسدية ، وإني مستعد أن أقدم بناتي لكم لئلّا تعملوا بالمعاصي ولئلّا تفضحونني في ضيوفي. وهنا احتمال أنه عليه‌السلام أراد من « بناتي » بنات المدينة ، وأضافهن إلى نفسه لأن كبير الناس يضيف الأفراد إلى نفسه ، أي : تزوجوا البنات عوض هذا العمل ( فَاتَّقُوا اللهَ ) خافوا عقابه في عمل اللواط ( وَلا تُخْزُونِ ) أي لا تلزموني عارا ( فِي ضَيْفِي ) فإن الضيف لو أهين كان ذلك خزيا للمضيف وعارا عليه ( أَ لَيْسَ مِنْكُمْ رَجُلٌ رَشِيدٌ ) استفهام توبيخي ، أي أليس فيكم رجل أو رشيد لا سفاهة به يمنعكم عن اقتراف هذه الجريمة وعن أن يهتك أمري بالنسبة إلى ضيوفي ، حتى قالُوا لَقَدْ عَلِمْتَ ما لَنا فِي بَناتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ ما نُرِيدُ (79) قالَ لَوْ أَنَّ لِي بِكُمْ قُوَّةً أَوْ آوِي إِلى رُكْنٍ شَدِيدٍ (80) لا يبقى عارها عليّ مدى الحياة ؟` },
            { text: "قَالُوا۟ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ", tafsir: `أي قال القوم في جواب لوط عليه‌السلام : ( لَقَدْ عَلِمْتَ ) يا لوط ( ما لَنا فِي بَناتِكَ مِنْ حَقٍ ) أي من حاجة ، فكما لا يرغب الإنسان فيما لا حق له فيه ، كذلك لا يرغب فيما لا حاجة له فيه ، أو لأن من حق الرجل أن يتزوج البنت ، أما إذا لم يرد فكأنه لا حق له فيها ، أو المراد ب « الحق » الحصة ، أي لا حصة لنا فيهن ( وَإِنَّكَ ) يا لوط ( لَتَعْلَمُ ما نُرِيدُ ) من الضيوف وعمل السيئة بهم. [81] وهنا انقطع لوط عليه‌السلام ويئس وحزن و ( قالَ ) في أسف بالغ : ( لَوْ أَنَّ لِي بِكُمْ قُوَّةً ) فأكون قويا قادرا على دفعكم ، و « الباء » في « بكم » إما للمقابلة أي بمقابلتكم ، أو بمعنى « على » أي عليكم ، وحذف جواب « لو » توسعة في المتعلق ، أو لوضوح أن المراد « لمنعتكم » ( أَوْ آوِي ) من « أوى يأوي » بمعنى : لجأ ( إِلى رُكْنٍ شَدِيدٍ ) يمنعني منكم ، أي : لو تمكّنت أن أستعين بقوة عشيرة أو ما أشبهها لدفعتكم ومنعتكم. في الحديث : إن جبرائيل قال ـ حين قال لوط ذلك ـ : « لو يعلم أية قوة له ؟ » (1) . و روي عن النبي صلى‌الله‌عليه‌وآله‌وسلم أنه قال : « رحم الله أخي لوطا كان يأوي إلى ركن شديد » . ( 1) الكافي : ج 5 ص 546. قالُوا يا لُوطُ إِنَّا رُسُلُ رَبِّكَ لَنْ يَصِلُوا إِلَيْكَ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِنَ اللَّيْلِ وَلا يَلْتَفِتْ مِنْكُمْ أَحَدٌ إِلاَّ امْرَأَتَكَ إِنَّهُ مُصِيبُها ما أَصابَهُمْ إِنَّ مَوْعِدَهُمُ [82] وهنا تكلم الرسل و ( قالُوا يا لُوطُ إِنَّا رُسُلُ رَبِّكَ ) أرسلنا لإنقاذك وهلاك القوم. روي أن جبرائيل قال للوط : دعهم يدخلوا. فلما دخلوا أهوى جبرائيل بإصبعه نحوهم ، فذهبت أعينهم كما قال سبحانه : ( فَطَمَسْنا أَعْيُنَهُمْ ) (1) ، ( لَنْ يَصِلُوا إِلَيْكَ ) أي لا يقدرون أن يهجموا عليك وينالوا منك سوءا في نفسك أو ضيوفك. ورجع القوم عن دار لوط خائبين من رعب الملائكة فقد ألقي في قلوبهم رعب شديد ، وصاروا كلهم عميانا لا يبصرون. وهنا توجهت الملائكة إلى لوط وقالوا له : ( فَأَسْرِ ) أي سر ليلا واخرج من هذه المدينة ، ( بِأَهْلِكَ ) « الباء » بمعنى « مع » أي مع أهلك ( بِقِطْعٍ مِنَ اللَّيْلِ ) أي بعد ذهاب بعض الليل وقطعة منه ، فإن القطع من الليل : بعضه ( وَلا يَلْتَفِتْ مِنْكُمْ أَحَدٌ ) إما بمعنى : لا يتخلّف في المدينة أحد منكم لأن كل من في المدينة سوف يصيبهم العذاب ، وإما بمعنى : لا ينظر أحد ورائه حين السير لئلّا يرى ما يزعجه من عذاب هؤلاء ( إِلَّا امْرَأَتَكَ ) استثناء من « أسر بأهلك » يعني فلتتخلف امرأتك ، لأنها كانت مع القوم ضدك يا لوط ( إِنَّهُ مُصِيبُها ما أَصابَهُمْ ) أي يصيبها من العذاب ما أصاب القوم ، فاللازم عليك أن لا تخبرها وأن تخلّفها في المدينة ( إِنَّ مَوْعِدَهُمُ ) أي وقت هلاكهم ( 1) القمر : 38. الصُّبْحُ أَ لَيْسَ الصُّبْحُ بِقَرِيبٍ (81) فَلَمَّا جاءَ أَمْرُنا جَعَلْنا عالِيَها سافِلَها وَأَمْطَرْنا عَلَيْها حِجارَةً مِنْ سِجِّيلٍ مَنْضُودٍ (82) مُسَوَّمَةً عِنْدَ رَبِّكَ وَما هِيَ مِنَ الظَّالِمِينَ بِبَعِيدٍ (83) وعذابهم ( الصُّبْحُ أَ لَيْسَ الصُّبْحُ بِقَرِيبٍ ) وهذا ما قالته الملائكة للوط حين استعجل عذابهم في ذلك الوقت.` },
            { text: "قَالَ لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍ شَدِيدٍ", tafsir: `` },
            { text: "قَالُوا۟ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓا۟ إِلَيْكَ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا ٱمْرَأَتَكَ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمْ إِنَّ مَوْعِدَهُمُ ٱلصُّبْحُ أَلَيْسَ ٱلصُّبْحُ بِقَرِيبٍ", tafsir: `` },
            { text: "فَلَمَّا جَآءَ أَمْرُنَا جَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ مَّنضُودٍ", tafsir: `بإهلاكهم ( جَعَلْنا عالِيَها ) أي عالي المدينة ( سافِلَها ) بأن قلبناها فإن جبرائيل أدخل جناحه تحت الأرض ثم قلبها بأن جعل أسفلها أعلاها ( وَأَمْطَرْنا عَلَيْها ) الظاهر أن الإمطار كان على نفس الناس ، و « الواو » لا تدل على تأخير الإمطار عن القلب ، وإن كان الترتيب الذكري قد يعطيه ، لأن « الواو » لمطلق الجمع كما ذكره أهل اللغة ( حِجارَةً مِنْ سِجِّيلٍ ) قيل : إنه معرّب « سنك كل » كلمتان فارسيتان بمعنى المدر ، ولا شاهد لذلك ( مَنْضُودٍ ) هو صفة سجيل ، أي متراكم بعضه يلاحق بعضا ، أو نضد بعضه على بعض حتى صار سجيلا ، أي صار حجرا.` },
            { text: "مُّسَوَّمَةً عِندَ رَبِّكَ وَمَا هِىَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٍ", tafsir: `أي معلّمة ، جعل فيها علامات تدل على أنها معدّة للعذاب ( عِنْدَ رَبِّكَ ) في علمه سبحانه ، وفي خزائنه التي لا يتصرف فيها أحد سواه. وكان ذكر هذه الأوصاف للتهويل ، وإن الله سبحانه قد أعد لهم في خزائنه حجارة منضودة معلمة ، كما أن الملك يهيئ لأعدائه سيوفا معلومة معلمة في خزائنه ليكون على استعداد تام ( وَما هِيَ ) أي حجارة السجيل ( مِنَ الظَّالِمِينَ بِبَعِيدٍ ) فلا يستبعد أحد كيف يعذب وَإِلى مَدْيَنَ أَخاهُمْ شُعَيْباً قالَ يا قَوْمِ اعْبُدُوا اللهَ ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ وَلا تَنْقُصُوا الْمِكْيالَ وَالْمِيزانَ إِنِّي أَراكُمْ بِخَيْرٍ وَإِنِّي أَخافُ عَلَيْكُمْ عَذابَ يَوْمٍ مُحِيطٍ (84) الله أحدا بإمطار الحجارة ؟ إنهم ظلموا فاستحقوا العقاب. و في بعض الأحاديث : إنها مهيأة لظالمي هذه الأمة أيضا (1) .` },
            { text: "وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ وَلَا تَنقُصُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ إِنِّىٓ أَرَىٰكُم بِخَيْرٍ وَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ", tafsir: `أرسلنا ( إِلى مَدْيَنَ ) وهم قبيلة سمّوا باسم جدهم مدين بن إبراهيم ، أو أنها اسم مدينة. وفي الكلام حذف ، أي : أرسلنا إلى أهل مدين ـ لكن السياق يقوّي الأول ـ ( أَخاهُمْ ) في النسب ( شُعَيْباً ) وهذه القصة قد ذكرت في سورة الأعراف باختلاف في ذكر بعض الخصوصيات هنا ـ كما هو الشأن في القصص القرآنية ـ فإن القرآن يأخذ في كل موضع طرفا من القصة لإدراجه في المقصود العام المساق له الكلام ( قالَ يا قَوْمِ اعْبُدُوا اللهَ ) وحده لا شريك له ( ما لَكُمْ ) أي ليس لكم ( مِنْ إِلهٍ غَيْرُهُ ) من الأصنام التي تعبدونها ( وَلا تَنْقُصُوا الْمِكْيالَ وَالْمِيزانَ ) أي لا تعطوا الناس أنقص من حقوقهم عند الكيل والوزن بالتطفيف ، و « المكيال » آلة الكيل ، كما أن « الميزان » آلة الوزن ، على وزن « مفتاح » ( إِنِّي أَراكُمْ بِخَيْرٍ ) فقد أنعم الله عليكم بالرزق فلا تحتاجون معه إلى التطفيف والسرقة من الناس ( وَإِنِّي أَخافُ عَلَيْكُمْ ) إن بقيتم في الكفر وعملتم بالتطفيف ( عَذابَ يَوْمٍ مُحِيطٍ ) يحيط بكم ( 1) راجع مجمع البيان : ج 5 ص 317. وَيا قَوْمِ أَوْفُوا الْمِكْيالَ وَالْمِيزانَ بِالْقِسْطِ وَلا تَبْخَسُوا النَّاسَ أَشْياءَهُمْ وَلا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ (85) بَقِيَّتُ اللهِ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ فلا ينجو منه أحد.` },
            { text: "وَيَٰقَوْمِ أَوْفُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ بِٱلْقِسْطِ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ", tafsir: `بالعدل. وقد كان من عادة الأنبياء عليهم‌السلام أن يركزوا جهودهم بعد الدعوة إلى التوحيد والمعاد ، على النقطة المنحرفة في القوم كما ركّز لوط عليه‌السلام جهوده لإزالة الانحراف الجنسي في قومه. وكان الانحراف العام في قوم شعيب بعد عبادة الأصنام تطفيف المكيال والميزان ، ولذا أكد على ذلك بالقول مكررا ، مرة بالنهي عن التطفيف ، ومرة بالأمر بإيفاء الكيل ( وَلا تَبْخَسُوا النَّاسَ أَشْياءَهُمْ ) أي لا تنقصوهم حقوقهم ، فإن البائع إذا باع منّا ثم أعطى أقل من ذلك فقد نقص وبخس حق المشتري ( وَلا تَعْثَوْا ) من « عاث » بمعنى سعى في الفساد ( فِي الْأَرْضِ مُفْسِدِينَ ) حال كونكم تفسدون. وهذا حال تأكيدي لأنه بمعنى الفعل ، وإنما جيء به لأن المفسد قد لا يعلم بإفساده ، فهو يريد النهي عن الإفساد عمدا ، أي لا تفسدوا متعمدين الإفساد قاصدين إليه بالذات.` },
            { text: "بَقِيَّتُ ٱللَّهِ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ", tafsir: `الذي يبقى بإذن الله وإجازته وإباحته ، وأضيف إليه تشريفا ( خَيْرٌ لَكُمْ ) أي ما أبقى الله تعالى لكم من الحلال بعد إتمام الكيل والوزن خير لكم من التطفيف والبخس ، فإنه أكثر بركة وأحسن عاقبة. وما ورد من أن الأئمة عليهم‌السلام والحجة عليه‌السلام ـ بصورة خاصة ـ بقية الله ، يراد بذلك أنهم وأنه عليه‌السلام هم الذين أبقاهم الله سبحانه للهداية والإرشاد ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) أي لو كنتم مؤمنين لعلمتم أن بقية الله وَما أَنَا عَلَيْكُمْ بِحَفِيظٍ (86) قالُوا يا شُعَيْبُ أَ صَلاتُكَ تَأْمُرُكَ أَنْ نَتْرُكَ ما يَعْبُدُ آباؤُنا أَوْ أَنْ نَفْعَلَ فِي أَمْوالِنا ما نَشؤُا إِنَّكَ لَأَنْتَ الْحَلِيمُ الرَّشِيدُ (87) قالَ يا قَوْمِ أَ رَأَيْتُمْ إِنْ كُنْتُ عَلى بَيِّنَةٍ مِنْ رَبِّي وَرَزَقَنِي مِنْهُ خير ، أو أن خيرية البقية مشروطة بالإيمان ( وَما أَنَا عَلَيْكُمْ بِحَفِيظٍ ) أحفظكم عن الحرام وعن العذاب ، وإنما أنا مذكّر مرشد ، فإن قبلتم قولي نجوتم ، وإن لم تقبلوا أهلكتكم.` },
            { text: "قَالُوا۟ يَٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَٰٓؤُا۟ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ", tafsir: `أي قال القوم في جواب إرشادات شعيب بالتوحيد وإيفاء المكيال والميزان : ( يا شُعَيْبُ أَ صَلاتُكَ ) التي تصليها لله ( تَأْمُرُكَ أَنْ نَتْرُكَ ما يَعْبُدُ آباؤُنا ) قالوا ذلك على نحو التهكّم والاستهزاء ، كأن الصلاة قد دفعت شعيب لهدم دين القوم ( أَوْ أَنْ نَفْعَلَ فِي أَمْوالِنا ما نَشؤُا ) أي هل الصلاة تأمر أن نترك التطفيف. ومن المعلوم أن في الكلام حذفا تقديره : « أ صلاتك تكلّفك أن تأمرنا بترك عبادة الأصنام وترك التطفيف في المكيال والميزان » ( إِنَّكَ ) يا شعيب ( لَأَنْتَ الْحَلِيمُ الرَّشِيدُ ) قالوا ذلك على وجه الاستهزاء ، فإن الداعي الذي لا قوة له ولا طول كثيرا ما يظهر في مظهر الحليم ذي الرشد الذي يكتم غضبه وأسفه في مقابل الجهلة الذين لا يلبّون طلبه. والمراد : إنك مصطنع ذلك لاقتناص السيادة.` },
            { text: "قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًا وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَٰحَ مَا ٱسْتَطَعْتُ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ", tafsir: `شعيب في جواب استهزاء القوم : ( يا قَوْمِ أَ رَأَيْتُمْ ) أي أخبروني ( إِنْ كُنْتُ عَلى بَيِّنَةٍ ) حجة واضحة على نبوتي وصدق ادعائي ( مِنْ رَبِّي ) أي من طرفه سبحانه ( وَرَزَقَنِي مِنْهُ ) من عنده تعالى رِزْقاً حَسَناً وَما أُرِيدُ أَنْ أُخالِفَكُمْ إِلى ما أَنْهاكُمْ عَنْهُ إِنْ أُرِيدُ إِلاَّ الْإِصْلاحَ مَا اسْتَطَعْتُ وَما تَوْفِيقِي إِلاَّ بِاللهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ (88) ( رِزْقاً حَسَناً ) بإعطائي النبوة والتوسعة عليّ في معاشي. والجواب محذوف ، أي : هل يسعني أن أترك عبادته وطاعته أو أخون وحيه فلا أبلغه ولا أؤديه ؟! ( وَما أُرِيدُ أَنْ أُخالِفَكُمْ ) عملا ( إِلى ما أَنْهاكُمْ عَنْهُ ) بأن أرتكب القبائح التي أنهاكم عنها ، فأريد أن تتركوها وأعملها أنا. ولعلّه إنما تكلم بهذا ، لما يرى المصلحون ـ غالبا ـ أنهم يفعلون ما ينهون الناس عنه ، وإنما يريدون أن يتنازل الناس عن قسم من شهواتهم ليأتوها هم ( إِنْ أُرِيدُ إِلَّا الْإِصْلاحَ ) أي ما أريد من دعوتي إلا الإصلاح لكم عن المفاسد ( مَا اسْتَطَعْتُ ) أي على قدر استطاعتي. قال بعض المفسرين : إن قوله عليه‌السلام « إن كنت على بينة » إشارة إلى حق الله ، وقوله « ما أريد » إشارة إلى حق النفس ، وقوله « إن أريد » إشارة إلى حق المجتمع. ( وَما تَوْفِيقِي إِلَّا بِاللهِ ) « التوفيق » مصدر « وفق » أي : تجمّع الأسباب لدى الإنسان ، وصيرورة بعضها وفق بعض لأخذ النتيجة. وغالبا تستعمل هذه اللفظة في التوفيق للأمور الحسنة وإن كان معناها اللغوي أعم ، فإن توفيقي في الكف عن القبائح والإطاعة ، والقيام بالدعوة إنما هو من عند الله سبحانه فإنه هو الذي أرشدني وهيأ لي أسباب ذلك ( عَلَيْهِ تَوَكَّلْتُ ) والتوكل على الله : الرضا بتدبيره ، واتخاذه ظهرا في الأمور بالالتجاء والتضرّع إليه ( وَإِلَيْهِ أُنِيبُ ) أي أرجع في أموري كلها إليه ، فكما أن الإنسان إذا كان له ظهر وركن وَيا قَوْمِ لا يَجْرِمَنَّكُمْ شِقاقِي أَنْ يُصِيبَكُمْ مِثْلُ ما أَصابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صالِحٍ وَما قَوْمُ لُوطٍ مِنْكُمْ بِبَعِيدٍ (89) وَاسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ إِنَّ رَبِّي رَحِيمٌ وَدُودٌ (90) قالُوا يا شُعَيْبُ ما نَفْقَهُ يلجأ إليه ليستمد منه القوة في نوائبه ، كذلك من اتخذ الله ظهيرا رجع إليه في حوائجه بالتوسل إليه لقضاء حوائجه. [90] ثم أخذ شعيب ينصح القوم ويذكرهم بمصارع الأقوام السابقة الذين خالفوا النبيين فأهلكوا ( وَيا قَوْمِ لا يَجْرِمَنَّكُمْ شِقاقِي ) أي لا يحملنّكم الخلاف معي والعناد واللجاج ( أَنْ يُصِيبَكُمْ ) العذاب ، فعنادكم يلجئكم إلى الكفر والتمادي في الغيّ حتى يصيبكم العذاب ( مِثْلُ ما أَصابَ قَوْمَ نُوحٍ ) من الغرق ( أَوْ قَوْمَ هُودٍ ) من الريح الصرصر ( أَوْ قَوْمَ صالِحٍ ) من الرجفة ( وَما قَوْمُ لُوطٍ مِنْكُمْ بِبَعِيدٍ ) فإنهم أهلكوا في عهد قريب ، خالفوا الرسول وتمادوا في الفساد ، فإن لم تعتبروا بالمتقدمين ، فاعتبروا بهؤلاء القريبين منكم.` },
            { text: "وَيَٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِىٓ أَن يُصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَٰلِحٍ وَمَا قَوْمُ لُوطٍ مِّنكُم بِبَعِيدٍ", tafsir: `` },
            { text: "وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى رَحِيمٌ وَدُودٌ", tafsir: `اطلبوا غفرانه لما سلف منكم من الكفر والمعاصي ( ثُمَّ تُوبُوا إِلَيْهِ ) أي ارجعوا إليه في عقيدتكم وأعمالكم ، فالاستغفار لما مضى ، والتوبة لما يأتي ( إِنَّ رَبِّي رَحِيمٌ ) بكم ، فإذا فعلتم ما ذكرته رحمكم وتلطّف بكم ( وَدُودٌ ) أي محبّ لكم ، ومعنى ذلك أنه يفعل بهم ما يفعل المحب بمحبّه.` },
            { text: "قَالُوا۟ يَٰشُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًا وَلَوْلَا رَهْطُكَ لَرَجَمْنَٰكَ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزٍ", tafsir: `أي قال القوم بعد أن وعظهم شعيب بتلك الموعظة البالغة : ( يا شُعَيْبُ ما نَفْقَهُ ) أي ما نفهم ، فإن « الفقه » في اللغة بمعنى « الفهم » كَثِيراً مِمَّا تَقُولُ وَإِنَّا لَنَراكَ فِينا ضَعِيفاً وَلَوْ لا رَهْطُكَ لَرَجَمْناكَ وَما أَنْتَ عَلَيْنا بِعَزِيزٍ (91) قالَ يا قَوْمِ أَ رَهْطِي أَعَزُّ عَلَيْكُمْ مِنَ اللهِ وَاتَّخَذْتُمُوهُ وَراءَكُمْ ظِهْرِيًّا إِنَّ رَبِّي بِما تَعْمَلُونَ مُحِيطٌ (92) وَيا قَوْمِ اعْمَلُوا عَلى مَكانَتِكُمْ ( كَثِيراً مِمَّا تَقُولُ ) وهذا كلام المعاند فإنه يقول مثل ذلك ويريد أنه معرض عن كلام المتكلم ، فقد أقيم السبب مقام المسبب لأن عدم العمل معلول لعدم العلم ( وَإِنَّا لَنَراكَ فِينا ضَعِيفاً ) لا قوة لك ولا عزة ، فلا تتمكن من دفع أذانا لو أردنا إيذاءك ( وَلَوْ لا ) وجود ( رَهْطُكَ ) أي عشيرتك ، وحرمتهم عندنا ( لَرَجَمْناكَ ) أي لقتلناك بالحجارة ( وَما أَنْتَ عَلَيْنا بِعَزِيزٍ ) أي لا عزّة لك عندنا. وكأن الإتيان بلفظ « علينا » لأجل أن العزيز فوق الناس مرتبة ومقاما.` },
            { text: "قَالَ يَٰقَوْمِ أَرَهْطِىٓ أَعَزُّ عَلَيْكُم مِّنَ ٱللَّهِ وَٱتَّخَذْتُمُوهُ وَرَآءَكُمْ ظِهْرِيًّا إِنَّ رَبِّى بِمَا تَعْمَلُونَ مُحِيطٌ", tafsir: `شعيب عليه‌السلام : ( يا قَوْمِ أَ رَهْطِي ) أي هل عشيرتي وقومي ( أَعَزُّ عَلَيْكُمْ مِنَ اللهِ ) فتتركون إيذائي لأجل حرمة عشيرتي ، ولا تتركون إيذائي لأجل الله سبحانه ، أي تراقبون العشيرة ولا تراقبون إله العشيرة وخالق الجميع. قال هذا الكلام على نحو الاستفهام الإنكاري ( وَاتَّخَذْتُمُوهُ ) جعلتم الله سبحانه ( وَراءَكُمْ ظِهْرِيًّا ) جعلتموه كالمنسي المنبوذ وراء ظهوركم ، ومعنى « الظهري » جعل الشيء وراء الظهر حتى ينسى ( إِنَّ رَبِّي بِما تَعْمَلُونَ مُحِيطٌ ) قد أحاط علمه بأعمالكم ، فلا يخفى عليه شيء تصنعونه ، فيجازيكم عليه.` },
            { text: "وَيَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَٰذِبٌ وَٱرْتَقِبُوٓا۟ إِنِّى مَعَكُمْ رَقِيبٌ", tafsir: `أي على المكانة التي أنتم عليها من الكفر والعصيان ، فإن « المكانة » هي الحالة التي يتمكن بها صاحبها من إِنِّي عامِلٌ سَوْفَ تَعْلَمُونَ مَنْ يَأْتِيهِ عَذابٌ يُخْزِيهِ وَمَنْ هُوَ كاذِبٌ وَارْتَقِبُوا إِنِّي مَعَكُمْ رَقِيبٌ (93) وَلَمَّا جاءَ أَمْرُنا نَجَّيْنا شُعَيْباً وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا العمل. وهذا تهديد يريد : أنكم سترون جزاء أعمالكم السيئة ( إِنِّي عامِلٌ ) حسب أمر الله سبحانه ولا أ تزحزح عن أوامره ، فهذا كقوله : ( لَكُمْ دِينُكُمْ وَلِيَ دِينِ ) (1) ، ( سَوْفَ تَعْلَمُونَ ) في الدنيا ( مَنْ ) منّا ( يَأْتِيهِ عَذابٌ يُخْزِيهِ ) يهينه ويفضحه ، هل أنتم أم أنا ؟ فيتبيّن من هو الصادق ( وَمَنْ هُوَ كاذِبٌ ) منّا ( وَارْتَقِبُوا ) انتظروا ما وعدكم ربكم من العذاب ( إِنِّي مَعَكُمْ رَقِيبٌ ) وإني أيضا أنتظر وأرتقب ما وعدتكم أن يأتيكم ، ليدلّ على صدقي وصحة رسالتي. [95] وهكذا بقي القوم في الغيّ وتمادوا في الكفر والعصيان ، ولم تنفعهم نصائح شعيب عليه‌السلام حتى جاءهم العذاب ( وَلَمَّا جاءَ أَمْرُنا ) بعذابهم ( نَجَّيْنا شُعَيْباً وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا ) حيث رحمناهم فلم يشملهم العذاب ، وإن كان المؤمنون به مستحقين للعذاب أيضا لما تقدم أن كل إنسان ـ غير معصوم ـ لا بد وأن يصدر منه ذنب يستحق العقاب به فتكون نجاة كل فرد برحمته سبحانه. قال في تفسير الصافي : وإنما ذكر هنا وفي قصة عاد ب « الواو » أي « ولما » ، وفي قصتي صالح وهود ب « الفاء » أي « فلما » ، لسبق ذكر وعد يجري مجرى السبب في قصتي صالح وهود دون الآخرين. انتهى (2) . ( 1) الكافرون : 7. ( 2) تفسير الصافي : ج 2 ص 470. وَأَخَذَتِ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيارِهِمْ جاثِمِينَ (94) كَأَنْ لَمْ يَغْنَوْا فِيها أَلا بُعْداً لِمَدْيَنَ كَما بَعِدَتْ ثَمُودُ (95) وَلَقَدْ أَرْسَلْنا مُوسى بِآياتِنا وَسُلْطانٍ مُبِينٍ (96) واحتمل بعض أن يكون قوله : « برحمة منّا » لأجل أن نجاتهم كانت بسبب هداية الله لهم وألطافه الخفية الموجبة لخروجهم عن حظيرة الكفار. ( وَأَخَذَتِ الَّذِينَ ظَلَمُوا الصَّيْحَةُ ) فقد صاح بهم جبرائيل عليه‌السلام صيحة شديدة زهقت روح كل واحد منهم في مكانه ( فَأَصْبَحُوا فِي دِيارِهِمْ جاثِمِينَ ) من « جثم » في المكان إذا أقام فيه ، أي ماتوا وهم في ديارهم ، ولم يتمكنوا من الحراك أصلا.` },
            { text: "وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ", tafsir: `` },
            { text: "كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَا بُعْدًا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ", tafsir: `من « غنى في المكان » إذا أقام فيه ، أي كأنهم لم يكونوا بتلك الديار ، فقد ذهبت آثارهم ، وعفت رسومهم ( أَلا بُعْداً لِمَدْيَنَ ) فلينتبه السامع إلى طرد قبيلة مدين من رحمة الله ولطفه ( كَما بَعِدَتْ ثَمُودُ ) ولعلّ ذكر ثمود هنا لأن كلتا الأمتين ماتتا بالصيحة. وربما احتمل أن المراد ب « الصيحة » نوع من العذاب ، تقول العرب : « صاح الزمان بهم » إذا أهلكوا. [97] ثم يحكي القرآن الحكيم القصة السابقة في هذه السورة وهي قصة موسى عليه‌السلام وفرعون ( وَلَقَدْ أَرْسَلْنا مُوسى بِآياتِنا ) أي مع الأدلة الدالة على كونه من طرفنا ، وهي الثعبان واليد البيضاء وغيرهما ( وَسُلْطانٍ مُبِينٍ ) أي حجة واضحة عقلية على أن للكون إلها ، وأن فرعون ليس بإله للناس. إِلى فِرْعَوْنَ وَمَلائِهِ فَاتَّبَعُوا أَمْرَ فِرْعَوْنَ وَما أَمْرُ فِرْعَوْنَ بِرَشِيدٍ (97) يَقْدُمُ قَوْمَهُ يَوْمَ الْقِيامَةِ فَأَوْرَدَهُمُ النَّارَ وَبِئْسَ الْوِرْدُ الْمَوْرُودُ (98) وَأُتْبِعُوا فِي هذِهِ لَعْنَةً وَيَوْمَ` },
            { text: "وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ", tafsir: `` },
            { text: "إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱتَّبَعُوٓا۟ أَمْرَ فِرْعَوْنَ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍ", tafsir: `إما المراد : الأشراف منهم ، وتخصيص الذكر بهم لأنهم إذا أذعنوا أذعن الناس كلهم ، أو المراد بالملإ : قومه كلهم ( فَاتَّبَعُوا ) أي اتبع الملأ ( أَمْرَ فِرْعَوْنَ ) في اتخاذه إلها والإعراض عن موسى وحججه ( وَما أَمْرُ فِرْعَوْنَ بِرَشِيدٍ ) أي ما هو هاد لهم إلى الرشد. وهو خلاف « السفه » فإن أمره غير مرشد وغير صحيح ، بل فيه ضلالة وسفاهة. [99] وكيف يكون أمره رشيدا ، والحال أنه وأتباعه يصيرون إلى النار ؟! وهل الرشد ما يسبب الهلاك والعقاب ؟! ( يَقْدُمُ ) فرعون ( قَوْمَهُ ) يتقدم عليهم ويمشي بين أيديهم ( يَوْمَ الْقِيامَةِ فَأَوْرَدَهُمُ النَّارَ ) جميعا ، ففي الدنيا كان يهديهم إلى النار ، وفي الآخرة يدخلهم فيها ( وَبِئْسَ الْوِرْدُ الْمَوْرُودُ ) « الورد » ورد الماء الذي يورد ، أي : بئس الماء الذي يردونه عطشى ، فإنه نار يردونها ، فقد شبّه هؤلاء بأهل الجنة حيث يردون المياه الجارية وأنهار من لبن وعسل وخمر ، وهؤلاء في مقابل أولئك يردون النار ويسقون من الحميم. قال بعض المفسرين : أوردهم كما يورد الراعي قطيع الغنم ، ألم يكونوا قطيعا يسير بدون تفكير ؟` },
            { text: "يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ", tafsir: `` },
            { text: "وَأُتْبِعُوا۟ فِى هَٰذِهِۦ لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ بِئْسَ ٱلرِّفْدُ ٱلْمَرْفُودُ", tafsir: `ألحقوا ( فِي هذِهِ ) الدنيا ( لَعْنَةً ) إما بالغرق ، وإما بأن الناس يلعنونهم ، فكانت نتيجة اتّباعهم لفرعون أن تبعتهم اللعنة ( وَيَوْمَ الْقِيامَةِ بِئْسَ الرِّفْدُ الْمَرْفُودُ (99) ذلِكَ مِنْ أَنْباءِ الْقُرى نَقُصُّهُ عَلَيْكَ مِنْها قائِمٌ وَحَصِيدٌ (100) وَما ظَلَمْناهُمْ وَلكِنْ ظَلَمُوا أَنْفُسَهُمْ فَما أَغْنَتْ عَنْهُمْ آلِهَتُهُمُ الَّتِي يَدْعُونَ مِنْ دُونِ اللهِ مِنْ شَ يْءٍ لَمَّا جاءَ أَمْرُ رَبِّكَ الْقِيامَةِ ) يتبعون باللعنات والعذاب ( بِئْسَ الرِّفْدُ ) أي العطاء ( الْمَرْفُودُ ) المعطى لهم ذلك العذاب واللعنة ، إن هذا كان عطاء فرعون لقومه ، لهم النار واللعنة ، وهذا هو عاقبة من تخلّف عن الحق واتبع الباطل. [101] ثم بيّن سبحانه الغرض الذي سيق من أجله تلك القصص ، وجعله كخاتمة للفصول المتقدمة ( ذلِكَ ) الذي ذكرناه فيما تقدم من هذه السورة ( مِنْ أَنْباءِ الْقُرى ) أي أخبار البلاد السابقة والأمم الخالية ( نَقُصُّهُ عَلَيْكَ ) ونخبره لك ليكون لك سلوة وذكرى ( مِنْها ) أي من تلك القرى ( قائِمٌ ) باق إلى الآن ، فإن بعض البلاد بقيت وإن هلك أهلها ، كمصر ( وَحَصِيدٌ ) أي منها حصيد قد حصد وعفا أثره ، كقرى قوم لوط عليه‌السلام .` },
            { text: "ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْقُرَىٰ نَقُصُّهُۥ عَلَيْكَ مِنْهَا قَآئِمٌ وَحَصِيدٌ", tafsir: `` },
            { text: "وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن ظَلَمُوٓا۟ أَنفُسَهُمْ فَمَآ أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ ٱلَّتِى يَدْعُونَ مِن دُونِ ٱللَّهِ مِن شَىْءٍ لَّمَّا جَآءَ أَمْرُ رَبِّكَ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ", tafsir: `أي نحن لم نظلم الذين هلكوا ( وَلكِنْ ظَلَمُوا أَنْفُسَهُمْ ) بالكفر والعصيان وهما سببين للهلاك والنكال ( فَما أَغْنَتْ عَنْهُمْ ) أي لم تنفعهم ولم تفدهم ( آلِهَتُهُمُ ) أصنامهم البشرية ، كفرعون ، والحجرية ، كالأوثان التي كانوا يعبدونها و ( الَّتِي ) كانوا ( يَدْعُونَ ) ها ( مِنْ دُونِ اللهِ ) ويتخذونها أربابا ( مِنْ شَيْءٍ ) متعلق به « ما أغنت عنهم » أي لم تنفعهم شيئا في دفع العذاب عنهم ( لَمَّا جاءَ أَمْرُ رَبِّكَ ) بإهلاكهم وَما زادُوهُمْ غَيْرَ تَتْبِيبٍ (101) وَكَذلِكَ أَخْذُ رَبِّكَ إِذا أَخَذَ الْقُرى وَهِيَ ظالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ (102) إِنَّ فِي ذلِكَ لَآيَة ً لِمَنْ خافَ عَذابَ الْآخِرَةِ ونزول العذاب عليهم ( وَما زادُوهُمْ ) ما زادتهم تلك الآلهة ( غَيْرَ تَتْبِيبٍ ) من « التباب » أي الخسارة ، أي أن الآلهة زادتهم خسارة على خسارتهم ، فإنهم لو لم يكونوا يعبدونها ، بل كانوا مجرد عاصين لم يزد في عذابهم ، فقد جاء من قبل تلك الآلهة زيادة في عذابهم ونكالهم ، وإنما قال : « زادوهم » بضمير العاقل ، لأن الكفار كانوا يعتبرونها عاقلة ، فجرى الكلام حسب اعتقادهم.` },
            { text: "وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ٱلْقُرَىٰ وَهِىَ ظَٰلِمَةٌ إِنَّ أَخْذَهُۥٓ أَلِيمٌ شَدِيدٌ", tafsir: `الذي بيّناه سابقا وأوضحناه ( أَخْذُ رَبِّكَ ) وهلاكه ( إِذا أَخَذَ الْقُرى وَهِيَ ظالِمَةٌ ) أي أهلكهم وعذبهم ، فقد شبّه الإهلاك بالأخذ ، فكما أن الأخذ لا يتمكن المأخوذ من الإفلات منه كذلك الذين عذبهم سبحانه لا يتمكنون من النجاة. روي عن النبي صلى‌الله‌عليه‌وآله‌وسلم أنه قال : « إن الله تعالى يمهل الظالم حتى إذا أخذه لم يفلته ثم قرأ الآية » (1) . ( إِنَّ أَخْذَهُ ) للظالم ( أَلِيمٌ ) مؤلم موجع ( شَدِيدٌ ) فلا يمكن الإفلات منه.` },
            { text: "إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّمَنْ خَافَ عَذَابَ ٱلْـَٔاخِرَةِ ذَٰلِكَ يَوْمٌ مَّجْمُوعٌ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوْمٌ مَّشْهُودٌ", tafsir: `الذي تقدم من أحوال الأمم التي كفرت وعصت الرسل ( لَآيَةً ) دليل على بطش الله سبحانه لمن طغى وتكبّر ( لِمَنْ خافَ عَذابَ الْآخِرَةِ ) أي لمن آمن لعلمه بأنه أنموذج من ذلك العذاب المهول ، فإن ذلك الأخذ الأليم الشديد مشابه لعذاب الآخرة لمن ( 1) بحار الأنوار : ج 67 ص 335. ذلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ وَذلِكَ يَوْمٌ مَشْهُودٌ (103) وَما نُؤَخِّرُهُ إِلاَّ لِأَجَلٍ مَعْدُودٍ (104) يَوْمَ يَأْتِ لا تَكَلَّمُ نَفْسٌ إِلاَّ بِإِذْنِهِ فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ (105) اعتقد بها ( ذلِكَ ) اليوم ( يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ ) يجمعون كلهم للحساب والجزاء ( وَذلِكَ يَوْمٌ مَشْهُودٌ ) ليشهده الخلائق كلهم من الجن والإنس ، وفي محضرهم يجري الحساب والجزاء.` },
            { text: "وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٍ مَّعْدُودٍ", tafsir: `ما نؤخر يوم القيامة ( إِلَّا لِأَجَلٍ مَعْدُودٍ ) أي أمد معدودة أيامه ، فإذا انتهى ذلك الأمد أظهرناه للوجود ، واللام في « لأجل » لام العلة ، أي لغرض تمام الأجل وانتهائه.` },
            { text: "يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِۦ فَمِنْهُمْ شَقِىٌّ وَسَعِيدٌ", tafsir: `حين يأتي يوم القيامة والجزاء ( لا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِ ) لا يتكلم أحد مع أحد إلا بإجازة الله سبحانه ، فقد شمل يوم القيامة صمت رهيب ، فإن الإنسان إذا خاف ووجل لم يتكلم حيث يسود الخوف والرهبة. ولعل في الإتيان بصيغة المجهول ـ بناء على ذلك ـ للإشارة إلى أن الناس هناك كالمساجين الذين لا يحق لأحد أن يكلمهم ، وفيه دلالة بليغة على الخوف السائد والرهبة المخيمة على الناس حتى أن سماع الكلام لا يجوز إلا بإذن خاص ، ولا يخفى أن هذا لا ينافي تكلم بعضهم مع بعض في مواقف مختلفة لأن ذلك بالإذن ، وهل الإذن كالإذن هناك ، أو المراد به الإذن التكويني برفع الأبهة ؟ احتمالان. ( فَمِنْهُمْ ) أي من الناس ( شَقِيٌ ) قد شقي بسبب الأعمال الفاسدة والعقائد الكاسدة ( وَ ) منهم ( سَعِيدٌ ) سعد وفاز بعقيدته الصحيحة فَأَمَّا الَّذِينَ شَقُوا فَفِي النَّارِ لَهُمْ فِيها زَفِيرٌ وَشَهِيقٌ (106) خالِدِينَ فِيها ما دامَتِ السَّماواتُ وَالْأَرْضُ إِلاَّ ما شاءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِما يُرِيدُ (107) وعمله الصالح.` },
            { text: "فَأَمَّا ٱلَّذِينَ شَقُوا۟ فَفِى ٱلنَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ", tafsir: `وهم الذين تركوا الفطرة الأصلية بسبب ووساوس الشياطين والنفس الأمارة ( فَفِي النَّارِ ) تلك محلّهم ومسكنهم ( لَهُمْ فِيها ) أي في النار ( زَفِيرٌ ) هو إخراج النفس ( وَشَهِيقٌ ) وهو إدخال النفس. قالوا : « الزفير » أول نهيق الحمار ، و « الشهيق » آخر نهيقه ، وهما من أصوات المكروبين المحزونين ، و « الزفير » من شديد الأنين وقبحه ، بمنزلة إبقاء صوت الحمار ، و « الشهيق » الأنين الشديد المرتفع جدا بمنزلة آخر صوت الحمار.` },
            { text: "خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِّمَا يُرِيدُ", tafsir: `أي دائمين أبدا في النار ( ما دامَتِ السَّماواتُ وَالْأَرْضُ ) أي ما بقيت جهة العلو وجهة السفل ، فإن اللفظين يطلقان على الجهتين ( إِلَّا ما شاءَ رَبُّكَ ) فإن بعض أهل النار يخرجون منها بإدراكهم الشفاعة أو استيفاء عقابهم لأنهم كانوا أهل معاصي ، أو كانوا كفارا عصاة ، لكن لم تتم الحجة عليهم بما يوجب الخلود ، وإنما كانت الحجة عليهم بقدر دخولهم النار كما لو خالفوا بعض الأوامر الثابتة عندهم أنها من قبله سبحانه ، بقتل نفس محترمة ، أو سلب مال أو ما أشبه. ولا يلازم خروجهم من النار دخولهم في الجنة ، إذ هناك أماكن أخرى معدة للناس كالأعراف. فلا يقال : كيف يدخل الكافر الجنة ؟ ( إِنَّ رَبَّكَ ) يا رسول الله ( فَعَّالٌ لِما يُرِيدُ ) لا يمنعه عن إرادته مانع ولا يقف دون مشيئته شيء. ولعلّ الإتيان بصيغة المبالغة « فعّال » وَأَمَّا الَّذِينَ سُعِدُوا فَفِي الْجَنَّةِ خالِدِينَ فِيها ما دامَتِ السَّماواتُ وَالْأَرْضُ إِلاَّ ما شاءَ رَبُّكَ عَطاءً غَيْرَ مَجْذُوذٍ (108) فَلا تَكُ فِي مِرْيَةٍ مِمَّا يَعْبُدُ هؤُلاءِ ما يَعْبُدُونَ إِلاَّ باعتبار العموم في ما يريد ، أي يفعل كل ما يريده ، فإذا أراد خلود الكفار خلدوا ، وإذا أراد نجاة بعض العاصين نجوا.` },
            { text: "وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ عَطَآءً غَيْرَ مَجْذُوذٍ", tafsir: `بالطاعة والعمل الصالح ( فَفِي الْجَنَّةِ ) لهم مستقر ومأوى ( خالِدِينَ فِيها ) أبد الآبدين لا يزولون عنها ولا تزول عنهم ( ما دامَتِ السَّماواتُ وَالْأَرْضُ ) أي ما بقيت جهتا العلو والسفل ، فإن العرب تقول لما أطلها : « سماء » ، ولما أقلها : « أرض » ( إِلَّا ما شاءَ رَبُّكَ ) هذا الاستثناء لإفادة أن الأمر لم يخرج عن إرادة الله سبحانه ، فليس الخلود جبرا عليهم فإذا شاء إخراجهم من الجنة أمكنه ذلك وإن لم يفعل ، أو الاستثناء باعتبار الأول يعني أن السعيد في الجنة إلا المقدار الذي هو في المحشر أو في النار ـ ابتداء ـ لما صدر منه من بعض الأعمال السيئة ، فليس في ذلك الوقت في الجنة لأن الله لم يشأ كونه فيها ، وإذ كان الكلام موهما لانقطاع الخلود جاء التأكد لذلك بقوله سبحانه : ( عَطاءً غَيْرَ مَجْذُوذٍ ) أي غير مقطوع ، و « عطاء » منصوب بما فهم من الجملة ، أي أعطاهم الجنة عطاء دائما. [110] إن الأقوام الذين كذبوا الرسل حق عليهم العقاب في الدنيا وحق عليهم العقاب في الآخرة ، كما استعرض كل من العقابين في قصصهم السابقة ، وإذ قد علمت يا رسول الله ذلك ( فَلا تَكُ فِي مِرْيَةٍ ) أي في شك ، فإن « المرية » بمعنى الشك ( مِمَّا يَعْبُدُ هؤُلاءِ ) الكفار ، من الأصنام المنحوتة ، فإن مصير الجميع إلى النار والهلاك ( ما يَعْبُدُونَ إِلَّا كَما يَعْبُدُ آباؤُهُمْ مِنْ قَبْلُ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنْقُوصٍ (109) وَلَقَدْ آتَيْنا مُوسَى الْكِتابَ فَاخْتُلِفَ فِيهِ وَلَوْ لا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ لَقُضِيَ بَيْنَهُمْ وَإِنَّهُمْ لَفِي شَكٍّ مِنْهُ مُرِيبٍ (110) كَما يَعْبُدُ آباؤُهُمْ مِنْ قَبْلُ ) فليس لهم حجة في عبادتهم إلا التقليد للآباء عن جهالة وضلالة ، فليست لهم حاجة في عبادتهم لدليل أو منطق. ومن المعلوم أن الرسول صلى‌الله‌عليه‌وآله‌وسلم لم يكن يشك في أمرهم ، وإنما جرى الكلام من باب « إياك أعني واسمعي يا جارة » ( وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ ) أي معطوهم جزاء أعمالهم وعقاب أفعالهم وافيا ( غَيْرَ مَنْقُوصٍ ) لا ينقص من عقابهم شيء.` },
            { text: "فَلَا تَكُ فِى مِرْيَةٍ مِّمَّا يَعْبُدُ هَٰٓؤُلَآءِ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ", tafsir: `` },
            { text: "وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ", tafsir: `شأن هؤلاء شأن من سبقهم من الأمم فلقد ( آتَيْنا مُوسَى الْكِتابَ ) أعطيناه التوراة ( فَاخْتُلِفَ فِيهِ ) أي في موسى ، هل هو نبي أم لا ؟ أو اختلف في الكتاب ، هل هو من عند الله أم لا ؟ وعلى كل حال ، فقد اختلفوا في الحق كما اختلف قومك يا رسول الله ( وَلَوْ لا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ ) حسب ما قدّر من المصالح ، بأن يكون لكل أمة أجل لا يتقدم ولا يتأخر ( لَقُضِيَ بَيْنَهُمْ ) لحكم سبحانه بين المؤمنين والكافرين بنجاة المؤمنين وإعطائهم الأجر ، وهلاك الكفار وخزيهم ، لكنه سبحانه حكم وقضى أن تكون الدنيا دار مهلة واختبار ، ولذا يترك كلّا وشأنه يعمل ما يشاء ( وَإِنَّهُمْ ) أي الكافرين ( لَفِي شَكٍ ) فإنهم ما كانوا يتيقنون بكذب دعوى الرسول صلى‌الله‌عليه‌وآله‌وسلم ، ( مِنْهُ ) أي من وعد الله ، أو من الرسول صلى‌الله‌عليه‌وآله‌وسلم ، أو من الكتاب ( مُرِيبٍ ) موجب للريب ، فان الإنسان قد لا يعتني فلا يكون الشك موجبا للريب وقد يعتني به حتى يوقعه في الريب حقيقة. وَإِنَّ كُلاًّ لَمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمالَهُمْ إِنَّهُ بِما يَعْمَلُونَ خَبِيرٌ (111) فَاسْتَقِمْ كَما أُمِرْتَ وَمَنْ تابَ مَعَكَ وَلا تَطْغَوْا إِنَّهُ بِما تَعْمَلُونَ بَصِيرٌ (112)` },
            { text: "وَإِنَّ كُلًّا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَٰلَهُمْ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرٌ", tafsir: `« إن » مخففة من الثقيلة ، أو نافية ، وعلى الأول أصل « لما » : « ل من ما » أي « لمن الذين » ، فأبدلت النون ميما واجتمعت ثلاث ميمات فحذفت إحداهن ، فيكون المعنى : وإن كل طائفة من الفريقين ـ المؤمنين والجاحدين ـ لمن الذين يعطيهم الله أجورهم. وعلى الثاني يكون « لمّا » بمعنى « إلا » أي : « ما كل طائفة إلا ليعطيهم الله أجورهم » ( لَمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمالَهُمْ ) أي يعطيهم ربك جزاء أعمالهم إن خيرا فخير وإن شرا فشر ( إِنَّهُ ) سبحانه ( بِما يَعْمَلُونَ خَبِيرٌ ) فلا يفوته شيء من أعمالهم ، بل يعلم كل عمل ويعطي جزاءه.` },
            { text: "فَٱسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا۟ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `يا رسول الله ( كَما أُمِرْتَ ) بالتبليغ والإنذار ، ولا يزحزحك إنكار المنكرين وجحود الجاحدين ( وَ ) ليستقم ( مَنْ تابَ ) ورجع إلى الله سبحانه بعد الكفر والعصيان ( مَعَكَ ) فإن الكافر والعاصي كأنهما ذاهبان عن الله سبحانه إلى غيره ، فإذا آمن الكافر ، واستغفر العاصي ، كانا تائبين راجعين إليه سبحانه. وتقدير « ليستقم » إنما هو بقرينة « استقم » نحو : « نحن بما عندنا وأنت بما عندك راض » أي : نحن بما عندنا راضون. ( وَلا تَطْغَوْا ) أي لا تجاوزوا أوامر الله سبحانه ، بالزيادة أو النقصان ، فإن « الطغيان » تجاوز الحد ، يقال : « طغى الماء » إذا تجاوز حده. والخطاب للناس ، المفهوم من قوله « من تاب » ( إِنَّهُ ) تعالى ( بِما تَعْمَلُونَ بَصِيرٌ ) فيبصر ويرى طغيان الطاغين واستقامة وَلا تَرْكَنُوا إِلَى الَّذِينَ ظَلَمُوا فَتَمَسَّكُمُ النَّارُ وَما لَكُمْ مِنْ دُونِ اللهِ مِنْ أَوْلِياءَ ثُمَّ لا تُنْصَرُونَ (113) المستقيمين ، فيجازي كلّ حسب عمله. في تفسير « الصافي » : قال ابن عباس : ما نزلت آية كان أشق على رسول الله صلى‌الله‌عليه‌وآله‌وسلم من هذه الآية ، ولهذا قال : « شيبتني هود والواقعة وأخواتها » (1) . وعن بعضهم قال : رأيت رسول الله صلى‌الله‌عليه‌وآله‌وسلم في النوم ، فقلت : روي عنك أنك قلت : « شيبتني هود » فقال صلى‌الله‌عليه‌وآله‌وسلم : « نعم » ، فقلت : ما الذي شيّبك منها ، أ قصص الأنبياء وهلاك الأمم ؟ قال : لا ، ولكن قوله تعالى : ( فَاسْتَقِمْ كَما أُمِرْتَ ) (2) . [114] وإذ أمر سبحانه المؤمنين بالاستقامة ، نهاهم عن الانحراف بالركون إلى الظالمين فإن كل انحراف عن الاستقامة ركون إلى الظالم الذي نهج ذلك المنهج المنحرف ( وَلا تَرْكَنُوا ) و « الركون » هو الاعتماد والميل والسكون إلى شخص أو جهة أو نحوها ( إِلَى الَّذِينَ ظَلَمُوا ) في عقيدة أو عمل أو غيرهما ( فَتَمَسَّكُمُ النَّارُ ) وتأخذكم. والتعبير ب « المس » لعله لإفادة أن مس النار يقتضي الحذر منه فكيف بما فوقه ( وَما لَكُمْ ) أيها المؤمنون ( مِنْ دُونِ اللهِ ) أي سوى الله سبحانه ( مِنْ أَوْلِياءَ ) ينصرونكم في الدنيا والآخرة ، فإن الله هو وليكم ( ثُمَ ) إن ركنتم إلى الظالمين ( لا تُنْصَرُونَ ) إذ الله سبحانه يقطع نصره عنكم ، والكافرون ـ ( 1) وسائل الشيعة : ج 6 ص 172. ( 2) شرح نهج البلاغة لابن أبي الحديد : ج 11 ص 213. وَأَقِمِ الصَّلاةَ طَرَفَيِ النَّهارِ وَزُلَفاً مِنَ اللَّيْلِ إِنَّ الْحَسَناتِ يُذْهِبْنَ السَّيِّئاتِ بما انطووا عليه من عدائكم ـ لا ينصرونكم ، وقد جرب المسلمون ذلك ، فإنهم من يوم ركنوا إلى الكافرين أخذ أمرهم في الانحطاط إلى هذا اليوم ، حتى يرجعوا عما اقترفوا ، فينصرهم الله سبحانه. [115] وبمناسبة لزوم الاستقامة يأتي السياق لبيان وجوب الصلاة ، فإنها أحسن وسيلة للاستقامة ، إذ هي تحتاج إلى يقظة دائمة في النفس وملكة راسخة تحفظ الإنسان طيلة العمر عن الانحراف ، وهذه اليقظة والملكة لا تكون إلا بالتذكير الدائم الحاصل من إقامة الصلاة صباحا وعصرا وليلا ( وَأَقِمِ الصَّلاةَ ) يا رسول الله ، أو كل من يأتي منه ذلك ( طَرَفَيِ النَّهارِ ) صباحا وعصرا ، فإن صلاة الصبح في الطرف الأول من النهار ، وصلاة الظهرين في الطرف الآخر منه ( وَزُلَفاً ) جمع « زلفة » وهي المنزلة ، مثل « غرف جمع غرفة » ، وهي أول ساعات الليل ، كأن كل ساعة منزلة من منازل الليل ( مِنَ اللَّيْلِ ) وهي صلاة المغرب والعشاء (1) . وهذا هو المفهوم من رواية النبي صلى‌الله‌عليه‌وآله‌وسلم أن : « طرفي النهار » الغداة ، ( وَزُلَفاً مِنَ اللَّيْلِ ) هي صلاة العشاء. أقول : فعلى هذا تكون الآية ساكتة عن الظهرين ، ولعلّ ذلك لصعوبة الثلاثة الأول دونهما. ( إِنَّ الْحَسَناتِ يُذْهِبْنَ السَّيِّئاتِ ) فإن الحسنة تكفّر السيئة ( 1) تفسير القمي : ج 1 ص 337. ذلِكَ ذِكْرى لِلذَّاكِرِينَ (114) وَاصْبِرْ فَإِنَّ اللهَ لا يُضِيعُ أَجْرَ الْمُحْسِنِينَ (115) وتمحقها ، ومن الحسنات « الصلوات الخمس » فإنها تمحق الذنوب وتمحيها. و قد روي ذلك عن النبي صلى‌الله‌عليه‌وآله‌وسلم ، كما روي عن الإمام المرتضى عليه‌السلام أنه قال : « إن الله يكفر بكل حسنة سيئة. ثم تلا هذه الآية » (1) . ( ذلِكَ ) الذي تقدم من قوله « استقم » ( ذِكْرى لِلذَّاكِرِينَ ) أي فيه تذكرة وموعظة لمن أراد التذكّر والتفكّر.` },
            { text: "وَلَا تَرْكَنُوٓا۟ إِلَى ٱلَّذِينَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ثُمَّ لَا تُنصَرُونَ", tafsir: `` },
            { text: "وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًا مِّنَ ٱلَّيْلِ إِنَّ ٱلْحَسَنَٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ", tafsir: `` },
            { text: "وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ", tafsir: `يا رسول الله على الاستقامة ، أو على الصلاة ، أو مطلقا ( فَإِنَّ اللهَ لا يُضِيعُ أَجْرَ الْمُحْسِنِينَ ) والصابر من أفضل أقسام المحسنين ، والصبر على ثلاثة أقسام : صبر على البلاء ، وصبر على الطاعة ، وصبر على الأحوال ، بأن لا يبطر الإنسان عند الرخاء ولا يجزع عند البلاء. [117] إن دعاة الإصلاح الذين يتمكنون من تغيير الواقع السيئ هم الذين يبقون على الأمم من الانهيار والدمار فإذا خلت أمة منهم انهارت واضمحلت ، كما أن المرضى يحتاجون إلى أطباء يتمكنون من علاجهم. أما إذا كان هناك مرضى بلا طبيب أو كان هناك طبيب لكن لم يتمكن من تنفيذ أوامره وعلاج مرضاه فإن عاقبتهم الموت والهلاك. وهكذا جرت سنة الله في الأمم سابقها ولا حقها فحيث إن الأمم السابقة لم ينفذ فيهم دعاة الإصلاح لقساوة قلوبهم عذّبوا. وهكذا يذكّر ( 1) بحار الأنوار : ج 29 ص 319. فَلَوْ لا كانَ مِنَ الْقُرُونِ مِنْ قَبْلِكُمْ أُولُوا بَقِيَّةٍ يَنْهَوْنَ عَنِ الْفَسادِ فِي الْأَرْضِ إِلاَّ قَلِيلاً مِمَّنْ أَنْجَيْنا مِنْهُمْ وَاتَّبَعَ الَّذِينَ ظَلَمُوا ما أُتْرِفُوا فِيهِ وَكانُوا مُجْرِمِينَ (116) وَما كانَ رَبُّكَ لِيُهْلِكَ الْقُرى الله سبحانه بهذه الحقيقة حتى يأخذ الناس حذرهم ، ويعلموا أنهم إن لم يصلحوا انهاروا واستحقوا العذاب. ( فَلَوْ لا ) أي فهلّا ، تقريح وذم ( كانَ مِنَ الْقُرُونِ ) جمع قرن وهو الجيل ، أي من الأجيال السابقة التي كانت ( مِنْ قَبْلِكُمْ ) أيها المسلمون ( أُولُوا بَقِيَّةٍ ) أصحاب بقايا فضل وعقل وتدبر ، فكأنهم كلهم كانوا أحداثا ، لا بقية عقل وحنكة وحكمة فيهم حتى يتدبروا ويتفكروا ويعتبروا بالماضين ( يَنْهَوْنَ عَنِ الْفَسادِ فِي الْأَرْضِ ) فإنه كان من اللازم أن يكون فيهم جمع هذه صفتهم حتى ينقذوا الأمم والقرون من الهلاك ( إِلَّا قَلِيلاً مِمَّنْ أَنْجَيْنا مِنْهُمْ ) من أنبيائهم وبعض المؤمنين بهم ، مما لم يكن يكفي لدفع العذاب عنهم ، فإن الطبيب ولو كان من أحذق الأطباء لكنه إذا لم يجد آذانا صاغية من المرضى والممرضين لم يكن لأمره نفع في إنقاذ المرضى ، إن القليل الذين كانوا ينهون قد أنجيناهم ، أما سائر الجيل فقد أهلكوا بفسادهم وعصيانهم ( وَاتَّبَعَ الَّذِينَ ظَلَمُوا ) وعصوا ( ما أُتْرِفُوا فِيهِ ) أي اتبعوا ترفهم وشهواتهم ، في مقابل المؤمنين الذين اتبعوا أوامر الله سبحانه ومناهج الأنبياء ( وَكانُوا مُجْرِمِينَ ) ذوي إجرام وعصيان ، ولذا أهلكوا بسبب أعمالهم الفاسدة.` },
            { text: "فَلَوْلَا كَانَ مِنَ ٱلْقُرُونِ مِن قَبْلِكُمْ أُو۟لُوا۟ بَقِيَّةٍ يَنْهَوْنَ عَنِ ٱلْفَسَادِ فِى ٱلْأَرْضِ إِلَّا قَلِيلًا مِّمَّنْ أَنجَيْنَا مِنْهُمْ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُوا۟ مَآ أُتْرِفُوا۟ فِيهِ وَكَانُوا۟ مُجْرِمِينَ", tafsir: `` },
            { text: "وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ", tafsir: `يا رسول الله ( لِيُهْلِكَ الْقُرى ) السابقة ، أي يهلك بِظُلْمٍ وَأَهْلُها مُصْلِحُونَ (117) وَلَوْ شاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً واحِدَةً وَلا يَزالُونَ مُخْتَلِفِينَ (118) إِلاَّ مَنْ رَحِ مَ رَبُّكَ وَلِذلِكَ خَلَقَهُمْ أهل القرى ( بِظُلْمٍ ) منه لهم ( وَ ) الحال أن ( أَهْلُها مُصْلِحُونَ ) يصلحون أنفسهم ومجتمعهم باجتناب المعاصي والنهي عن المنكر ، وإنما أهلكهم بالعدل حين كان أهلها مجرمين مفسدين. [119] إن الدنيا دار اختبار وامتحان ليجزي كل حسب عمله ولذا ترك الله سبحانه الأمم وما يختارون بعد أن بيّن لهم الرشد من الغي ( وَلَوْ شاءَ رَبُّكَ ) يا رسول الله ( لَجَعَلَ النَّاسَ أُمَّةً واحِدَةً ) بإلجاء الجميع إلى الإيمان والعمل الصالح ، لكنه لا يشاء ذلك لئلّا يبطل الثواب والعقاب ( وَ ) لكن ( لا يَزالُونَ ) الناس ( مُخْتَلِفِينَ ) بعضهم كافر وبعضهم مؤمن ، وبعضهم مطيع وبعضهم عاص ، وذلك بأن شاء الله اختيارهم وقدرتهم.` },
            { text: "وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةً وَٰحِدَةً وَلَا يَزَالُونَ مُخْتَلِفِينَ", tafsir: `` },
            { text: "إِلَّا مَن رَّحِمَ رَبُّكَ وَلِذَٰلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ", tafsir: `من المؤمنين فإنهم لا يختلفون ويجتمعون على الحق. والمراد ب « الرحمة » الألطاف الخفية ، بعد هداية الجميع إلى الطريق وإرشادهم ، فمن قبل وآمن لطف به اللطف الخفي الزائد ، ومن أعرض تركه وغيّه ، كما أن الأب إذا أعطى أولاده رؤوس الأموال ليتّجروا بها فأعرض بعض وأقبل بعض ، لطف بالمقبل كثيرا وأخذ بيده ، أما المعرض فهو يخذله ويتركه ليفعل ما يشاء ( وَلِذلِكَ ) أي للرحمة ( خَلَقَهُمْ ) فقد خلقهم الله سبحانه حتى يرحمهم ، لكن قسما منهم أبوا وتخلّفوا وعصوا ، كما أن من أسس مدرسة إنما يؤسسها لتعليم الناس وهدايتهم ، فإذا أعرض البعض كان وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ (119) وَكُلاًّ نَقُصُّ عَلَيْكَ مِنْ أَنْباءِ الرُّسُلِ ما نُثَبِّتُ بِهِ فُؤادَكَ وَجاءَكَ فِي هذِهِ الْحَقُّ وَمَوْعِظَةٌ وَذِكْرى لِلْمُؤْمِنِينَ (120) وَقُلْ لِلَّذِينَ لا يُؤْمِنُ ونَ اعْمَلُوا عَلى مَكانَتِكُمْ من عنده ، لا من عند من أسس المدرسة ( وَتَمَّتْ كَلِمَةُ رَبِّكَ ) أي انتهت فلا مبدل لها ، والكلمة هي : ( لَأَمْلَأَنَ ) من « ملأ » بمعنى : إدخال الشيء في الظرف حتى يمتلئ ( جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ ) بسبب كفرهم وعصيانهم ، وإنما ذكر هذا الطرف من الناس لأن الكلام حول العصاة والكفار ، والذين أهلكوا بسبب مخالفتهم للأنبياء.` },
            { text: "وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ وَجَآءَكَ فِى هَٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌ وَذِكْرَىٰ لِلْمُؤْمِنِينَ", tafsir: `أي كلّا من هذه القصص المتقدمة ( نَقُصُّ عَلَيْكَ ) ونخبرك ( مِنْ أَنْباءِ الرُّسُلِ ) أخبارهم ، كيف بلغوا ، وكيف وقف قومهم ضدهم وآذوهم ؟ ( ما نُثَبِّتُ بِهِ فُؤادَكَ ) أي نقوّي به قلبك ، حتى إذا رأيت إعراضا وأذى من قومك ، لم يسبب ذلك يأسك عن البلاغ. وليس معنى ذلك أنه لم يكن للنبي صلى‌الله‌عليه‌وآله‌وسلم ثبات ، وإنما استمرار الثبات هو بيد الله سبحانه ( وَجاءَكَ ) يا رسول الله ( فِي هذِهِ ) القصص السالفة ( الْحَقُ ) فكل ما حكي كان حقا مطابقا للواقع ( وَ ) جاءتك في هذه ( مَوْعِظَةٌ ) تعظ بها الجاهلين وتبعد بها الناس عن المعاصي ( وَذِكْرى لِلْمُؤْمِنِينَ ) تذكّرهم بالله وبآياته وبالآخرة.` },
            { text: "وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنَّا عَٰمِلُونَ", tafsir: `يا رسول الله ( لِلَّذِينَ لا يُؤْمِنُونَ ) من الكافرين ( اعْمَلُوا عَلى مَكانَتِكُمْ ) أي على حالتكم التي أنتم عليها ، وهذا تهديد لهم ، إِنَّا عامِلُونَ (121) وَانْتَظِرُوا إِنَّا مُنْتَظِرُونَ (122) وَلِلَّهِ غَيْبُ السَّماواتِ وَالْأَرْضِ وَإِلَيْهِ يُرْجَعُ الْأَمْرُ كُلُّهُ فَاعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ وَما رَبُّكَ بِغافِلٍ عَمَّا تَعْمَلُونَ (123) كقوله : ( اعْمَلُوا ما شِئْتُمْ ) (1) ، ( إِنَّا عامِلُونَ ) على منهجنا ، حتى نرى ما يصنع الله بكم وبنا.` },
            { text: "وَٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ", tafsir: `أي توقعوا عقاب الله وعذابه ( إِنَّا مُنْتَظِرُونَ ) فضله ورضوانه ، أو المعنى : نحن وأنتم ننتظر نتائج الأعمال ، وهل نحن كنا على باطل أم أنتم ؟. [124] إن ما يأتي غيب وسينكشف الغيب ويظهر المجهول ( وَلِلَّهِ غَيْبُ السَّماواتِ وَالْأَرْضِ ) فكلّ ما غاب عن الحواس ، أو غاب عن الوجود ـ بأن لم يوجد بعد ـ سواء كان في السماوات أو في الأرض ، إنه لله وحده فهو العالم به وهو القادر على إيجاده أو إظهاره ( وَإِلَيْهِ ) أي إلى الله تعالى ( يُرْجَعُ الْأَمْرُ كُلُّهُ ) فكل الأمور مرجعها إليه في الدنيا وفي الآخرة ، فهو الفاصل في القضايا التكوينية والتشريعية ، حتى أنه إذا لم يشأ شيئا لم ينفع فيه إرادة الجن والإنس ( فَاعْبُدْهُ ) يا رسول الله ( وَتَوَكَّلْ عَلَيْهِ ) اجعله وكيلا عنك وناصرا لك ، فإن من يعلم الغيوب ، ويكون مصير الأمور إليه ، أحق بالعبادة والتوكل عليه ، من سائر الأشياء ( وَما رَبُّكَ ) يا رسول الله ( بِغافِلٍ ) أو جاهل ( عَمَّا تَعْمَلُونَ ) من الخير والشر ، فمن أحسن فلنفسه ، ومن أساء فعليها. ( 1) فصلت : 41. (12)` },
            { text: "وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَيْهِ يُرْجَعُ ٱلْأَمْرُ كُلُّهُۥ فَٱعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ", tafsir: `` }
        ]
    },
    12: { // سورة يوسف
        name: "يوسف",
        basmalaTafsir: ``,
        verses: [
            { text: "الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ", tafsir: `من جنس « ألف » و « لام » و « راء » أنشئ القرآن الحكيم ، أو هي رموز بين الله والرسول كالرموز التي بين رؤساء الحكومات وسفرائها ، أو غير ذلك ( تِلْكَ آياتُ الْكِتابِ الْمُبِينِ ) فإن هذه الأحرف وما من جنسها هي بعينها تلك الآيات البعيدة التي فوق الطاقة البشرية لا يتمكن الإنسان من الإتيان بمثلها لا لفظا ولا منهجا ، والكتاب مبيّن واضح لا لبس فيه ولا غموض ولا التواء. [3] ولقد شاء الله سبحانه أن ينزل هذا الكتاب بلغة العرب ( إِنَّا أَنْزَلْناهُ ) أنزلنا هذا الكتاب ( قُرْآناً عَرَبِيًّا ) ولماذا ؟ ( لَعَلَّكُمْ تَعْقِلُونَ ) وتفهمون ، إذ هو بلغتكم ، أو الخطاب في « لعلكم » عام يشمل جميع البشر ، إذ كون القرآن من مصدر عربي أقوى في الدلالة على كونه من قبل الله سبحانه فإن الحضارة ـ عهد نزول القرآن ـ لم تكن إلا لفارس والروم ، أما عرب الجزيرة فلم يكونوا أهل تحضّر وعلم من قراءة وكتابة ، فإذا جاء بالقرآن رجل عربي يعيش بين أظهرهم ، كان أدل على أنه من قبل الله سبحانه ، مما لو كان منزلا على رجل رومي أو فارسي وسط الحضارة. وقد ذكر المفسرون : أن نزول القرآن على رسول من الجزيرة يشتمل على أنواع من الفضل لم تكن توجد لو أنزل على طرفي العالم المتحضر يوم ذاك ، فإن الجزيرة تعد وسط العالم تقريبا ، وأنها كانت أحوج إلى الرشاد ، وأن أهلها كانوا أقدر على حمل الرسالة ، لبداوتهم وعدم تلوثهم بمفاسد الحضارة ، وغير ذلك مما بيّنوه في المفصلات. نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ بِما أَوْحَيْنا إِلَيْكَ هذَا الْقُرْآنَ وَإِنْ كُنْتَ مِنْ قَبْلِهِ لَمِنَ الْغافِلِينَ (3) إِذْ قالَ يُوسُفُ لِأَبِيهِ يا أَبَتِ إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَباً وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي ساجِدِينَ (4)` },
            { text: "إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ", tafsir: `` },
            { text: "نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَٰفِلِينَ", tafsir: `وبالأخص قصة يوسف ، فإنها قصة واقعية فيها أنواع من التذكرة والعظة ، مشوقة حيث اشتملت على موضوع مثير ( بِما أَوْحَيْنا إِلَيْكَ هذَا الْقُرْآنَ ) أي بسبب إيحائنا هذا القرآن قصصنا عليك هذه القصص فلو لا إيحاؤه لم تكن قصة ( وَإِنْ كُنْتَ ) يا رسول الله ( مِنْ قَبْلِهِ ) قبل إيحاء القرآن إليك ( لَمِنَ الْغافِلِينَ ) الذين لا يعرفون شيئا من ذلك. وهذا لا ينافي الحديث المروي : « كنت نبيا وآدم بين الماء والطين » (1) إذ لا ملازمة بين النبوة وبين علم كل شيء ، فلقد كان نبيا لكنه لم يكن يعلم بعض الأشياء ، أو كان وحي القرآن قبل ذلك لأنه إنما أوحي إلى النبي القرآن بعد البعثة في الظاهر ، وأما في الحقيقة فقد كان صلى‌الله‌عليه‌وآله‌وسلم يعلم القرآن قبل وحيه إليه. ؟ وقد ورد أن الإمام المرتضى عليه‌السلام قرأ القرآن وهو طفل رضيع. [5] فاذكر يا رسول الله ( إِذْ قالَ يُوسُفُ لِأَبِيهِ ) يعقوب بن إسحاق بن إبراهيم الخليل عليه‌السلام : ( يا أَبَتِ إِنِّي رَأَيْتُ ) في المنام ( أَحَدَ عَشَرَ كَوْكَباً وَالشَّمْسَ وَالْقَمَرَ رَأَيْتُهُمْ لِي ساجِدِينَ ) إنما أتى بالجمع العاقل لأن السجود من صفات العقلاء. روي عن الباقر عليه‌السلام في تأويل هذه ( 1) بحار الأنوار : ج 16 ص 402. قالَ يا بُنَيَّ لا تَقْصُصْ رُؤْياكَ عَلى إِخْوَتِكَ فَيَكِيدُوا لَكَ كَيْداً إِنَّ الشَّيْطانَ لِلْإِنْسانِ عَدُوٌّ مُبِينٌ (5) وَكَذلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحادِيث ِ وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ الرؤيا : أنه سيملك مصر ويدخل عليه أبواه وأخوته ، أما الشمس فأم يوسف راحيل ، والقمر يعقوب ، وأما الأحد عشر كوكبا فإخوته. فلما دخلوا عليه سجدوا شكرا لله وحده حين نظروا إليه. وكان ذلك السجود لله تعالى (1) .` },
            { text: "إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَٰجِدِينَ", tafsir: `` },
            { text: "قَالَ يَٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا إِنَّ ٱلشَّيْطَٰنَ لِلْإِنسَٰنِ عَدُوٌّ مُّبِينٌ", tafsir: `يعقوب : ( يا بُنَيَ ) تصغير « ابن » ، ولعلّ وجه التصغير الشفقة ( لا تَقْصُصْ رُؤْياكَ عَلى إِخْوَتِكَ ) أي لا تخبرهم بما رأيت في المنام ( فَيَكِيدُوا لَكَ كَيْداً ) أي فيحسدوك ، حيث تدل رؤياك على مقام رفيع ، ويحتالوا لإهلاكك حيلة ( إِنَّ الشَّيْطانَ لِلْإِنْسانِ عَدُوٌّ مُبِينٌ ) ظاهر العداوة ، فإنه يريد الإيقاع بين الأخوة بإشعال نار الحسد في قلوب بعضهم على بعض.` },
            { text: "وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَٰقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ", tafsir: `أي كما أراك هذه الرؤيا تكرمة لك ، مما كان تعبيره خضوع الأخوة والأبوين لمقامك ( يَجْتَبِيكَ ) من « الاجتباء » أي الاختيار وهو الاصطفاء ، أي يختارك ( رَبُّكَ ) يا يوسف للنبوة ( وَيُعَلِّمُكَ مِنْ تَأْوِيلِ الْأَحادِيثِ ) « الأحاديث » هي الرؤيا ، لأنها من أحاديث الملك وإخباره للإنسان في منامه إن كانت الرؤيا صادقة ، ومن أحاديث الشيطان والنفس إن كانت كاذبة ، و « تأويلها » تعبيرها ، سمي « تأويلا » لأن الرؤيا تأوّل إلى ذلك المعنى المتضمنة له ( وَيُتِمُّ نِعْمَتَهُ عَلَيْكَ ) بإعطائك ( 1) بحار الأنوار : ج 12 ص 217. وَعَلى آلِ يَعْقُوبَ كَما أَتَمَّها عَلى أَبَوَيْكَ مِنْ قَبْلُ إِبْراهِيمَ وَإِسْحاقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ (6) لَقَدْ كانَ فِي يُوسُفَ وَإِخْوَتِهِ آياتٌ لِلسَّائِلِينَ (7) إِذْ قالُوا لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلى أَبِينا مِنَّا رغباتك في الدنيا والآخرة ( وَعَلى آلِ يَعْقُوبَ ) إخوتك وأولادكم بجعلهم أنبياء وملوكا وسادة للناس ( كَما أَتَمَّها ) أي أتم الله سبحانه نعمته ( عَلى أَبَوَيْكَ ) أبيك وجدك ( مِنْ قَبْلُ إِبْراهِيمَ وَإِسْحاقَ ) حيث جعلهما نبيين وأعطاهما نعم الدنيا ( إِنَّ رَبَّكَ ) يا يوسف ( عَلِيمٌ ) بمن يصلح للرسالة والسيادة والملك ( حَكِيمٌ ) يفعل الأشياء حسب الصلاح والحكمة. [8] ثم شرع سبحانه في قصة يوسف بقوله : ( لَقَدْ كانَ فِي ) قصة ( يُوسُفَ وَإِخْوَتِهِ ) الأحد عشر ( آياتٌ ) أدلة وعلامات على قدرة الله سبحانه ، وإرشادات لمن أراد الاسترشاد ( لِلسَّائِلِينَ ) أي لمن يسأل عن الآيات ويهتم بالأمور ويفتش عن الحقائق. ؟ عن الجوامع : روي أن اليهود قالوا لكبراء المشركين : سلوا محمدا لم انتقل آل يعقوب من الشام إلى مصر وعن قصة يوسف ؟ قال : فأخبرهم صلى‌الله‌عليه‌وآله‌وسلم بالقصة.` },
            { text: "لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَٰتٌ لِّلسَّآئِلِينَ", tafsir: `` },
            { text: "إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَٰلٍ مُّبِينٍ", tafsir: `أي اذكر إذ قالوا ، أو لقد كان آيات إذ قالوا ، أي : قال بعض الأخوة لبعض ، وقد كان عشرة منهم من غير أم ، ويوسف وابن يامين من أم ـ كما في بعض التفاسير والتواريخ ـ ( لَيُوسُفُ وَأَخُوهُ ) أي ابن يامين ( أَحَبُّ إِلى أَبِينا ) يعقوب عليه‌السلام ( مِنَّا ) فقد كان يعقوب شديد وَنَحْنُ عُصْبَةٌ إِنَّ أَبانا لَفِي ضَلالٍ مُبِينٍ (8) اقْتُلُوا يُوسُفَ أَوِ اطْرَحُوهُ أَرْضاً يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا مِنْ بَعْدِهِ قَوْماً صالِحِينَ (9) الحب ليوسف وبعده لابن يامين ، وكان يوسف من أحسن الناس وجها وأحسنهم أخلاقا. فقد حكي أن رجلا سأل يعقوب : لم تفضل يوسف على باقي الأخوة ؟ قال : أعلمك بالأمر ، فطلب أحد الأخوة وسأله عما لو أساء شخص إليه ماذا يصنع ؟ قال الولد : أنتقم منه .. ثم طلب يوسف وسأله عن مثل ذلك السؤال ، فقال يوسف : أعفو عنه ، قال : فإن أساء إليك ثانية ؟ قال يوسف : أعفو ، قال : فإن أساء إليك ثالثة ؟ قال : أعفو. ( وَ ) الحال أنّا ( نَحْنُ عُصْبَةٌ ) جماعة يتعصّب بعضنا لبعض ، ويعين بعضنا بعضا ، فكيف أن أبانا يقدّم يوسف وبنيامين علينا ونحن أنفع له منهما ؟ ( إِنَّ أَبانا لَفِي ضَلالٍ ) انحراف عن طريق الصواب ( مُبِينٍ ) واضح لا شك فيه ، فكيف يقدم أصغر الأولاد على سائر الأولاد ؟ [10] أخذ الأخوة ـ وبالطبع لم يكن فيهم ابن يامين ـ يتآمرون على يوسف ليطفئوا حسدهم قائلين : ( اقْتُلُوا يُوسُفَ ) قتلا ( أَوِ اطْرَحُوهُ أَرْضاً ) مجهولة بعيدة ، حتى لا يكون إلى جنبنا ، ولعلّ السباع تأكله ، أو يؤول أمره إلى الموت ( يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ ) تخلص لكم محبة الأب ، وتملكون قلبه ، فلا يصرف اهتمامه وحبه نحو يوسف فقط ( وَتَكُونُوا مِنْ بَعْدِهِ ) أي بعد هذا العمل من قتل يوسف أو طرحه في أرض مجهولة ( قَوْماً صالِحِينَ ) تستغفرون الله سبحانه. وهذا من عادة الذي قالَ قائِلٌ مِنْهُمْ لا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيابَتِ الْجُبِّ يَلْتَقِطْهُ بَعْضُ السَّيَّارَةِ إِنْ كُنْتُمْ فاعِلِينَ (10) قالُوا يا أَبانا ما لَكَ لا تَأْمَنَّا عَلى يُوسُفَ وَإِنَّا لَهُ لَناصِحُونَ (11) يريد أن يسيء وفيه بقية من إيمان ، فإنه بين عزمه على ارتكاب الجريمة بما توسوس إليه نفسه ، وبين نيته في أنه سيصبح صالحا مستغفرا بعد ارتكابها. ويحتمل أن يراد « صالحين في أمر دنياكم لا يزاحمكم فيها يوسف » .` },
            { text: "ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًا صَٰلِحِينَ", tafsir: `` },
            { text: "قَالَ قَآئِلٌ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَٰعِلِينَ", tafsir: `في بعض الأحاديث أن اسمه « لاوي » وهو جد موسى عليه‌السلام : ( لا تَقْتُلُوا يُوسُفَ وَأَلْقُوهُ فِي غَيابَتِ الْجُبِ ) « الجب » هو البئر و « غيابته » قعره ، حتى لا يموت ولا يشرف على الموت حيث ( يَلْتَقِطْهُ ) أي يأخذه من هناك ( بَعْضُ السَّيَّارَةِ ) « السيارة » هي الجماعة المسافرون ، سموا بذلك لأنهم يسيرون في البلاد. فإنهم إذا عطشوا وأرادوا الماء أدلوا دلوهم فيها ، فيتعلق به يوسف فيخرجوه ، ويذهبوا به إلى دورهم ومحلهم ، فقد تخلصنا من يوسف ، ولم نرتكب جريمة قتله ( إِنْ كُنْتُمْ فاعِلِينَ ) أي تريدون في الحقيقة التخلص من يوسف ، فليكن هذا عملكم ونوع تخلصكم. [12] ولما أحكموا المؤامرة وأجمعوا على التخلص من يوسف الغلام البريء الجميل حسدا وعداء ، جاءوا إلى أبيهم يعقوب ف ( قالُوا يا أَبانا ما لَكَ لا تَأْمَنَّا عَلى يُوسُفَ ) لأي شيء لا تثق بنا في أمر يوسف ؟ ألسنا نحن أمناء عندك ؟ ويظهر من الكلام أن يعقوب كان سيئ الظن بهم في أمر ابنه يوسف عليه‌السلام ( وَ ) الحال ( إِنَّا لَهُ ) أي ليوسف ( لَناصِحُونَ ) ننصح لأجله ونريد الخير به. أَرْسِلْهُ مَعَنا غَداً يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُ لَحافِظُونَ (12) قالَ إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخافُ أَنْ يَأْكُلَهُ الذِّئْبُ وَأَنْتُمْ عَنْهُ غافِلُونَ (13) قالُوا لَئِنْ أَكَلَهُ الذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّا إِذاً لَخاسِرُونَ (14)` },
            { text: "قَالُوا۟ يَٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ", tafsir: `` },
            { text: "أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ", tafsir: `يا أبانا ( مَعَنا ) إلى الصحراء ( غَداً يَرْتَعْ وَيَلْعَبْ ) « جزم الفعلين » على جواب الأمر ، والمعنى : إن ترسله معنا ، يرتع ويلعب ، و « الرتع » هو التوسع في أكل الفواكه وغيرها ، من « الرتعة » وهي الخصب ، أو التردد ذهابا ومجيئا ( وَإِنَّا لَهُ ) ليوسف ( لَحافِظُونَ ) نحفظه عن أن يصيبه الأذى.` },
            { text: "قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَٰفِلُونَ", tafsir: `يعقوب عليه‌السلام في جواب الأولاد : ( إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ ) فذهابكم به موجب لغمي وحزني حيث لا أقدر على فراقه ( وَأَخافُ ) عليه إن ذهبتم به ( أَنْ يَأْكُلَهُ الذِّئْبُ ) حيث كانت الأرض مذئبة ( وَ ) الحال ( أَنْتُمْ عَنْهُ غافِلُونَ ) مشغولون بأنفسكم. قيل : إن يعقوب رأى في منامه كأن يوسف قد شد عليه عشرة ذئاب يقتلوه ، وإذا ذئب منها يحمي عنه فكأن الأرض انشقت فدخل فيها يوسف فلم يخرج منها إلا بعد ثلاثة أيام ، ولذا قال لهم : أخاف أن يأكله الذئب.` },
            { text: "قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًا لَّخَٰسِرُونَ", tafsir: `قال الأولاد في جواب يعقوب : ( لَئِنْ أَكَلَهُ الذِّئْبُ وَ ) الحال ( نَحْنُ عُصْبَةٌ ) يتعصّب بعضنا لبعض ، ولنا من القوة والطاقة قدر كاف ( إِنَّا إِذاً لَخاسِرُونَ ) نكون كالذين تذهب عنهم رؤوس أموالهم ، أو نكون إذن عاجزون هالكون ، وهذا كالتعليق على ما لا يكون ، للتأكيد فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيابَتِ الْجُبِّ وَأَوْحَيْنا إِلَيْهِ لَتُنَبِّئَنَّهُمْ بِأَمْرِهِمْ هذا وَهُمْ لا يَشْعُرُونَ (15) وَجاؤُ أَباهُمْ عِشاءً يَبْكُونَ (16) على المقصود. [16] ثم إن يعقوب سلم للأمر وأرسل يوسف معهم ( فَلَمَّا ذَهَبُوا بِهِ ) بيوسف ( وَأَجْمَعُوا ) أي عزموا جميعا ، يقال : « أجمع » إذا عزم ( أَنْ يَجْعَلُوهُ فِي غَيابَتِ الْجُبِ ) في قعره ، وجواب « لما » محذوف تقديره « فعلوه » ( وَأَوْحَيْنا إِلَيْهِ ) إلى يوسف وهو في الجب ( لَتُنَبِّئَنَّهُمْ ) أي تخبرن إخوتك ( بِأَمْرِهِمْ هذا ) بعد ما تنجو من البئر وتصبح ملكا ، ويأتوك إخوتك لأجل الطعام ، تحكي لهم القصة ( وَهُمْ لا يَشْعُرُونَ ) في ذلك الوقت أنك يوسف. وقد ذكر سبحانه في آخر السورة قول يوسف لأخوته ـ وهم جاهلون بأنه يوسف ـ ( ( هَلْ عَلِمْتُمْ ما فَعَلْتُمْ بِيُوسُفَ وَأَخِيهِ ) (1) ؟. [17] ولما طرحوا يوسف في البئر ، تأخروا في الرجوع إلى المدينة حتى يأتي الليل فلا يظهر على وجوههم آثار الكذب ( وَجاؤُ أَباهُمْ ) أي رجعوا إلى أبيهم يعقوب ( عِشاءً ) أي وقت العشاء ، وذلك بعد ساعة من الغروب تقريبا ( يَبْكُونَ ) وإنما أظهروا البكاء ليوهموا أنهم صادقون في قولهم ، فإن البكاء لا يكون إلا عن حرقة القلب التي تلازم الصدق غالبا ، لكن البكاء قد يكون اصطناعا ، وإن جرت الدمعة. وكان بكاء الأخوة هكذا. ( 1) يوسف : 90. قالُوا يا أَبانا إِنَّا ذَهَبْنا نَسْتَبِقُ وَتَرَكْنا يُوسُفَ عِنْدَ مَتاعِنا فَأَكَلَهُ الذِّئْبُ وَما أَنْتَ بِمُؤْمِنٍ لَنا وَلَوْ كُنَّا صادِقِينَ (17) وَجاؤُ عَلى قَمِيصِهِ بِدَمٍ كَذِبٍ [18] ولما رأى يعقوب بكاءهم ، فزع وقال : ما لكم ؟ ( قالُوا يا أَبانا إِنَّا ذَهَبْنا نَسْتَبِقُ ) أي نتسابق في العدو لننظر أينا أقدر على العدو والركض ، وأينا يسبق أصحابه ، من « استبق » بمعنى تسابق ( وَتَرَكْنا يُوسُفَ عِنْدَ مَتاعِنا ) أي رحلنا وبضاعتنا ، لأنه صغير لا يقدر على العدو ، وليحفظ رحلنا ( فَأَكَلَهُ الذِّئْبُ ) وافترسه ( وَما أَنْتَ ) يا أبانا ( بِمُؤْمِنٍ ) أي بمصدّق ( لَنا ) لكلامنا ( وَلَوْ كُنَّا صادِقِينَ ) ومن عادة الكاذب أن يبرّر كذبه بمثل هذه التأكيدات ، كما قال الشاعر : « كاد المريب أن يقول خذوني » .` },
            { text: "فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ", tafsir: `` },
            { text: "وَجَآءُوٓ أَبَاهُمْ عِشَآءً يَبْكُونَ", tafsir: `` },
            { text: "قَالُوا۟ يَٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ وَمَآ أَنتَ بِمُؤْمِنٍ لَّنَا وَلَوْ كُنَّا صَٰدِقِينَ", tafsir: `` },
            { text: "وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ", tafsir: `جاء الأخوة ( عَلى قَمِيصِهِ بِدَمٍ كَذِبٍ ) جاءوا أباهم ومعهم قميص يوسف ملطخا بدم مكذوب ، فقد ذبحوا جديا ولطخوا قميص يوسف بدمه ، حيث أنهم لما ألقوه في البئر جرّدوه من ثوبه وألقوه في البئر عاريا. وإنما جاء ب « على » لأن المعنى : « جاءوا على القميص بالدم » ، أي صبّوا عليه الدم ، هذا بناء على أن « جاء » يراد به المجيء على القميص ، لا المجيء نحو الأب ، وإنما يستفاد الثاني من السياق ، وأما لو أريد من « جاءوا » المجيء نحو الأب كان اللازم تقدير ، حال مثل « صابّين » ونحوه. « وكذب » مصدر أقيم مقام الوصف ، أي « مكذوب فيه » ، وإنما جاء بالمصدر للمبالغة ، كقولك : « زيد عدل » . ولما نظر يعقوب إلى القميص عرف أنهم كاذبون في قولهم وأنهم قالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْراً فَصَبْرٌ جَمِيلٌ وَاللهُ الْمُسْتَعانُ عَلى ما تَصِفُونَ (18) إنما دبروا له مكيدة ، ولذا توجه إليهم و ( قالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْراً ) أي زيّنت لكم أنفسكم الحاسدة ليوسف مكيدة دبرتموها. و قد روي : أنه عليه‌السلام لما رأى القميص وليس به آثار الشق ، علم أن الذئب لم يأكله فإن الذئب إذا أكل إنسانا مزّق ثيابه. قال الصادق عليه‌السلام : لما أتي بقميص يوسف إلى يعقوب قال : « اللهم لقد كان ذئبا رفيقا حين لم يشق القميص » (1) . فأمري في هذا الفراق ( فَصَبْرٌ جَمِيلٌ ) روي عن النبي صلى‌الله‌عليه‌وآله‌وسلم والإمامين الباقر والصادق عليهما‌السلام : « إن الصبر الجميل هو الذي لا شكوى فيه إلى الخلق » (2) ( وَاللهُ الْمُسْتَعانُ ) به ، من « استعان » بمعنى : طلب العون ( عَلى ما تَصِفُونَ ) أي على دفع ما تصفونه من هلاك يوسف. وقد يقال : أنه كيف يوصف الصبر بالجميل ، مع أنه عليه‌السلام بكى حتى ابيضت عيناه ؟ بل كيف يمكن للنبي أن يكون له مثل هذه العلاقة بالأولاد مع أنه يرى عظمة الله وثوابه ؟ وقد يقال مثل ذلك في بكاء آدم عليه‌السلام والصديقة الطاهرة عليها‌السلام والإمام السجاد ؟ والجواب : إن هذا النحو من البكاء والتوجّع كان له نوعا من التبليغ والإرشاد لم يكن يؤدى إلا بذلك ، فقد كان بكاء آدم عليه‌السلام ( 1) بحار الأنوار : ج 12 ص 299. ( 2) الكافي : ج 2 ص 93. وَجاءَتْ سَيَّارَةٌ فَأَرْسَلُوا وارِدَهُمْ فَأَدْلى دَلْوَهُ إرشادا إلى وقع الخطيئة ـ ولو كانت ترك الأولى ـ وبيانا لما للجنة ورضا الله سبحانه من أهمية كبري حتى أن فراقها والدخول فيما لا يرضيه سبحانه ـ ولو لم يكن عصيانا ـ يوجبان هذا النوع من البكاء. وفي قصة آدم ، ما أجدر البكاء ولو ألف سنة لسخط الله العظيم الذي له كل شيء وبيده كل شيء .. وبكاء يعقوب كان تنفيرا لمثل هذا الاجرام الجماعي وإرشادا عمليا لما للحسد من الوقع السيئ على الحاسد والمحسود والمجتمع ، وإن مثل هذا التنفير العملي من أقوى أقسام الإرشاد والهداية .. وكذلك بكاء الصديقة الطاهرة والسجاد عليهما‌السلام كان تنفيرا عمليا لأعمال الغاصبين والسفاكين ، وإرشادا إلى عظمة المعزّى له ، الموجب لالتفات الناس حولهم فيستضيئون بأنوارهم ويهتدون بآثارهم. [20] رجع الأولاد إلى أبيهم وتمت القصة هنا ، لتبتدئ بحال يوسف في الجب ، فقد ذكر المفسرون أن البئر كانت ذات ماء ولما طرحوا يوسف فيها أوى إلى صخرة كانت في ثناياها. و قد روي أن جبرائيل عليه‌السلام هو الذي أخذه ، وشاء الله سبحانه أن يطعمه في البئر ، وهناك بقي ثلاثة أيام ( وَجاءَتْ سَيَّارَةٌ ) أي قافلة تسير كثيرا ، فإن « سيارة » صيغة مبالغة ، والقافلة تسمى بهذا الاسم لسيرها كثيرا في الأرض ( فَأَرْسَلُوا ) أي أهل السيارة ( وارِدَهُمْ ) الذي يرد الماء ليستقي منه للقافلة ، حتى يأتي إليهم من تلك البئر ـ التي فيها يوسف ـ بالماء ( فَأَدْلى ) الوارد ( دَلْوَهُ ) أي فأرسل دلوه في البئر ليأخذ الماء ، فتعلق يوسف بالدلو. و روي أن جبرائيل عليه‌السلام هو الذي جعل يوسف في الدلو ، بدل الماء ، ولما أن أخرج الوارد الدلو ، رأى غلاما جميلا فيه ، عوض الماء ، فدهش من قالَ يا بُشْرى هذا غُلامٌ وَأَسَرُّوهُ بِضاعَةً وَاللهُ عَلِيمٌ بِما يَعْمَلُونَ (19) وَشَرَوْهُ بِثَمَنٍ بَخْسٍ دَراهِمَ مَعْدُودَةٍ وَكانُوا فِيهِ مِنَ الزَّاهِدِينَ (20) هذه الصدفة العجيبة و ( قالَ ) لأصحابه : ( يا بُشْرى ) يا قوم ! البشارة ( هذا غُلامٌ وَأَسَرُّوهُ بِضاعَةً ) إن القوم لما رأوا يوسف نووا في أنفسهم أن يجعلوه بضاعة يبيعونه في البلد بعنوان أنه عبد (1) . و ورد أن الأخوة جاءوا إلى البئر ليروا ماذا صنع بيوسف هل خرج أو هلك ؟ وإذا بهم يتلاقون مع السيارة ، فقالوا لهم أنه عبد لنا أبق من المدينة ، ثم باعوه للسيارة ليستريحوا منه ( وَاللهُ عَلِيمٌ بِما يَعْمَلُونَ ) أي تعمل السيارة من نيتها جعل يوسف بضاعة. وقيل : في المعنى أمور أخرى ، وما ذكرناه الأظهر منها.` },
            { text: "وَجَآءَتْ سَيَّارَةٌ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ قَالَ يَٰبُشْرَىٰ هَٰذَا غُلَٰمٌ وَأَسَرُّوهُ بِضَٰعَةً وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ", tafsir: `` },
            { text: "وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍ دَرَٰهِمَ مَعْدُودَةٍ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ", tafsir: `أي باع الأخوة يوسف للسيارة ( بِثَمَنٍ بَخْسٍ ) ثمن ناقص مبخوس فيه عشرين درهما ـ كما في جملة من الأحاديث ـ ( دَراهِمَ مَعْدُودَةٍ ) أي قليلة ، وجيء بهذا الوصف لدلالته على القلة ، فإن القلة تعدّ ، أما الكثرة فلا تعد بسهولة ( وَكانُوا ) كان الأخوة ( فِيهِ ) أي في الثمن ، أو في يوسف ( مِنَ الزَّاهِدِينَ ) يقال : « زهد فيه » بمعنى لم يرغب ، فإن الأخوة ما باعوه لقصد الربح حتى يرغبوا في الثمن ، وإنما باعوه للتخلّص منه. [22] وجاءت السيارة بيوسف إلى مصر ، وهل هناك بيع آخر ، أو كان عزيز مصر هو الذي اشتراه ابتداء ؟ احتمالان ، وعلى كل حال فقد صار ( 1) راجع مجمع البيان : ج 5 ص 372. وَقالَ الَّذِي اشْتَراهُ مِنْ مِصْرَ لامْرَأَتِهِ أَكْرِمِي مَثْواهُ عَسى أَنْ يَنْفَعَنا أَوْ نَتَّخِذَهُ وَلَداً وَكَذلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحادِي ثِ وَاللهُ غالِبٌ عَلى أَمْرِهِ يوسف عليه‌السلام في كنف عزيز مصر ، وقد قالوا : أنه كان كبير الوزراء هناك ، أو كان هو الملك بالذات ، وتوسم العزيز فيه الخير لما رأى على شمائله من آثار الكبر والرفعة ( وَ ) لذا ( قالَ الَّذِي اشْتَراهُ ) اشترى يوسف ( مِنْ مِصْرَ ) من أهل مصر ( لِامْرَأَتِهِ ) وكانت تسمى « زليخا » ( أَكْرِمِي مَثْواهُ ) أي هيئي له مكانا شريفا كريما ، ليكون في راحة ورفاه ( عَسى أَنْ يَنْفَعَنا ) في المستقبل باتخاذه عاملا عندنا في أمورنا ، أو المراد : بيعه والانتفاع بثمنه لأن مثله غالي الثمن ( أَوْ نَتَّخِذَهُ وَلَداً ) على وجه التبنّي. فقد قالوا : أن عزيزا لم يكن له ولد ، كما أنه لم يكن يقدر على إتيان النساء ( وَكَذلِكَ ) كما أنعمنا على يوسف بالنجاة من كيد الأخوة والخلاص من الجب ، كذلك ( مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ ) بما عطفنا عليه قلب الملك الذي اشتراه ـ أو الوزير ـ حتى صار بذلك متمكنا من الأمر والنهي ، وصارت له منزلة حسنة ، والمراد ب « الأرض » أرض مصر ( وَلِنُعَلِّمَهُ مِنْ تَأْوِيلِ الْأَحادِيثِ ) أي تفسير الرؤيا ليبلغ المرتبة العالية بواسطة تمكّنه من هذا العلم. ولعل المراد بذلك النبوة ، وقوله : « ولنعلمه » عطف على المعنى ، أي : دبرنا الأمر ليوسف لنمكنه في الأرض ولنعلمه ، وقد كان التعليم بسبب أنه عف عن الزنا ـ كما قيل ـ ( وَاللهُ غالِبٌ عَلى أَمْرِهِ ) أي على أمر يوسف يحفظه ويهيئ له أسباب الرفاه حتى يوصله إلى السلطة والسيادة ، أو المراد : أن الله غالب على أمر نفسه فمهما شاء من شيء وَلكِنَّ أَكْثَرَ النَّاسِ لا يَعْلَمُونَ (21) وَلَمَّا بَلَغَ أَشُدَّهُ آتَيْناهُ حُكْماً وَعِلْماً وَكَذلِكَ نَجْزِي الْمُحْسِنِينَ (22) وَراوَدَتْهُ تمكن منه ، لا يتمكن أحد على دفعه عن مراده ولا يعجزه شيء ( وَلكِنَّ أَكْثَرَ النَّاسِ لا يَعْلَمُونَ ) وهذا يناسب المعنى الثاني ، فإن الناس غالبا ينظرون إلى المقدمات التي ألفوها فلا يرون النتائج التي يريدها الله سبحانه ، لكنه تعالى يفعل ما يشاء مما لا يظهر للناس بل يخفى عليهم. [23] ولهذا بقي يوسف هناك منفردا مكرما ( وَلَمَّا بَلَغَ أَشُدَّهُ ) بأن اكتمل شبابه وقوته ، و « أشد » جمع لا واحد له ـ كما قيل ـ ( آتَيْناهُ ) أعطيناه ( حُكْماً ) حكمة يعرف بها مواضع الأشياء وموارد الأمور ومصادرها ، فكأنه يحكم على الأشياء حسب موازينها اللائقة بها ( وَعِلْماً ) وهو العلم بالأشياء. ومن المعلوم أن العلم بالشيء غير الحكمة ، فرب عالم غير حكيم ، ورب حكيم غير عالم. ولعل تقديم « الحكم » على « العلم » لما في الحكم من الأهمية ولذا نرى كثيرا من العلماء لا حكمة لهم ، ولذا لا ينجحون في الحياة ( وَكَذلِكَ ) كما جزينا يوسف عليه‌السلام على صبره وعلى المصائب التي وردت عليه ( نَجْزِي ) سائر ( الْمُحْسِنِينَ ) الذين يحسنون في العقيدة والعمل. وهل المراد بقوله « آتيناه » الرسالة ، أو زيادة فيها ؟ احتمالان. [24] وإذ قد انتهت مرحلة امتحان يوسف الأولى ، جاء دور المرحلة الثانية ، وقد كانت أصعب من الدور الأول ، وقد جرت سنة الله سبحانه على امتحان الأنبياء بأشق أنواع الامتحان ، حتى يصلوا لأخذ زمام المجتمع ، وينالوا المراتب السامية ( وَراوَدَتْهُ الَّتِي هُوَ فِي بَيْتِها عَنْ نَفْسِهِ وَغَلَّقَتِ الْأَبْوابَ وَقالَتْ هَيْتَ لَكَ قالَ مَعاذَ اللهِ إِنَّهُ رَبِّي أَحْسَنَ مَثْوايَ الَّتِي هُوَ فِي بَيْتِها ) فاعل « راودت » « التي » والمراد بها « زليخا » زوجة العزيز و « هو » يرجع إلى يوسف ، أي طالبت يوسف المرأة التي كان يوسف في بيتها ( عَنْ نَفْسِهِ ) كأنها تريد انتزاع نفس يوسف وشبابه وطاقاته الجسمية ، فإن « المراودة » مفاعلة ، بمعنى « الذهاب والإياب » لأجل قضاء الحاجة ، فقد تكررت زليخا في الذهاب إلى يوسف ، لتغريه وتنتزع نفسه منه ، بأن يجامعها ، إشباعا لغرائزها الجنسية. ( وَغَلَّقَتِ ) زليخا ( الْأَبْوابَ ) أبواب القصر لئلّا يأتي أحد فجأة فيكشف مؤامرتها على يوسف ، ولفظة « غلقت » من باب التفعيل تدل على كثرة في الأبواب ( وَقالَتْ ) زليخا ليوسف : ( هَيْتَ لَكَ ) أي أقبل وبادر ، فإن « هيت » اسم فعل بمعنى : « هلمّ » و « لك » خطاب ، أي أنت يا يوسف ، يأتي للتأكيد ، كما يقال : «أنت » . وقد يصور هذا المقام الحرج الذي كان يوسف عليه‌السلام عليه ، فشاب عازب ، في قصر مليء بالترف ، وامرأة في سن الاقتضاء ، والأبواب مغلقة ، وتقتضي القاعدة أن قبل ذلك كانت منها إشارات وتطلبات ، والآن أتت الساعة الحاسمة ، بلفظ مكشوف « هيت لك » لكن الإيمان الراسخ في يوسف ضرب بالطلب عرض الحائط ( قالَ مَعاذَ اللهِ ) أعتصم بالله وأعوذ به أن أرتكب هذه الجريمة ( إِنَّهُ رَبِّي ) إن الله ربي ، فكيف أخالفه بعد أن ( أَحْسَنَ مَثْوايَ ) وجعل مكاني مكانا حسنا. ثم أن المراد ب « المثوى » الأصل ، أو المراد : النبوة ، أو المراد : ما هيئ له في بيت العزيز من الكرامة والاحترام. وذكر بعض المفسرين أن إِنَّهُ لا يُفْلِحُ الظَّالِمُونَ (23) وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِها لَوْ لا أَنْ رَأى بُرْهانَ رَبِّهِ كَذلِكَ لِنَصْرِفَ عَنْهُ السُّوءَ وَالْفَحْشاءَ الضمير في « إنه » عائد إلى « زوجها » أي إن سيدي زوجك قد أحسن مثواي فكيف أخونه في زوجته. فإن « الرب » يطلق على السيد المحسن. ( إِنَّهُ ) أي الشأن ( لا يُفْلِحُ الظَّالِمُونَ ) الذين يظلمون أنفسهم بالعصيان ، أو يظلمون الغير بالخيانة في عرضه. [25] إن يوسف لم يهم بالخطيئة ، كيف وقد قال : « معاذ الله » لكن الآية الكريمة تصور الطبيعة البشرية التي تهم بالخطيئة لو لا النبوة والعصمة ( وَلَقَدْ هَمَّتْ بِهِ ) أي همت زليخا وقصدت الخطيئة بيوسف ( وَهَمَّ بِها لَوْ لا أَنْ رَأى بُرْهانَ رَبِّهِ ) أي لكان هم ، لو لم يكن برهان الله يرعى يوسف ، بكونه نبيا معصوما. وهكذا كما تقول : « قصد فلان قتلي وقصدت قتله لو كنت جاهلا » . قال الإمام الصادق عليه‌السلام : « البرهان : النبوة المانعة من ارتكاب الفواحش ، والحكمة الصارفة عن القبائح » (1) . وحاصل المعنى : أن يوسف لو لا النبوة لكان همّ بها ، لكن النبوة منعت عن ذلك لأن المعصوم لا يهم بالخطيئة ( كَذلِكَ ) أريناه البرهان وحفظناه بالنبوة والعصمة ( لِنَصْرِفَ عَنْهُ السُّوءَ ) كل أقسام السوء ، فإن العصمة ملكة لا تدع المتصف بها يفعل شيئا مهما كان ( وَالْفَحْشاءَ ) ( 1) راجع بحار الأنوار : ج 12 ص 335. إِنَّهُ مِنْ عِبادِنَا الْمُخْلَصِينَ (24) وَاسْتَبَقَا الْبابَ وَقَدَّتْ قَمِيصَهُ مِنْ دُبُرٍ وَأَلْفَيا سَيِّدَها لَدَى الْبابِ قالَتْ ما جَزاءُ مَنْ أَرادَ بِأَهْلِكَ سُوءاً إِلاَّ أَنْ يُسْجَنَ أَوْ عَذابٌ أَلِيمٌ (25) قالَ هِيَ راوَدَتْنِي عَنْ نَفْسِي ركوب الفاحشة ، والمراد بها الزنا ( إِنَّهُ ) إن يوسف عليه‌السلام ( مِنْ عِبادِنَا الْمُخْلَصِينَ ) ـ بصيغة المفعول ـ أي الذين أخلصناهم عن الزيف والعصيان ، واخترناهم للنبوة والطهارة. [26] إن زليخا همت بأخذ يوسف للخطيئة ويوسف هم بالفرار منها وتوجه كل منهما نحو الباب ( وَاسْتَبَقَا الْبابَ ) أي تبادر كل من يوسف وزليخا نحو باب الغرفة ، من « استبق » بمعنى السبقة ، وقد كان التوجه إلى الباب أولا من يوسف حيث أراد الهروب والفرار ( وَ ) أخذت زليخا قميص يوسف لتجرّه نحوها ف ( قَدَّتْ ) أي شقت ( قَمِيصَهُ ) أي قميص يوسف ( مِنْ دُبُرٍ ) أي من خلف يوسف ، لأنها أخذت بالقميص من خلفه ( وَأَلْفَيا ) من « ألفى » بمعنى « وجد » ، أي وجدت زليخا ويوسف ( سَيِّدَها ) أي زوج زليخا ، وهو « العزيز » ( لَدَى الْبابِ ) أي قرب الباب ، وهنا سقط في يد زليخا ، وتحيّر يوسف ماذا يصنع ، لأن المنظر كان مريبا. وهنا بادرت زليخا لتبرير نفسها ( قالَتْ ) مخاطبة زوجها : ( ما ) نافية ، أي ليس ( جَزاءُ مَنْ أَرادَ بِأَهْلِكَ ) زوجتك ( سُوءاً ) عملا قبيحا ( إِلَّا أَنْ يُسْجَنَ ) يحبس ( أَوْ عَذابٌ أَلِيمٌ ) بأن يضرب بالسياط أو نحو ذلك.` },
            { text: "وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ ٱللَّهِ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ", tafsir: `` },
            { text: "وَلَقَدْ هَمَّتْ بِهِۦ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَٰنَ رَبِّهِۦ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ", tafsir: `` },
            { text: "وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَٰذِبِينَ", tafsir: `يوسف عليه‌السلام : ( هِيَ ) أي زليخا هي التي ( راوَدَتْنِي عَنْ نَفْسِي ) وَشَهِدَ شاهِدٌ مِنْ أَهْلِها إِنْ كانَ قَمِيصُهُ قُدَّ مِنْ قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ الْكاذِبِينَ (26) وَإِنْ كانَ قَمِيصُهُ قُدَّ مِنْ دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ الصَّادِقِينَ (27) فَلَمَّا رَأى قَمِيصَهُ قُدَّ مِنْ دُبُرٍ أي طالبتني بالسوء ( وَشَهِدَ شاهِدٌ مِنْ أَهْلِها ) أهل المرأة. روي عن الإمام الصادق عليه‌السلام أنه قال : « ألهم الله عزوجل يوسف أن قال للملك : سل هذا الصبي في المهد ، فإنه يشهد أنها راودتني عن نفسي. فقال العزيز : الصبي ؟ فأنطق الله الصبي في المهد ليوسف » . أقول : قال بعضهم : أن الابن كان له من العمر ثلاثة أشهر ، وكان ابن أخت زليخا ، وكانت الشهادة أن قال : ( إِنْ كانَ قَمِيصُهُ ) أي ثوب يوسف عليه‌السلام ( قُدَّ ) أي شقّ ( مِنْ قُبُلٍ ) من مقدّمه ( فَصَدَقَتْ ) زليخا ( وَهُوَ مِنَ الْكاذِبِينَ ) أي أن يوسف كاذب ، إذ يظهر أن يوسف أراد المرأة وهي أخذت بثوبه لتدفعه عن نفسها فانشق القميص ، أو لأنه يدل أن المرأة فرّت ويوسف عقبها فتعثر بثوبه من الأمام وانشق الثوب من قدام.` },
            { text: "وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّٰدِقِينَ", tafsir: `إن كان ثوب يوسف شقّ من الخلف ( فَكَذَبَتْ ) تبيّن كذب زليخا ( وَهُوَ مِنَ الصَّادِقِينَ ) فيدل على أن المرأة هي التي راودت يوسف وأنه أراد الفرار ، لأنه يدل على أن المرأة تبعت يوسف وأخذت بثوبه من خلف ، فانشق الثوب لجذبها له. [29] فالتفت الزوج إلى القميص ولما ( رَأى قَمِيصَهُ ) أي ثوب يوسف عليه‌السلام ( قُدَّ مِنْ دُبُرٍ ) أي شقّ من خلف ، عرف أن المرأة هي التي قالَ إِنَّهُ مِنْ كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ (28) يُوسُفُ أَعْرِضْ عَنْ هذا وَاسْتَغْفِرِي لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخاطِئِينَ (29) وَقالَ نِسْوَةٌ فِي الْمَدِينَةِ خانت وأرادت السوء ( قالَ ) متوجها إلى زليخا ( إِنَّهُ ) أي هذا العمل الذي رأى آثاره ( مِنْ كَيْدِكُنَ ) وحيلكن معاشر النساء ( إِنَّ كَيْدَكُنَّ عَظِيمٌ ) تعملن الأعمال السيئة ، ثم تلقين التهم على البريء. [30] ثم توجه السيد إلى يوسف عليه‌السلام قائلا : يا ( يُوسُفُ أَعْرِضْ عَنْ هذا ) الحديث واكتمه فلا تفشه ( وَاسْتَغْفِرِي ) يا زليخا ( لِذَنْبِكِ إِنَّكِ كُنْتِ مِنَ الْخاطِئِينَ ) أنت أذنبت لا يوسف عليه‌السلام . قال « من الخاطئين » ولم يقل « من الخاطئات » تغليبا ، كما قال : ( وَارْكَعِي مَعَ الرَّاكِعِينَ ) (1) ، وكان ذلك لأن أول ما يتبادر إلى الذهن الرجال ، سواء في الإطاعة والعصيان ، أو غيرهما. [31] ثم لم يمض زمان حتى شاع هذا الأمر في البلد وأن زليخا قصدت يوسف بالسوء ( وَقالَ نِسْوَةٌ ) أي جماعة من النساء. وإنما ذكر الفعل لأنه يجوز في الجمع مذكرا كان أو مؤنثا الأمران ، تقول « قال وقالت رجال » ، وكذا « قال وقالت نساء » ، باعتبار اللفظ والمعنى ، كما أن « قالت » باعتبار جماعة الرجال ، قال ابن مالك : و التاء مع جمع سوى السالم من مذكر كالتاء مع إحدى اللبن ( فِي الْمَدِينَةِ ) في مصر ، وكان ذكر هذه الجملة لإفادة أن الخبر ( 1) آل عمران : 44. امْرَأَتُ الْعَزِيزِ تُراوِدُ فَتاها عَنْ نَفْسِهِ قَدْ شَغَفَها حُبًّا إِنَّا لَنَراها فِي ضَلالٍ مُبِينٍ (30) فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَأً وَآتَتْ كُلَّ واحِدَةٍ مِنْهُنَّ سِكِّيناً وَقالَتِ اخْرُجْ شاع في البلد ، ولو لم تذكر لاحتمل أن ذلك قول نسوة القصر ، فقد قلن تلك النسوة على وجه التعجّب والاستغراب : ( امْرَأَتُ الْعَزِيزِ تُراوِدُ فَتاها عَنْ نَفْسِهِ ) أي تدعو مملوكها إلى نفسه ، فتريد أن تسلب نفس المملوك ، ليفجر بها ( قَدْ شَغَفَها حُبًّا ) دخل حب الفتى في شغاف قلبها ، فإن « الشغاف » هو حجاب القلب ، يقال : « شغف زيد عمرو حبا » أي خرق حب زيد شغاف قلب عمرو ، وفاعل شغفها الضمير الراجع إلى يوسف عليه‌السلام ( إِنَّا لَنَراها ) نرى امرأة العزيز ( فِي ضَلالٍ مُبِينٍ ) انحراف عن نهج الصواب واضح ، إذ كيف تتعلق المرأة ذات البعل بعبدها.` },
            { text: "فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ", tafsir: `` },
            { text: "يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَٱسْتَغْفِرِى لِذَنۢبِكِ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ", tafsir: `` },
            { text: "وَقَالَ نِسْوَةٌ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ قَدْ شَغَفَهَا حُبًّا إِنَّا لَنَرَىٰهَا فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `` },
            { text: "فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنْ هَٰذَآ إِلَّا مَلَكٌ كَرِيمٌ", tafsir: `زليخا ( بِمَكْرِهِنَ ) أي تعيير تلك النسوة لها بحب يوسف. وإنما سمي « مكرا » لأن قصدهن من هذا القول كان أن يرين يوسف لما وصف لهن منه حسنه ـ كذا في « المجمع » ـ. وقيل : لأنهن أخفين التعيير كما يخفي الماكر مكره ( أَرْسَلَتْ إِلَيْهِنَ ) تطلبهن للضيافة عندها ( وَأَعْتَدَتْ ) هيأت ( لَهُنَّ مُتَّكَأً ) هو ما يتكأ عليه لطعام أو شراب أو حديث ، أي هيأت لهن مأدبة وقد كان العادة أن يأكلوا الطعام وهم متكئون على الوسائد ـ كما هو عادة أهل الترف ـ ( وَآتَتْ ) أعطت زليخا ( كُلَّ واحِدَةٍ مِنْهُنَّ سِكِّيناً ) لقطع اللحم ، أو تقشير الفاكهة كما هي العادة الجارية إلى هذا الزمان ( وَقالَتِ ) زليخا ليوسف حين اشتغلن بالتقشير أو التقطيع : ( اخْرُجْ ) يا يوسف عَلَيْهِنَّ فَلَمَّا رَأَيْنَهُ أَكْبَرْنَهُ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حاشَ لِلَّهِ ما هذا بَشَراً إِنْ هذا إِلاَّ مَلَكٌ كَرِيمٌ (31) قالَتْ فَذلِك ُنَّ الَّذِي لُمْتُنَّنِي فِيهِ ( عَلَيْهِنَ ) أمرته بذلك ليرين جماله فلا يعذلنها في ما قصدته منه فخرج عليه‌السلام حيث كان بصورة مملوك مطيع لديها ولما ( رَأَيْنَهُ أَكْبَرْنَهُ ) أي أعظمنه وتحيّرن في جماله ، فقد كان خارق الحسن والجمال ( وَقَطَّعْنَ أَيْدِيَهُنَ ) بتلك السكاكين ، بدل تقطيع اللحم أو الفاكهة ، على جهة الخطأ ، فقد بعثت دهشتهن بجماله أن لم يلتفتن إلى صنعهن ، والمراد بالقطع ـ حسب الظاهر ـ الجرح والخدش ، يقال : « فلان قطع يده بالسكين » إذا جرحها وخدشها. ( وَقُلْنَ حاشَ لِلَّهِ ) وهي كلمة تنزيه تقال في موضع الدهشة والعجب ، لبيان الدهشة في صنعه سبحانه ، وأصل « حاش » « حاشا » حذفت الألف تخفيفا ، بمعنى التنزيه ، و « لله » جار ومجرور متعلق به ما هذا الذي نراه ، أي يوسف عليه‌السلام ( بَشَراً ) « ما » تعمل عمل ليس ف « هذا » اسمها ، و « بشرا » خبرها ، أي ليس هذا كالبشر ، فإن هذا الجمال الخارق لا يوجد في البشر ( إِنْ هذا ) ما هذا ( إِلَّا مَلَكٌ كَرِيمٌ ) رفيع المنزلة عند الله سبحانه ، ذو كرامة ، وإلّا لم يمنحه هذا الجمال.` },
            { text: "قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ ٱلصَّٰغِرِينَ", tafsir: `زليخا بعد أن رأت أنها فازت عليهن وأنهن أعطين الحق لها فيما قصدت من السوء بيوسف : ( فَذلِكُنَ ) « ذا » إشارة إلى يوسف ، و « كن » خطاب لهن ، أي فهذا يوسف ـ أيتها النسوة ـ هو ( الَّذِي لُمْتُنَّنِي فِيهِ ) من « لام » بمعنى « عذل » أي عذلتنني بالنسبة إليه ، قائلات كيف أن امرأة العزيز تراود فتاها ؟ ثم قالت زليخا ، وقد بقي لها تعلق وَلَقَدْ راوَدْتُهُ عَنْ نَفْسِهِ فَاسْتَعْصَمَ وَلَئِنْ لَمْ يَفْعَلْ ما آمُرُهُ لَيُسْجَنَنَّ وَلَيَكُوناً مِنَ الصَّاغِرِينَ (32) قالَ رَبِّ السِّجْنُ أَحَبُّ إِلَيَّ مِمَّا يَدْعُونَنِي إِلَيْهِ وَإِلاَّ تَصْرِفْ عَنِّي كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ به : ( وَلَقَدْ راوَدْتُهُ عَنْ نَفْسِهِ ) أي طلبت نفس يوسف ( فَاسْتَعْصَمَ ) أي لاذ بالعصمة والامتناع ( وَلَئِنْ لَمْ يَفْعَلْ ) بعد ذلك ( ما آمُرُهُ ) من الفعل ( لَيُسْجَنَنَ ) أي ليحبس في السجن ، فإني أكيد به حتى أوقعه في السجن ( وَلَيَكُوناً مِنَ الصَّاغِرِينَ ) الصاغر هو الذليل ، من الصفات ، أي لأذله حتى يكون ذليلا. [34] ولما رأى يوسف عليه‌السلام إصرارها على الخطيئة به اختار السجن لنفسه الشريفة عن الآثام ، وليخلص من التذبذب والاتهام ، ف ( قالَ ) : يا ( رَبِّ السِّجْنُ أَحَبُّ إِلَيَّ مِمَّا يَدْعُونَنِي إِلَيْهِ ) من الفاحشة ، وفي الإتيان بلفظ « يدعونني » دلالة على أن تلك النسوة أيضا طمعن فيه. و قد روي عن الإمام السجاد عليه‌السلام : « أن النسوة لما خرجن من عندها أرسلت كل واحدة منهن إليه سرا من صاحبته تسأله الزيارة لها » (1) . ولا يخفى أن « أحب » هنا مجرد عن معنى التفضيل ، كما هو القاعدة في أمثاله كقوله : ( هُوَ خَيْرٌ ثَواباً ) (2) ، و ( ( أَحْسَنُ تَأْوِيلاً ) (3) ، ( وَإِلَّا تَصْرِفْ ) يا رب ( عَنِّي كَيْدَهُنَ ) بالعصمة والحفظ ( أَصْبُ إِلَيْهِنَ ) يقال : « صبا يصبو » ، إذا مال نحو الشهوة الجنسية ، من ( 1) راجع بحار الأنوار : ج 12 ص 275. ( 2) الكهف : 45. ( 3) النساء : 60. وَأَكُنْ مِنَ الْجاهِلِينَ (33) فَاسْتَجابَ لَهُ رَبُّهُ فَصَرَفَ عَنْهُ كَيْدَهُنَّ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ (34) ثُمَّ بَدا لَهُمْ مِنْ بَعْدِ ما رَأَوُا الْآياتِ لَيَسْجُنُنَّهُ حَتَّى حِينٍ (35) « الصبوة » وهي لطافة الهوى ، أي : أمل إلى تلك النساء. ومن المعلوم أنه لو لا لطف الله وعصمته تميل النفس البشرية إلى الشهوات ( وَأَكُنْ مِنَ الْجاهِلِينَ ) يقال للعاصي : جاهل ، وإن كان عالما ، لأنه لو لم يجهل حقيقة لم يعرض نفسه لعقاب الله سبحانه.` },
            { text: "قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَٰهِلِينَ", tafsir: `` },
            { text: "فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `أجاب الله دعاء يوسف ( فَصَرَفَ عَنْهُ كَيْدَهُنَ ) فقد عصمه سبحانه حتى أنه لم يكن يتزحزح عن الطهارة ولو أصيب بالأذى وسجن ، كما ألقى اليأس في قلب زليخا والنسوة لامتناع يوسف عن الفاحشة ( إِنَّهُ ) سبحانه ( هُوَ السَّمِيعُ ) لداعي الداعي ( الْعَلِيمُ ) بالنيات.` },
            { text: "ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْـَٔايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍ", tafsir: `ظهر للعزيز وزوجته وأصحابهما ( مِنْ بَعْدِ ما رَأَوُا الْآياتِ ) الدالة على براءة يوسف عليه‌السلام ( لَيَسْجُنُنَّهُ ) فإن زليخا خدعت زوجها بأن يسجن يوسف حتى يظن الناس أنه المجرم وحتى تشفي زليخا غيظها منه حيث لم يطعها في الفاحشة ( حَتَّى حِينٍ ) إلى مدة حتى تخمد الضوضاء ، وينسى الناس القصة. [37] وسيق إلى السجن يوسف البريء عليه‌السلام وأخذت المرأة المجرمة تسرح وتمرح ـ كما هو عادة الدنيا ـ روي عن الإمام الرضا عليه‌السلام : أن السجان قال ليوسف : إني لأحبك. فقال يوسف : ما أصابني إلا من الحب ، إن كانت خالتي أحبتني سرقتني ، وإن كان أبي أحبني حسدني إخوتي ، وَدَخَلَ مَعَهُ السِّجْنَ فَتَيانِ قالَ أَحَدُهُما إِنِّي أَرانِي أَعْصِرُ خَمْراً وَقالَ الْآخَرُ إِنِّي أَرانِي أَحْمِلُ فَوْقَ رَأْسِي خُبْزاً تَأْكُلُ الطَّيْرُ مِنْهُ نَبِّئْنا بِتَأْوِيلِهِ إِنَّا نَراكَ مِنَ الْمُحْسِنِينَ (36) و إن كانت امرأة العزيز أحبتني حبستني (1) . و روي عن الصادق عليه‌السلام : أن يوسف بكى على يعقوب حتى تأذى منه أهل السجن فقالوا له : إما أن تبكي الليل وتسكن بالنهار وإما أن تبكي بالنهار وتسكن بالليل على واحد منهما (2) . ( وَدَخَلَ مَعَهُ ) مع يوسف ( السِّجْنَ فَتَيانِ ) شابان ، وكانا عبدين للملك أحدهما خبازه والآخر صاحب شرابه. وفي ذات يوم جاءا إلى يوسف يبيّنان له رؤيا رأياها ـ بزعمهما ـ ف ( قالَ أَحَدُهُما ) وهو صاحب الشراب : ( إِنِّي أَرانِي ) أرى نفسي في المنام ( أَعْصِرُ خَمْراً ) أي أعصر العنب لصنعه خمرا ، فقد سمي العنب بذلك بعلاقة الأول ، كما يقال : « فلان يطبخ الدبس » وإنما يطبخ التمر ليكون دبسا ( وَقالَ الْآخَرُ ) وهو خباز الملك : ( إِنِّي أَرانِي ) أرى نفسي في المنام ( أَحْمِلُ فَوْقَ رَأْسِي خُبْزاً تَأْكُلُ الطَّيْرُ مِنْهُ ) من ذلك الخبز. ثم قال الفتيان ليوسف : ( نَبِّئْنا ) أخبرنا ( بِتَأْوِيلِهِ ) ما يؤول إليه منامنا ( إِنَّا نَراكَ مِنَ الْمُحْسِنِينَ ) الذي يحسن إلى الناس. ومن المعلوم إن الإنسان المحسن يتوسّم فيه الخير في كل شيء حتى في تأويل الرؤيا وتعبير المنام ، أو المراد تحسن تعبير الرؤيا. قال الصادق عليه‌السلام : لما أمر الملك بحبس يوسف في السجن ( 1) بحار الأنوار : ج 12 ص 247. ( 2) إرشاد القلوب : ج 1 ص 95. قالَ لا يَأْتِيكُما طَعامٌ تُرْزَقانِهِ إِلاَّ نَبَّأْتُكُما بِتَأْوِيلِهِ ألهمه الله تعالى علم تعبير الرؤيا فكان يعبر لأهل السجن رؤياهم (1) . أقول : وكأن ذلك العلم صار شعارا لمن منع نفسه عن الشهوة الجنسية ، فقد قالوا : أن ابن سيرين كان تلميذا عند بزاز وكان جميلا جدا وفي ذات يوم جاءت امرأة واشترت من البزاز أجناسا ثم حمّلتها الفتى ليأتي بها إلى بيتها ، ولما أن دخلا الدار أغلقت الباب وقالت : هيت لك. قال ابن سيرين ـ لما لم يجد حيلة للفرار منها ـ : ائذني لي بالبراز لأقضي حاجتي ثم بعد ذلك أنت وشأنك. ولما أن دخل المرحاض لوث نفسه بالنجاسة ، فلما خرج ورأته المرأة بتلك الحالة عافته استقذار له ، ومن ذلك الحين وهب الله له علم الرؤيا. [38] وهنا أراد يوسف عليه‌السلام أن يرشد الفتيين إلى الطريقة الصحيحة كما هو عادة الأنبياء والمرشدين حتى ينتهزوا كل فرصة لنشر الدين وتبليغ رسالة الله سبحانه ، وقد أراد أن يقدم لذلك مقدمة مطمئنا بصحة ما يدعو إليه ، فإن غالب الناس إذا رأوا من أحد خارقة أو ما أشبهها اطمأنوا إليه وصدقوا كلامه ، بخلاف ما لو كان الكلام مجرد منطق ودليل ، فإن الناس ينظرون إلى القائل لا إلى القول. ولذا بدأ يوسف يبين لهم أنه يعرف بعض أمور الغيب بتعليم الله له ، فبإمكانه أن يخبر عن الطعام الذي يؤتى به لهما قبل أن يؤتى به ف ( قالَ لا يَأْتِيكُما ) أيها الفتيان ( طَعامٌ تُرْزَقانِهِ ) لأجل أكلكما ورزقكما ( إِلَّا نَبَّأْتُكُما بِتَأْوِيلِهِ ) آتي بصفة ذلك الطعام وسائر خصوصياته ، وإنما قال « بتأويله » لأن الطعام يؤول إلى تلك الصفة ، فمثلا اللحم المعد للطعام يؤول إلى « الكباب » أو « المرق » أو ما أشبههما ، وقد لوحظ في ( 1) تفسير العياشي : ج 2 ص 176. قَبْلَ أَنْ يَأْتِيَكُما ذلِكُما مِمَّا عَلَّمَنِي رَبِّي إِنِّي تَرَكْتُ مِلَّةَ قَوْمٍ لا يُؤْمِنُونَ بِاللهِ وَهُمْ بِالْآخِرَةِ هُمْ كافِرُونَ (37) وَاتَّبَعْتُ مِلَّةَ آبائِي إِبْراهِيمَ وَإِسْحاقَ وَيَعْقُوبَ اللفظ ـ الجناس ـ حيث تقدم لفظ « التأويل » بالنسبة إلى الرؤيا ، وقد كان عيسى عليه‌السلام كذلك كما قال : ( وَأُنَبِّئُكُمْ بِما تَأْكُلُونَ وَما تَدَّخِرُونَ فِي بُيُوتِكُمْ ) (1) . ( قَبْلَ أَنْ يَأْتِيَكُما ) التأويل ( ذلِكُما ) أي ذلك التأويل للأشياء الغائبة عن الحواس ، و « كما » خطاب ، أي أن التأويل أيها الفتيان ( مِمَّا عَلَّمَنِي رَبِّي ) ومن هذا الباب تطرق إلى ذكر الرب ، ليتسنى له الشرح حوله ( إِنِّي تَرَكْتُ مِلَّةَ قَوْمٍ لا يُؤْمِنُونَ بِاللهِ ) أي رفضت فراعنة مصر الذين يتخذون الأصنام آلهة ، أي أني تركت هذه الملة. وليس معنى « تركت » كونه عليه‌السلام فيها ، ثم تركها ، بل معناه : عدم قبولها ورفضها من الابتداء ، فإن الفعل يستعمل في المعنيين ( وَهُمْ بِالْآخِرَةِ هُمْ كافِرُونَ ) فلا يؤمنون بمبدإ ولا معاد ، وحيث تركت تلك الملة ألهمني الله الغيب وتأويل الرؤيا.` },
            { text: "وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًا وَقَالَ ٱلْـَٔاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًا تَأْكُلُ ٱلطَّيْرُ مِنْهُ نَبِّئْنَا بِتَأْوِيلِهِۦٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ", tafsir: `` },
            { text: "وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ", tafsir: `و « الملة » هي الطريقة الدينية ، يقال : « ملة اليهود » و « ملة النصارى » ولا يقال : ملة العطارين ( إِبْراهِيمَ ) جد أبيه ( وَإِسْحاقَ ) جده ( وَيَعْقُوبَ ) أبيه ، وبذلك بيّن عليه‌السلام أنه من بيت النبوة والطهارة حتى يكون كلامه مسموعا لديهم. فقد جرت عادة الناس أن يسمعوا من ذوي البيوتات والشرف أصحاب الحسب ( 1) آل عمران : 50. ما كانَ لَنا أَنْ نُشْرِكَ بِاللهِ مِنْ شَيْءٍ ذلِكَ مِنْ فَضْلِ اللهِ عَلَيْنا وَعَلَى النَّاسِ وَلكِنَّ أَكْثَرَ النَّاسِ لا يَشْكُرُونَ (38) يا صاحِبَيِ السِّجْنِ والنسب ، وكان إبراهيم عليه‌السلام مشهود لدى الجميع ، ولعل إسحاق ويعقوب كان كذلك ( ما كانَ لَنا ) أي لا يجوز لنا معاشر الأنبياء ، أو المراد عموم البشر ، أي لا يحق للبشر ( أَنْ نُشْرِكَ بِاللهِ مِنْ شَيْءٍ ) غيره باتخاذ الأصنام آلهة ، وكيف يجوز للبشر أن يكفر بخالقه ويجعل له أندادا ؟ ( ذلِكَ ) التمسك بالتوحيد والبراءة من الشرك ( مِنْ فَضْلِ اللهِ عَلَيْنا ) حيث هدانا إلى ذلك وأوحى إلينا به ( وَعَلَى النَّاسِ ) حيث هداهم بسبب الفطرة والأنبياء. ولعل سبب ذكر « علينا » مستقلا ، لاختصاصهم بالنبوة والوحي ( وَلكِنَّ أَكْثَرَ النَّاسِ لا يَشْكُرُونَ ) هذه النعمة العظيمة ، وهي نعمة الهداية ، بل يكفرون بها باتخاذ الأصنام آلهة. [40] وبعد ما بيّن عليه‌السلام طريقته وملته ، وذكر أنه من بيت رفيع وأنه يعلم بعض أمور الغيب بتعليم الله له حتى يطمئن إليه ، أخذ في الاستدلال على التوحيد ، وقد كان الموقع مناسبا جدا للتبليغ ، فإن المستمع حيث ينتظر جوابه يصغي جيدا ، بخلاف ما لو أجابهم عن تأويل رؤياهم ثم بيّن التوحيد ، وحيث قدم له مقدمة صار الموقع أنسب ، لأنه بين ماض مشوّق ومستقبل متقرب ، فالنفس متفتحة للاستماع والقبول ( يا صاحِبَيِ السِّجْنِ ) أي يا صاحبي فيه ، فإن الشيء قد يضاف إلى الزمان والمكان مجازا ، كما قال الشاعر : يا سارق الليلة أهل الدار يا سارقا مالي ومال جاري أَ أَرْبابٌ مُتَفَرِّقُونَ خَيْرٌ أَمِ اللهُ الْواحِدُ الْقَهَّارُ (39) ما تَعْبُدُونَ مِنْ دُونِهِ إِلاَّ أَسْماءً سَمَّيْتُمُوها أَنْتُمْ وَآباؤُكُمْ ما أَنْزَلَ اللهُ بِها مِنْ سُلْطانٍ أو المراد « ملازمي السجن » فإن « صاحب » يقال للملازم للشيء ، يقال : « صاحب الدكان » لمن لازمه بالبيع والشراء فيه .. وهكذا. ( أَ أَرْبابٌ ) أي هل آلهة ( مُتَفَرِّقُونَ ) شتى متعدّدون ( خَيْرٌ ) في اتخاذها آلهة وعبادتها ، بأن يعبد الإنسان آلهة من حجر وخشب ( أَمِ اللهُ الْواحِدُ ) المتفرد الذي خلق كل شيء ، وبيده كل شيء ( الْقَهَّارُ ) الغالب الذي لا يعادله شيء ولا يتمكن شيء أن يقاومه ؟ ومن الطبيعي أن يكون الجواب : بل الله الواحد القهار.` },
            { text: "يَٰصَٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ", tafsir: `` },
            { text: "مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءً سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ", tafsir: `أنتم أيها المشركون ( مِنْ دُونِهِ ) من دون الله ( إِلَّا أَسْماءً سَمَّيْتُمُوها ) أي أسماء الآلهة لا حقيقة الإله ، فإن ما تعبدون إنما هي أسماء فارغة لا حقيقة لها في منصب الألوهية ، كما يقال : « الحاكم الفلاني اسم مجرد » يراد أنه ليس بحقيقة حاكم ، وليس لديه علم الحاكم وإرادته ( أَنْتُمْ وَآباؤُكُمْ ) بدل من ضمير الجمع ، فأنتم وآباؤكم إنما تعبدونها باعتبار أسماء تطلقون عليها ، فكأنكم لا تعبدون إلا الأسماء المجردة ( ما أَنْزَلَ اللهُ بِها ) بتلك الآلهة ، أو بأسمائها ( مِنْ سُلْطانٍ ) من حجة ، أي لا حجة لكم في كونها آلهة ، إذ الحجة لا بد أن تكون معقولة ، والعقل يأبى أن ينحت الإنسان حجرا أو ينجر صنما ثم يقول إنه إله الكون ، والله سبحانه لم يقل ذلك ولم ينزل بذلك دليلا. ولعل ترك الدليل العقلي إنما هو لوضوحه ، ولأنهم كانوا ينسبون ذلك إليه سبحانه. إِنِ الْحُكْمُ إِلاَّ لِلَّهِ أَمَرَ أَلاَّ تَعْبُدُوا إِلاَّ إِيَّاهُ ذلِكَ الدِّينُ الْقَيِّمُ وَلكِنَّ أَكْثَرَ النَّاسِ لا يَعْلَمُونَ (40) يا صاحِبَيِ السِّجْنِ ( إِنِ الْحُكْمُ ) ليس الحكم والأمر والنهي ( إِلَّا لِلَّهِ ) فكيف يعبد سواه ؟ إذ العبادة خاصة بمن له الحكم والأمر والنهي ، لأن العبادة خضوع ، والخضوع لا يليق إلا أمام الحاكم الآمر والناهي ، وقد ( أَمَرَ ) سبحانه ( أَلَّا تَعْبُدُوا ) أحدا ( إِلَّا إِيَّاهُ ) وحده لا شريك له. ولعل « إن الحكم » و « أمر » إشارة إلى مرتبتين من التوحيد. فقد قالوا إن التوحيد على أربعة أقسام : توحيد الذات ، بأن يعتقد الإنسان أن الإله واحد لا شريك له ، وتوحيد الصفات ، بأن يعتقد الإنسان أن صفات الله عين ذاته لا تعدّد فيها ولا مغايرة ، وتوحيد الخلق ، بأن يعتقد الإنسان أن جميع الخلق إنما هو منه وحده لا يشاركه فيه أحد ، وتوحيد العبادة ، بأن لا يعبد الإنسان أحدا إلا إياه. ( ذلِكَ ) التوحيد ( الدِّينُ الْقَيِّمُ ) أي الطريقة المستقيمة ، فإن « الدين » بمعنى الطريقة ، و « القيم » بمعنى المستقيم ، مشتق من « قام » ، لا اعوجاج فيه ولا انحراف ( وَلكِنَّ أَكْثَرَ النَّاسِ لا يَعْلَمُونَ ) إن هذا هو الدين القيم ، وإن سواه معوج منحرف. [42] وإذ أتم يوسف عليه‌السلام الإرشاد والتبليغ ، شرع في جواب سؤال صاحبيه من الرؤيا ، فقال : ( يا صاحِبَيِ السِّجْنِ ) أصله « صاحبين » حذفت النون لإضافته إلى السجن ، كما هو القاعدة ، قال ابن مالك : نونا تلي الإعراب أو تنوينا مما تضف أحذف كطور سينا أَمَّا أَحَدُكُما فَيَسْقِي رَبَّهُ خَمْراً وَأَمَّا الْآخَرُ فَيُصْلَبُ فَتَأْكُلُ الطَّيْرُ مِنْ رَأْسِهِ قُضِيَ الْأَمْرُ الَّذِي فِيهِ تَسْتَفْتِيانِ (41) ( أَمَّا أَحَدُكُما ) وهو ساقي الملك الذي رأى أنه كان يعصر خمرا ، فيخرج من السجن ويصير حاله كحاله السابق ( فَيَسْقِي رَبَّهُ ) أي سيده الملك ( خَمْراً ) كما كان يسقي من ذي قبل. وفي بعض التفاسير : أنه أخبر بأن بقاءه في السجن ثلاثة أيام ويخرج اليوم الرابع. وإنما قال « ربه » لأن الرب يطلق على الصاحب ، يقال : « رب الدار » و « رب الدابة » . ( وَأَمَّا الْآخَرُ ) وهو الخباز الذي زعم أنه رأى خبزا على رأسه تأكل الطير منه ( فَيُصْلَبُ ) أي يشنق فيموت ( فَتَأْكُلُ الطَّيْرُ ) تأنيث الفعل ، باعتبار كون الطير اسم جنس يطلق على الجماعة من الطائر ( مِنْ رَأْسِهِ ) أي من دماغه. في الحديث : إن الخباز كان كاذبا في ما ادعى من الرؤيا ولم يكن رأى شيئا في منامه وإنما اختلق ذلك. وفي بعض التفاسير : لما قال يوسف ذلك ، قال الرجل : كذبت وما رأيت شيئا ، وإنما كنت ألعب (1) . فقال يوسف عليه‌السلام : ( قُضِيَ الْأَمْرُ الَّذِي فِيهِ تَسْتَفْتِيانِ ) أي فرغ من الأمر الذي تسألان وتطلبان معرفته ، وما قلته لكما فإنه نازل بكما وكائن لا محالة ، و « الاستفتاء » طلب الفتيا ، أي الجواب في مسألة متعلقة بالدين أو الدنيا ، وقد كان الواقع الذي سوف يجري على الخباز ( 1) مجمع البيان : ج 5 ص 404. وَقالَ لِلَّذِي ظَنَّ أَنَّهُ ناجٍ مِنْهُمَا اذْكُرْنِي عِنْدَ رَبِّكَ فَأَنْساهُ الشَّيْطانُ ذِكْرَ رَبِّهِ فَلَبِثَ فِي السِّجْنِ بِضْعَ سِنِينَ (42) من خلال شعاعه في دماغه ، فاخترع هذه الرؤيا المكذوبة ، ويوسف عليه‌السلام إنما نظر إلى الواقع فأخبره به ـ وكان ذلك من علم الغيب لا من تفسير الرؤيا ـ.` },
            { text: "يَٰصَٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًا وَأَمَّا ٱلْـَٔاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ", tafsir: `` },
            { text: "وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ", tafsir: `يوسف عليه‌السلام : ( لِلَّذِي ظَنَّ أَنَّهُ ناجٍ مِنْهُمَا ) أي للعاصي الذي ظن يوسف عليه‌السلام أنه ينجو من السجن والقتل ، من صاحبيه ، ولعل التعبير ب « ظن » لإمكان محو ما علم في علمه سبحانه فإن الأمور المستقبلة ـ إلا بعضها ـ قابلة للمحو ، قال سبحانه : ( يَمْحُوا اللهُ ما يَشاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتابِ ) (1) ، ( اذْكُرْنِي عِنْدَ رَبِّكَ ) أي اذكر حالي عند الملك وإني إنما حبست ظلما ، لكي يفرج عني ويطلق سراحي فلما تحقق ما قاله يوسف وأن صاحب الشراب تخلّص من السجن ، وأن الخباز صلب ( فَأَنْساهُ الشَّيْطانُ ذِكْرَ رَبِّهِ ) أي أنسى الشيطان صاحب الشراب أن يذكر يوسف لربه الملك ( فَلَبِثَ ) يوسف ( فِي السِّجْنِ ) بقي فيه ( بِضْعَ سِنِينَ ) « بضع » كلمة بمعنى « ما دون العشرة » ، وأصله بمعنى « القطعة » من الدهر ، أو من غيره. و منه قول النبي صلى‌الله‌عليه‌وآله‌وسلم : « فاطمة بضعة مني » (2) . [44] بقي يوسف سنوات في السجن ، وساقي الملك ناس ، مشغول ( 1) الرعد : 40. ( 2) وسائل الشيعة : ج 20 ص 67. وَقالَ الْمَلِكُ إِنِّي أَرى سَبْعَ بَقَراتٍ سِمانٍ يَأْكُلُهُنَّ سَبْعٌ عِجافٌ وَسَبْعَ سُنْبُلاتٍ خُضْرٍ وَأُخَرَ يابِساتٍ يا أَيُّهَا الْمَلَأُ أَفْتُونِي فِي رُءْيايَ إِنْ كُنْتُمْ لِلرُّءْيا تَعْبُرُونَ (43) بملهيات القصر ـ وكذلك ينسي الرخاء الإنسان زميله الذي يكابد البلاء ـ حتى رأى الملك رؤيا هالته فطلب معبّرا لذلك. وهناك تذكر الساقي يوسف السجين الذي عبّر رؤياه من ذي قبل ، وشاءت إرادة الله سبحانه إنقاذ يوسف في ذلك الحين ، وقد كان السجن والجب وكيد المرأة وحسد الأخوة امتحانات له ولرفع درجته ، فقد وكّل البلاء بالأنبياء ثم الأولياء ثم الأمثل فالأمثل ( وَقالَ الْمَلِكُ إِنِّي أَرى ) في منامي. وكأنه حكاية حال ما ماضية ، وإلا فاللازم أن يقول إني رأيت ( سَبْعَ بَقَراتٍ سِمانٍ ) جمع « سمين » ضد هزيل ( يَأْكُلُهُنَّ سَبْعٌ عِجافٌ ) أي سبع بقرات كن هزيلات ، و « عجاف » جمع « أعجف » وهو الهزيل ومؤنثه « عجفاء » ، فقد أكلت البقرات الهزال البقرات السمان حتى دخلن في بطن الهزال ( وَ ) أرى ( سَبْعَ سُنْبُلاتٍ ) و « السنبلة » هي العود الذي تنبت عليه حبوب الحنطة والشعير وما أشبه ( خُضْرٍ ) جمع « خضراء » ، أي قد انفتق حبها وكانت رطبة ( وَ ) سبع سنبلات ( أُخَرَ يابِساتٍ ) قد حصدت فالتوت تلك اليابسات على تلك الخضر حتى غلبن عليها. ( يا أَيُّهَا الْمَلَأُ ) أي الجماعة الأشراف ، فإن الملأ هم الأشراف ( أَفْتُونِي فِي رُءْيايَ ) أي أجيبوا عن هذه الرؤيا وعبّروها لي ( إِنْ كُنْتُمْ لِلرُّءْيا تَعْبُرُونَ ) أي إذا كنتم تعرفون التعبير. وسمي تأويل الرؤيا تعبيرا يعبر بالإنسان من هذا الجانب ـ وهو جانب ظاهر الرؤيا ـ إلى ذلك قالُوا أَضْغاثُ أَحْلامٍ وَما نَحْنُ بِتَأْوِيلِ الْأَحْلامِ بِعالِمِينَ (44) وَقالَ الَّذِي نَجا مِنْهُما وَادَّكَرَ بَعْدَ أُمَّةٍ أَنَا أُنَبِّئُكُمْ بِتَأْوِيلِهِ فَأَرْسِلُونِ (45) الجانب ـ وهو جانب باطنه وأوله ـ مأخوذ من « العبور » من شاطئ النهر إلى الشاطئ الآخر.` },
            { text: "وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ يَٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ", tafsir: `` },
            { text: "قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَٰمِ بِعَٰلِمِينَ", tafsir: `أي قال الملأ في جواب الملك : إن رؤياك ( أَضْغاثُ أَحْلامٍ ) « أضغاث » جمع « ضغث » ، وهي قبضة الحشيش المختلط رطبها بيابسها ، و « أحلام » جمع « حلم » وهو المنام ، أي إن هذه الرؤيا إنما هي أحلام مختلطة لا يعرف تأويلها ، فكأنها إن كانت على وجه واحد عرف التأويل لها ، أما إذا اختلطت ، سمان وعجاف ، حيوان ونبات ، وتغلب الأضعف على الأقوى ـ بعكس القاعدة ـ فلا يعرف تأويلها ( وَما نَحْنُ بِتَأْوِيلِ الْأَحْلامِ ) التي هي من هذا القبيل ( بِعالِمِينَ ) وقد كان قولهم : « أضغاث أحلام » كمعذرة قدّموها إلى الملك ، نسبة لعدم علمهم بتأويلها.` },
            { text: "وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ", tafsir: `الساقي ( الَّذِي نَجا مِنْهُما ) من السجن ـ كلا الساقي والخباز ، اللذين سجنا مع يوسف ـ ( وَادَّكَرَ ) أصله « ذكر » ولما جيء إلى باب الانتقال ، صار « اذتكر » ، فأبدلت التاء دالا ، فصار « اذدكر » ، وأدغمت الذال في الدال لقرب مخرجهما ، فصار « ادّكر » ، أي : وتذكّر قصة يوسف عليه‌السلام ( بَعْدَ أُمَّةٍ ) أي بعد مدة ، فإن « الأمة » بمعنى الجماعة ، سواء كانت من الناس أو غيرهم أو من الزمان ، أو نحوه ، كأنه من « أمّ » بمعنى قصد ، فكأن الجماعة يدخل بعضها في بعض ويقصد بعضها بعضا ( أَنَا أُنَبِّئُكُمْ ) أي أخبركم ( بِتَأْوِيلِهِ ) أي تأويل هذه الرؤيا ( فَأَرْسِلُونِ ) يُوسُفُ أَيُّهَا الصِّدِّيقُ أَفْتِنا فِي سَبْعِ بَقَراتٍ سِمانٍ يَأْكُلُهُنَّ سَبْعٌ عِجافٌ وَسَبْعِ سُنْبُلاتٍ خُضْرٍ وَأُخَرَ يابِساتٍ لَعَلِّي أَرْجِعُ إِلَى النَّاسِ لَعَلَّهُمْ يَعْلَمُونَ (46) قالَ أي : فأرسلوني إلى يوسف ليأتي ويخبركم هو بتأويل الرؤيا ، أو : فأرسلوني إلى يوسف لأسأله تعبيرها وأخبركم بالجواب. فقد قال للملك : إن في الحبس رجلا فاضلا صالحا كثير الطاعة ، قد قصصت أنا والخباز عليه منامين فذكر تأويلهما ، فصدق في الكل ولم يخطئ ، فإن أذنت مضيت إليه وجئتك بالجواب منه. فأذن له الملك ، وجاء إلى يوسف عليه‌السلام ليخبره بتعبيرها ، قائلا : [47] يا ( يُوسُفُ أَيُّهَا الصِّدِّيقُ ) الكثير الصدق فيما تخبر به ، وإنما وصفه بهذا الوصف لأنه رأى صدقه في تأويل رؤياه ، ورؤيا زميله الخباز ( أَفْتِنا ) أي أعطنا الجواب ( فِي ) هذه الرؤيا ( سَبْعِ بَقَراتٍ سِمانٍ يَأْكُلُهُنَّ سَبْعٌ عِجافٌ ) وكان تقديم السمان ، مع أن مقتضى القاعدة أن يقول : « سبع بقرات عجاف يأكلن سبع سمان » ، لأجل إفادة أنه رأى السمان قبل العجاف ، كما أن التأويل أيضا كذلك ، فقد تقدمت السنين الخصبة ( وَسَبْعِ سُنْبُلاتٍ خُضْرٍ ) تلتف عليها ( وَ ) تغلبها ( أُخَرَ يابِساتٍ ) فما تأويل هذه الرؤيا ( لَعَلِّي أَرْجِعُ إِلَى النَّاسِ ) الملك وحاشية ( لَعَلَّهُمْ يَعْلَمُونَ ) التفسير ، أو لعلهم يعلمون فضلك فينقذوك من السجن. وإنما قال : « لعلي » لأن الإنسان يحتمل حيلولة الموت بينه وبين ما يقصده من المقاصد المستقبلة.` },
            { text: "يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ", tafsir: `` },
            { text: "قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ", tafsir: `يوسف عليه‌السلام في جواب الساقي : أما البقرات السبع العجاف تَزْرَعُونَ سَبْعَ سِنِينَ دَأَباً فَما حَصَدْتُمْ فَذَرُوهُ فِي سُنْبُلِهِ إِلاَّ قَلِيلاً مِمَّا تَأْكُلُونَ (47) ثُمَّ يَأْتِي مِنْ بَعْدِ ذلِكَ سَبْعٌ شِدادٌ يَأْكُلْنَ ما قَدَّمْتُمْ لَهُنَّ والسنابل اليابسات فهن السنون الجدبة ، وأما البقرات السبع السمان والسنابل السبع الخضر فإنهن سبع سنين مخصبات ذوات نعمة. أقول : كأن البقر والسنابل إشارتان إلى المأكل ، فإن الزرع والضرع من البقر والسنبل وجنسهما ، فقد أخبر عليه‌السلام بأن سبع سنين تكون مخصبة ثم تأتي سبع سنوات مجدبة يأكل الإنسان ما ادّخر في المخصبة ، ولذا التوت السنابل اليابسة على الخضر ، وأكلت البقرات الهزال البقرات السمان. ثم بيّن يوسف عليه‌السلام ما ينبغي لهم أن يعملوا تجاه هذا القحط الذي سيأتيهم بعد سبع سنين من الخصب ، فقال : ( تَزْرَعُونَ ) « خبر في معنى الإنشاء » ، أي ازرعوا ( سَبْعَ سِنِينَ دَأَباً ) أي متوالية بجهد وجد ، أو بمعنى « على دأبكم وعادتكم في الزراعة » ، فإن « دأب » يأتي بالمعنيين ( فَما حَصَدْتُمْ ) من الزرع الذي هو أكثر من كفايتكم ( فَذَرُوهُ ) أي دعوه ( فِي سُنْبُلِهِ ) لا تدوسوه ، بل اتركوه ليبقى أكثر ، ولئلّا يسرع إليه الفساد ، فإن الحبوب في سنبلها تبقى أكثر مدة ( إِلَّا قَلِيلاً مِمَّا تَأْكُلُونَ ) مما تحتاجون في نفس السنة ، فادخروه لأكلكم وحوائجكم.` },
            { text: "ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ", tafsir: `السبع سنين الخصبة ( سَبْعٌ ) من السنين ( شِدادٌ ) جمع « شديد » ، أي سنوات قحط وجدب صعاب على الناس تشتد عليهم لعدم الأكل والزرع والضرع ( يَأْكُلْنَ ) أي تلك السنوات الشدائد ( ما قَدَّمْتُمْ لَهُنَ ) ما أبقيتم من الحبوب ، لأجل تلك السنوات. إِلاَّ قَلِيلاً مِمَّا تُحْصِنُونَ (48) ثُمَّ يَأْتِي مِنْ بَعْدِ ذلِكَ عامٌ فِيهِ يُغاثُ النَّاسُ وَفِيهِ يَعْصِرُونَ (49) وإنما قال : « يأكلن » ليطابق رؤيا الملك « يأكلهن سبع عجاف » ومثل هذا التعبير شائع في المجاز ، قال : « أكل الدهر ما جمعت ومالي » . حكى في المجمع : عن زيد بن أسلم أن يوسف عليه‌السلام كان يصنع طعام اثنين فيقربه إلى رجل فيأكل نصفه ، حتى كان ذات يوم قربه إليه فأكله كله ، فقال : هذا أول يوم من السبع الشداد. أقول : ولا بعد في ذلك ، فإن الهواء من القحط ـ غير المصطنع ـ يتغير ويتطلب الجفاف والفناء ، فما يصيب الأرض ، يصيب الحيوان والإنسان. ( إِلَّا قَلِيلاً مِمَّا تُحْصِنُونَ ) استثناء من « يأكلن » أي أن السبع الشداد تنفق فيها جميع السنابل المحرزة إلا مقدار قليل مما أحصنتم وحفظتم فإنه يبقى ليكون بذرا للرخاء الذي يأتي بعد سنيّ القحط السبع.` },
            { text: "ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ", tafsir: `الذي ذكرنا من الأعوام الشداد ( عامٌ فِيهِ يُغاثُ النَّاسُ ) يمطرون ، فإن الغيث بمعنى المطر ( وَفِيهِ ) أي في ذلك العام ( يَعْصِرُونَ ) ما اعتادوا عصره من أنواع الفواكه في أوقات الخصب والرخاء كالعنب وغيره. وهذا يدل على شدة الخصب حتى أن الناس يتأنقون في المأكل والمشرب. ولعل الإتيان بهذه اللفظة بمناسبة كون الرجل السائل كان الساقي العاصر للملك ، وقد كان هذا إخبارا من يوسف عليه‌السلام بعلم الغيب خارجا عن المنام ، لأن رؤيا الملك اشتملت على السبع الشداد ، أما ماذا يكون بعدها ، فلم يكن في الرؤيا. وَقالَ الْمَلِكُ ائْتُونِي بِهِ فَلَمَّا جاءَهُ الرَّسُولُ قالَ ارْجِعْ إِلى رَبِّكَ فَسْئَلْهُ ما بالُ النِّسْوَةِ اللاَّتِي قَطَّعْنَ أَيْدِيَهُنَّ إِنَّ رَبِّي بِكَيْدِهِنَّ عَلِيمٌ (50) [51] ثم أن الساقي بعد ما علم التعبير من يوسف جاء الملك وأخبره أن الرجل السجين يقول هكذا في تعبير رؤياك ( وَ ) حينئذ ( قالَ الْمَلِكُ ) لمن حواليه ( ائْتُونِي بِهِ ) جيئوا إليّ بالسجين الذي عبّر الرؤيا ( فَلَمَّا جاءَهُ ) جاء يوسف ( الرَّسُولُ ) من قبل الملك ليخرجه من السجن ، أبى يوسف عليه‌السلام الخروج حتى تتبيّن براءته من التهمة التي قذفته بها زليخا وأنه أراد بها سوءا ، ف ( قالَ ) يوسف للرسول : ( ارْجِعْ إِلى رَبِّكَ ) سيدك الملك ( فَسْئَلْهُ ) أي اسأل منه ( ما بالُ النِّسْوَةِ اللَّاتِي قَطَّعْنَ أَيْدِيَهُنَ ) أي يتعرف الملك على حال تلك النسوة اللاتي قطّعن أيديهن بالسكاكين لمّا رأينني. وإنما خصهن بالذكر لأنهن كن شاهدات على زليخا أنها دعت يوسف إلى الفاحشة ، فقد سبق أنها قالت لهن : ( وَلَئِنْ لَمْ يَفْعَلْ ما آمُرُهُ لَيُسْجَنَنَّ ) . ومعنى « ما بال » أي ما شأنهن من تلك القصة. في بعض الأحاديث : إن الرسول صلى‌الله‌عليه‌وآله‌وسلم أظهر التعجب لأمرين من قصة يوسف ، الأول : أنه عبّر رؤيا الملك بدون أن يشترط ذلك على خروجه من السجن. الثاني : أنه لم يخرج من السجن بعد الأمر بإطلاقه حتى تظهر براءته. أقول : لعل يوسف لم يذكر امرأة العزيز تأدبا ، أو لأنه علم أنها لا تعترف بأنها صاحبة الجريمة ، بخلاف سائر النساء ، وكان ذكر « قطّعن أيديهن » لأنه خير مذكّر لهن بالقصة. ( إِنَّ رَبِّي بِكَيْدِهِنَّ عَلِيمٌ ) فهو سبحانه العالم بأنهن قد كدن قالَ ما خَطْبُكُنَّ إِذْ راوَدْتُنَّ يُوسُفَ عَنْ نَفْسِهِ قُلْنَ حاشَ لِلَّهِ ما عَلِمْنا عَلَيْهِ مِنْ سُوءٍ قالَتِ امْرَأَةُ الْعَزِيزِ الْآنَ حَصْحَصَ الْحَقُّ أَنَا راوَدْتُهُ عَنْ نَفْسِهِ ومكرن ـ وإنما سمي كيدا ، لأن أمرهن كان في خفاء ـ وإني بريء من القذف والتهمة. [52] ثم إن الرسول رجع إلى الملك ، وقال له ما طلبه يوسف عليه‌السلام ، فأرسل الملك إلى النسوة ودعاهن ، وقال لهن : ما شأنكن مع يوسف ؟ وما تعلمون من قصته وقصة زليخا ؟ ( قالَ ) الملك لهن : ( ما خَطْبُكُنَ ) أي ما شأنكن ( إِذْ راوَدْتُنَّ يُوسُفَ عَنْ نَفْسِهِ ) أي طلبتن انتزاع نفس يوسف ودعوته إلى أنفسكن ، فهل كان مائلا إلى ذلك ؟ ( قُلْنَ حاشَ لِلَّهِ ) أي تنزيها لله ، وأصله « حاشا » حذف الألف تخفيفا ، وهي كلمة تقال في موارد ، منها : في مقام تبرئة المتهم ، كأنه تعجّب من قدرة الله على خلق بشر عفيف وبريء مثله ( ما عَلِمْنا عَلَيْهِ مِنْ سُوءٍ ) فإنه بريء لم يكن مائلا إلى الشهوة وإنما نحن كن مجرمات. ولفظ « عليه » كأنه بسبب أن السوء يركب على المجرم. وكأن امرأة العزيز « زليخا » كانت من جملة النساء اللاتي استجوبهم الملك ف ( قالَتِ امْرَأَةُ الْعَزِيزِ الْآنَ حَصْحَصَ الْحَقُ ) أي ظهر الحق ، وهو براءة يوسف. قال بعضهم : « حصحص » اشتقاقه من « الحصة » أي بانت حصة الحق من حصة الباطل ، فظهر جليا واضحا لا لبس فيه ولا غموض ( أَنَا ) امرأة العزيز ( راوَدْتُهُ ) أي راودت يوسف ، راجعته واختلفت إليه ( عَنْ نَفْسِهِ ) لأسلب نفسه ، وأقضي وَإِنَّهُ لَمِنَ الصَّادِقِينَ (51) ذلِكَ لِيَعْلَمَ أَنِّي لَمْ أَخُنْهُ بِالْغَيْبِ وَأَنَّ اللهَ لا يَهْدِي كَيْدَ الْخائِنِينَ (52) معه الشهوة ( وَإِنَّهُ لَمِنَ الصَّادِقِينَ ) فيما قال ( هِيَ راوَدَتْنِي عَنْ نَفْسِي ) فأنا كاذبة في التهمة ، وهو صادق في براءته وكوني أنا المجرمة. [53] وهنا عاد الرسول إلى يوسف من السجن وأخبره باستجواب الملك للنساء ، وأنهن اعترفن ببراءته عليه‌السلام وأنهن المجرمات. فقال يوسف : ( ذلِكَ ) الذي طلبت من التثبّت في أمري ( لِيَعْلَمَ ) الملك ـ أو العزيز ، على تقدير كونه الوزير ـ ( أَنِّي لَمْ أَخُنْهُ بِالْغَيْبِ ) أي أني لم أخن الملك في غيابه بقصد السوء إلى زوجته ، وذكر « بالغيب » لبيان شدة وقع الخيانة إذا وقعت كذلك ، إذ خيانة المؤتمن أسوء من خيانة غيره ( وَأَنَّ اللهَ لا يَهْدِي كَيْدَ الْخائِنِينَ ) أي لا ينقذه ولا يوصله إلى مقصده. وهذا تنبيه على أن الخائن إن ستر أمره مدّة ، وهبّت الرياح نحوه أياما ، فإنه سيفضح وإن كيده سيفشل. وهناك احتمال أن يكون هذا من كلام زليخا ، تريد : إنما اعترفت ليظهر أني لا أخون يوسف وهو غائب في السجن بأن أنسب إليه الجريمة ، وكذلك ( ( وَما أُبَرِّئُ نَفْسِي ) (1) ، من تتمة كلامها. ( 1) يوسف : 54. الفهرس` },
            { text: "وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّٰتِى قَطَّعْنَ أَيْدِيَهُنَّ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌ", tafsir: `` },
            { text: "قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ قُلْنَ حَٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٰٔنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ", tafsir: `` },
            { text: "ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ", tafsir: `` },
            { text: "وَمَآ أُبَرِّئُ نَفْسِىٓ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ إِنَّ رَبِّى غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ", tafsir: `` },
            { text: "قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ إِنِّى حَفِيظٌ عَلِيمٌ", tafsir: `` },
            { text: "وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "وَلَأَجْرُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ", tafsir: `` },
            { text: "وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ", tafsir: `` },
            { text: "وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ", tafsir: `` },
            { text: "فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ", tafsir: `` },
            { text: "قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ", tafsir: `` },
            { text: "وَقَالَ لِفِتْيَٰنِهِ ٱجْعَلُوا۟ بِضَٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ", tafsir: `` },
            { text: "فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ", tafsir: `` },
            { text: "قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ فَٱللَّهُ خَيْرٌ حَٰفِظًا وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ", tafsir: `` },
            { text: "وَلَمَّا فَتَحُوا۟ مَتَٰعَهُمْ وَجَدُوا۟ بِضَٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ قَالُوا۟ يَٰٓأَبَانَا مَا نَبْغِى هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتْ إِلَيْنَا وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ذَٰلِكَ كَيْلٌ يَسِيرٌ", tafsir: `` },
            { text: "قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ", tafsir: `` },
            { text: "وَقَالَ يَٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍ وَٰحِدٍ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍ مُّتَفَرِّقَةٍ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ عَلَيْهِ تَوَكَّلْتُ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ", tafsir: `` },
            { text: "وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةً فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا وَإِنَّهُۥ لَذُو عِلْمٍ لِّمَا عَلَّمْنَٰهُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَٰرِقُونَ", tafsir: `` },
            { text: "قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ", tafsir: `` },
            { text: "قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍ وَأَنَا۠ بِهِۦ زَعِيمٌ", tafsir: `` },
            { text: "قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَٰرِقِينَ", tafsir: `` },
            { text: "قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَٰذِبِينَ", tafsir: `` },
            { text: "قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ كَذَٰلِكَ كِدْنَا لِيُوسُفَ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌ", tafsir: `` },
            { text: "قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُۥ مِن قَبْلُ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ قَالَ أَنتُمْ شَرٌّ مَّكَانًا وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ", tafsir: `` },
            { text: "قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذًا لَّظَٰلِمُونَ", tafsir: `` },
            { text: "فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّا قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ", tafsir: `` },
            { text: "ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَٰفِظِينَ", tafsir: `` },
            { text: "وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا وَإِنَّا لَصَٰدِقُونَ", tafsir: `` },
            { text: "قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ", tafsir: `` },
            { text: "وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌ", tafsir: `` },
            { text: "قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَٰلِكِينَ", tafsir: `` },
            { text: "قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ", tafsir: `` },
            { text: "يَٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَٰفِرُونَ", tafsir: `` },
            { text: "فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَٰعَةٍ مُّزْجَىٰةٍ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ", tafsir: `` },
            { text: "قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَٰهِلُونَ", tafsir: `` },
            { text: "قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِى قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَٰطِـِٔينَ", tafsir: `` },
            { text: "قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ يَغْفِرُ ٱللَّهُ لَكُمْ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ", tafsir: `` },
            { text: "ٱذْهَبُوا۟ بِقَمِيصِى هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ", tafsir: `` },
            { text: "وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ لَوْلَآ أَن تُفَنِّدُونِ", tafsir: `` },
            { text: "قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَٰلِكَ ٱلْقَدِيمِ", tafsir: `` },
            { text: "فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًا قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ", tafsir: `` },
            { text: "قَالُوا۟ يَٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ", tafsir: `` },
            { text: "قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ", tafsir: `` },
            { text: "فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ", tafsir: `` },
            { text: "وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًا وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأْوِيلُ رُءْيَٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّا وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ إِنَّ رَبِّى لَطِيفٌ لِّمَا يَشَآءُ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ", tafsir: `` },
            { text: "رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ تَوَفَّنِى مُسْلِمًا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ", tafsir: `` },
            { text: "ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ", tafsir: `` },
            { text: "وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ", tafsir: `` },
            { text: "وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ", tafsir: `` },
            { text: "وَكَأَيِّن مِّنْ ءَايَةٍ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ", tafsir: `` },
            { text: "وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ", tafsir: `` },
            { text: "أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَٰشِيَةٌ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ", tafsir: `` },
            { text: "قُلْ هَٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى وَسُبْحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ", tafsir: `` },
            { text: "وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ٱتَّقَوْا۟ أَفَلَا تَعْقِلُونَ", tafsir: `` },
            { text: "حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ", tafsir: `` },
            { text: "لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌ لِّأُو۟لِى ٱلْأَلْبَٰبِ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ", tafsir: `` }
        ]
    }
});
